/* 教材正文：集合框架篇 / 集合体系、List、ArrayList 与 LinkedList、HashMap、Set、迭代器与队列、专用容器 */
(function () {
  'use strict';
  var T = window.JAVA_TEXTBOOK || (window.JAVA_TEXTBOOK = {});

  T['collections'] = {
    meta: '本章约 6300 字 · 建议 35 分钟 · 配套流程图与 5 道习题',
    blocks: [
      { h: '1.1 为什么学集合' },
      { p: '在学集合之前，我们存一批数据只能用数组。数组的缺点非常明确：长度在创建时就固定，装满了没法自动变大，装少了又浪费内存；删除中间一个元素要自己写循环搬移；两个数组之间没有任何共同接口，换个存储结构，调用方的代码就得跟着重写。更麻烦的是数组不检查类型，一个 Object[] 里可以同时塞字符串、整数和自定义对象，取出来时必须自己判断和强转，写错一个类型就在运行期抛异常。' },
      { p: '集合框架（Collections Framework）就是 JDK 为“存一组对象”这件事提供的一整套标准答案。它用一组接口描述“能做什么”，用多个实现类提供“怎么做”，再用泛型把类型检查提前到编译期。你写 List&lt;String&gt;，编译器就保证里面只有字符串；你声明 List 接口，以后把 ArrayList 换成 LinkedList，调用方一行都不用改。' },
      { p: '这一章先建立全局地图：集合框架分成哪两大家族，List 的契约是什么，常用方法有哪些坑，遍历和排序该怎么做。把这些打牢，后面几章讲 ArrayList、LinkedList、HashMap、Set 和队列时，你才知道每个细节挂在地图的哪个位置，而不是死记零散结论。' },
      { h: '1.2 两大家族：Collection 与 Map' },
      { p: '集合框架的顶层不是一个接口，而是两条并行的线。第一条以 <code>Iterable</code> 为起点，下面是 <code>Collection</code>，再往下分成 <code>List</code>、<code>Set</code>、<code>Queue</code> 三条分支，它们存的都是“单个元素”。第二条是 <code>Map</code>，存的是“键到值”的映射，它不属于 Collection，也不继承 Iterable，所以不能直接对 Map 写增强 for。' },
      { table: { head: ['接口', '是否有序', '能否重复', '核心特征', '常见实现'], rows: [
        ['List', '有，按插入位置', '可以', '支持下标访问', 'ArrayList、LinkedList'],
        ['Set', '取决于实现', '不可以', '用于去重、判重', 'HashSet、TreeSet'],
        ['Queue', '有，按入队顺序', '可以', '从队头取、队尾放', 'ArrayDeque、PriorityQueue'],
        ['Map', '取决于实现', 'key 不可重复', '键值对映射', 'HashMap、TreeMap']
      ] } },
      { p: '注意表格里 Set 和 Map 的“有序”写的是“取决于实现”，因为 HashSet 和 HashMap 根本不保证顺序，而 LinkedHashSet、TreeSet、LinkedHashMap、TreeMap 又各自维护了不同的顺序。判断一个容器有没有顺序，不能只看接口，要看具体实现类。' },
      { note: '<b>最容易记错的一点：</b>Map 不是 Collection 的子接口。List、Set、Queue 都继承 Collection，而 Map 独立存在。面试里问“Collection 和 Map 的区别”，答的就是这条。' },
      { p: '除了接口和实现类，集合框架还有两个常被忽略的成员：一是 <code>Collections</code> 工具类，提供 sort、reverse、shuffle、unmodifiableList 等静态方法；二是 <code>Iterable</code> 与 <code>Iterator</code> 这套遍历协议，增强 for 能遍历集合，靠的就是它。工具类后面带 s，接口不带 s，写代码时不要混。' },
      { p: '接口和实现分离，是集合框架最重要的设计。你声明 <code>List&lt;String&gt; list = new ArrayList&lt;&gt;()</code>，调用方只依赖 List 提供的 add、get、remove 这些能力，完全不关心底层是数组还是链表。某天发现某个方法成了性能瓶颈，把右边换成 <code>new LinkedList&lt;&gt;()</code> 就行，左边和所有调用代码一个字都不用改。这种“面向接口编程”的习惯，比记住任何一个类的 API 都更有长期价值。' },
      { p: '学习集合时还要建立“契约”意识：接口文档写明的行为，才是你能依赖的东西。比如 List 承诺有序、可重复，ArrayList 承诺随机访问快，但并没有承诺“扩容时不会复制”。如果代码依赖了实现细节，换版本或换实现就可能出问题。面试和真实故障里，很多“集合的坑”本质上都是把实现细节当成了接口契约。' },
      { h: '1.3 泛型：把类型检查提前' },
      { p: '集合在设计之初是装 Object 的，什么问题都能往里放，代价是取出来必须强转。泛型（Generics）解决了这个问题：<code>List&lt;String&gt;</code> 明确告诉编译器“这个列表只装字符串”，add 别的类型直接编译失败，get 出来也不需要强转。' },
      { lang: 'java', code: 'import java.util.ArrayList;\nimport java.util.List;\n\npublic class GenericDemo {\n    public static void main(String[] args) {\n        List<String> names = new ArrayList<>();\n        names.add("Tom");\n        names.add("Anna");\n        // names.add(100);        // 编译错误：需要 String\n\n        String first = names.get(0);   // 不需要强转\n        System.out.println(first.toUpperCase());\n    }\n}', title: 'GenericDemo.java' },
      { out: 'TOM' },
      { p: '泛型有一个硬限制：类型参数只能是引用类型，不能是基本类型。写 <code>List&lt;int&gt;</code> 编译不过，必须写 <code>List&lt;Integer&gt;</code>。当你执行 <code>list.add(1)</code> 时，编译器自动调用 <code>Integer.valueOf(1)</code> 把 int 装箱成对象；执行 <code>int n = list.get(0)</code> 时再自动拆箱。装箱不是零成本，循环里频繁装箱会产生大量临时对象。' },
      { p: '还有一个必须知道的事实：泛型在运行期会被“擦除”。<code>List&lt;String&gt;</code> 和 <code>List&lt;Integer&gt;</code> 在 JVM 眼里都是 List，所以不能写 <code>new T[]</code>，不能写 <code>obj instanceof List&lt;String&gt;</code>，也不能用泛型类型做方法重载。擦除换来的是向后兼容：老代码不用改，新代码享受编译期检查。' },
      { p: '泛型还有一个常见的进阶话题：通配符。<code>List&lt;? extends Number&gt;</code> 表示“元素是 Number 或它的子类”的列表，适合只读，不能往里 add（除了 null），因为编译器不知道具体是 Integer 还是 Double；<code>List&lt;? super Integer&gt;</code> 表示“元素类型是 Integer 或它的父类”，适合写入。记不住方向时用助记：extends 管读，super 管写。初学阶段先把 <code>List&lt;String&gt;</code> 这种具体类型用熟，遇到 API 里的通配符再回来查。' },
      { h: '1.4 List 的三条契约' },
      { p: 'List 的契约只有三条，但每条都影响你选实现：第一，有序，元素按插入位置排列，每个元素都有下标；第二，可重复，同一个值可以出现多次；第三，支持下标访问，get、set、add(index, e)、remove(index) 都基于位置。' },
      { p: 'List 允许存 null，也允许存重复的 null。判断“包含”用的是 equals，不是 ==，所以自定义对象想被 contains 正确识别，必须重写 equals。这一点在 Set 和 Map 里同样成立，只是 List 不去重，影响没那么明显。' },
      { table: { head: ['实现类', '底层结构', '随机访问', '中间插入删除', '线程安全', '适用场景'], rows: [
        ['ArrayList', '动态数组', 'O(1)', 'O(n)', '否', '绝大多数列表场景'],
        ['LinkedList', '双向链表', 'O(n)', '定位后 O(1)', '否', '频繁头尾增删、当双端队列'],
        ['Vector', '动态数组', 'O(1)', 'O(n)', '是（全表锁）', '遗留代码，不推荐新项目'],
        ['CopyOnWriteArrayList', '写时复制数组', 'O(1)', 'O(n)', '是（写锁）', '读多写极少的并发场景']
      ] } },
      { p: '初学者最常见的选型错误，是觉得“链表插入快”就一律用 LinkedList。这个结论只在“已经定位到插入点”时成立；如果还要先按下标找到位置，定位本身就是 O(n)。绝大多数业务是“追加 + 遍历 + 偶尔按下标取”，ArrayList 的连续内存和 CPU 缓存友好性反而更快。具体对比放在下一章。' },
      { p: '评估一个 List 操作的代价，要区分“定位”和“改动”两件事。按下标定位，ArrayList 是 O(1)，LinkedList 是 O(n)；在定位好的位置改动，ArrayList 要搬移后续元素，LinkedList 只改几个引用。所谓“LinkedList 插入快”，前提是你已经通过迭代器走到了那个位置，而不是先 get(index) 再插入。把这两步拆开看，绝大多数性能疑问都能自己回答。' },
      { h: '1.5 创建 List 的五种写法' },
      { p: '第一种是标准写法：<code>List&lt;String&gt; list = new ArrayList&lt;&gt;();</code>。左边声明接口，右边创建实现，尖括号里留空让编译器推断。这是最推荐的写法，因为以后换实现只改右边一处。' },
      { p: '第二种是带初始容量：<code>new ArrayList&lt;&gt;(100)</code>。注意它只是把底层数组一次分配到能装 100 个，size 仍然是 0，不是“创建了 100 个元素”。如果你已经知道大概要装多少条，提前给容量能避免多次扩容复制。' },
      { p: '第三种是复制另一个集合：<code>new ArrayList&lt;&gt;(otherList)</code>。它会按 otherList 的迭代顺序把元素复制进来，得到的是一个独立的新列表，修改新列表不影响原列表。' },
      { p: '第四种是 <code>Arrays.asList("a", "b")</code>。它返回的是一个“固定长度”的列表，底层直接包装原数组：可以用 set 修改某个位置，但不能 add 或 remove，否则抛 UnsupportedOperationException。很多人把它当成普通 List 用，一 add 就炸。' },
      { p: '第五种是 <code>List.of("a", "b")</code>（JDK 9 及以上）。它返回真正不可变的列表，任何修改方法都抛 UnsupportedOperationException，而且不允许 null 元素。适合定义常量表、返回值快照。如果需要一个可变的副本，再套一层 <code>new ArrayList&lt;&gt;(List.of(...))</code>。' },
      { lang: 'java', code: 'import java.util.ArrayList;\nimport java.util.Arrays;\nimport java.util.List;\n\npublic class CreateList {\n    public static void main(String[] args) {\n        List<String> fixed = Arrays.asList("a", "b");\n        fixed.set(0, "A");              // 允许：修改元素\n        System.out.println(fixed);      // [A, b]\n        // fixed.add("c");              // UnsupportedOperationException\n\n        List<String> immutable = List.of("a", "b");\n        // immutable.set(0, "A");       // UnsupportedOperationException\n\n        List<String> copy = new ArrayList<>(immutable);\n        copy.add("c");                  // 副本可以修改\n        System.out.println(copy);       // [a, b, c]\n    }\n}', title: 'CreateList.java' },
      { out: '[A, b]\n[a, b, c]' },
      { note: '<b>双括号初始化是个坑：</b><code>new ArrayList&lt;&gt;() {{ add("a"); }}</code> 会生成一个匿名内部类，持有外部类引用，可能造成内存泄漏，序列化也会出问题。想要一行初始化，用 <code>new ArrayList&lt;&gt;(List.of("a"))</code>。' },
      { p: '容量大于 size 是正常状态，不是内存泄漏。ArrayList 扩容后不会自动缩容，删掉大量元素，底层数组可能仍然很大；如果确认之后不会再增长，可以调用 <code>trimToSize()</code> 把数组缩到刚好等于 size。反过来，如果能预估规模，用 <code>ensureCapacity(n)</code> 或带初始容量的构造器一次分配够，能减少多次复制。以默认容量 10 为例，装到第 11 个元素时就要新建数组并复制，数据量大时这些复制会累积成可观的开销。不过这两个方法都是性能优化手段，普通业务不写也完全正确，不要为了“优化”到处调用，更不要在没有测量数据时凭感觉调参。' },
      { h: '1.6 增删改查与下标边界' },
      { p: 'List 的方法不多，但重载和返回值容易记混。add(e) 追加到尾部，返回 boolean；add(index, e) 插入到指定位置，没有返回值；get(index) 取元素；set(index, e) 替换并返回旧值；remove(index) 删除并返回被删元素；remove(Object) 删除第一个相等元素，返回 boolean；size() 返回元素个数；isEmpty() 判断是否为空；contains 和 indexOf 都依赖 equals；clear() 清空但保留容量。' },
      { lang: 'java', code: 'import java.util.ArrayList;\nimport java.util.List;\n\npublic class ListBasics {\n    public static void main(String[] args) {\n        List<String> list = new ArrayList<>();\n        list.add("Java");\n        list.add("Go");\n        list.add(1, "Rust");          // 插到下标 1，Go 后移\n        list.set(0, "Kotlin");        // 替换，返回旧值 Java\n\n        System.out.println(list);           // [Kotlin, Rust, Go]\n        System.out.println(list.get(1));    // Rust\n        System.out.println(list.size());    // 3\n        System.out.println(list.indexOf("Go")); // 2\n    }\n}', title: 'ListBasics.java' },
      { out: '[Kotlin, Rust, Go]\nRust\n3\n2' },
      { flow: ['调用 add(1, "Rust")', '检查 0 ≤ index ≤ size', '确保容量足够', '下标 1 及之后的元素后移一位', '写入新元素', 'size 加一'] },
      { p: '最经典的陷阱是 remove 的重载。对于 <code>List&lt;Integer&gt;</code>，<code>remove(1)</code> 匹配的是 remove(int index)，删的是下标 1；想删“值为 1 的元素”，必须写 <code>remove(Integer.valueOf(1))</code>。编译器先做基本类型匹配，再做装箱匹配，所以字面量 1 永远优先当下标。' },
      { lang: 'java', code: 'import java.util.ArrayList;\nimport java.util.List;\n\npublic class RemoveTrap {\n    public static void main(String[] args) {\n        List<Integer> nums = new ArrayList<>(List.of(10, 20, 30));\n        nums.remove(1);                     // 删除下标 1 的元素 20\n        System.out.println(nums);           // [10, 30]\n\n        nums.remove(Integer.valueOf(10));   // 删除元素 10\n        System.out.println(nums);           // [30]\n    }\n}', title: 'RemoveTrap.java' },
      { out: '[10, 30]\n[30]' },
      { note: '<b>记住这条规则：</b>参数是 int 就走下标删除，参数是对象就走内容删除。集合里存 Integer 时，这个区别足以让代码删错数据，而且不报错，最难排查。' },
      { p: '除了单个元素的增删改查，List 还继承了 Collection 的批量方法：<code>addAll</code> 把一个集合全部追加进来，<code>containsAll</code> 判断是否包含全部，<code>removeAll</code> 删除与另一个集合的交集，<code>retainAll</code> 只保留交集。批量方法通常比循环单次操作快，因为实现类可以一次性扩容、一次性搬移；数据量大时这个差距会非常明显。但要注意 removeAll 和 retainAll 会改变原列表，如果传入的集合就是它自己，行为要按具体实现确认，不要写出依赖未定义行为的代码。另外，这些方法判断相等仍然依赖 equals，自定义对象没重写 equals 时，交集和去重都不会按你期望的语义工作。' },
      { p: 'List 的下标从 0 开始，合法范围是 <code>0 &lt;= index &lt; size()</code>。但有一个例外：<code>add(index, e)</code> 允许 index 等于 size，表示追加到末尾；get、set、remove 则必须严格小于 size。传负数或超过范围，都会抛 <code>IndexOutOfBoundsException</code>，这是运行时异常，编译器不会提前提醒。' },
      { p: '写循环时，条件里的 <code>list.size()</code> 每次都会重新计算，但它的开销极小，不要为了“优化”把它提到循环外。真正危险的是在循环体里增删元素，导致 size 变化、下标错位。比如正向遍历删除元素，会跳过被删元素的下一个，甚至越界。' },
      { p: '空列表调用 get(0) 同样越界。取第一个元素前，先判断 <code>!list.isEmpty()</code>，或者用 <code>Optional</code> 包装。不要用“捕获异常再返回默认值”的方式做正常流程控制，异常的开销远大于一次判断。' },
      { h: '1.7 四种遍历方式' },
      { p: '第一种是普通 for 循环，用下标访问，适合需要知道位置的场景，比如“每隔一个删一个”。第二种是增强 for（for-each），代码最简洁，底层编译成迭代器，适合只读遍历。第三种是显式使用 Iterator，适合遍历中删除元素。第四种是 <code>forEach</code> 配合 lambda（JDK 8+），适合把处理逻辑抽成方法引用。' },
      { lang: 'java', code: 'import java.util.ArrayList;\nimport java.util.Iterator;\nimport java.util.List;\n\npublic class Traverse {\n    public static void main(String[] args) {\n        List<String> list = new ArrayList<>(List.of("Java", "Go", "Rust"));\n\n        for (int i = 0; i < list.size(); i++) {\n            System.out.print(list.get(i) + " ");\n        }\n        System.out.println();\n\n        for (String s : list) {\n            System.out.print(s.toUpperCase() + " ");\n        }\n        System.out.println();\n\n        Iterator<String> it = list.iterator();\n        while (it.hasNext()) {\n            System.out.print(it.next().length() + " ");\n        }\n        System.out.println();\n\n        list.forEach(s -> System.out.print(s.charAt(0) + " "));\n    }\n}', title: 'Traverse.java' },
      { out: 'Java Go Rust \nJAVA GO RUST \n4 2 4 \nJ G R ' },
      { p: '增强 for 虽然好看，但它拿到的迭代器是“只读视角”：遍历过程中只要集合结构发生变化（add、remove、clear），下一次调用 next 就会抛 <code>ConcurrentModificationException</code>。注意这是单线程也会发生的异常，不是“并发”两个字误导的那样只在多线程出现。正确做法是用 Iterator.remove、removeIf，或者先收集要删的元素再统一删除，第 5 章会详细拆解。' },
      { p: 'lambda 里的 forEach 还有一个限制：不能修改外部局部变量。Java 要求 lambda 捕获的局部变量是 effectively final，想在遍历中累加，只能用数组成员、AtomicInteger，或者干脆用 stream 的 sum。这不是集合的限制，是 lambda 的规则。' },
      { p: '遍历中删除元素的正确姿势有三种。第一，显式拿到 Iterator，用 <code>it.remove()</code> 删除，它会把迭代器的期望修改次数同步更新，不会触发异常。第二，JDK 8 的 <code>list.removeIf(x -&gt; 条件)</code>，一行完成过滤，内部仍然走迭代器，代码最短。第三，如果必须按下标删除，就从后往前遍历，避免删掉元素后下标前移导致漏删。最不推荐的是“先收集要删的元素，再调用 removeAll”，它多一次遍历和一份临时集合，但胜在语义清晰，数据量不大时完全可以接受。' },
      { h: '1.8 subList 是视图，不是副本' },
      { p: '<code>subList(from, to)</code> 返回的是原列表的一段“视图”，左闭右开：包含 from，不包含 to。它没有复制元素，读写都直接作用在原列表上。所以对视图 set，原列表会变；对原列表做结构修改，再访问视图就会抛 ConcurrentModificationException。' },
      { lang: 'java', code: 'import java.util.ArrayList;\nimport java.util.List;\n\npublic class SubListView {\n    public static void main(String[] args) {\n        List<String> all = new ArrayList<>(List.of("a", "b", "c", "d"));\n        List<String> part = all.subList(1, 3);   // [b, c]\n        part.set(0, "B");\n        System.out.println(all);                 // [a, B, c, d]\n\n        all.add("e");                            // 修改了原列表结构\n        System.out.println(part);                // ConcurrentModificationException\n    }\n}', title: 'SubListView.java' },
      { out: '[a, B, c, d]\nException in thread "main" java.util.ConcurrentModificationException' },
      { p: '如果确实想要一份独立的子列表，用 <code>new ArrayList&lt;&gt;(all.subList(1, 3))</code> 复制出来。还有一个常用技巧：<code>list.subList(2, list.size()).clear()</code> 可以一次性删除尾部一段，比循环 remove 高效得多，因为它只搬移一次。' },
      { p: '把集合转成数组用 <code>toArray</code>。无参版本返回 Object[]，强转容易出错；推荐 <code>toArray(new String[0])</code>，类型安全，JDK 11 之后还可以用 <code>toArray(String[]::new)</code>。反过来，<code>Arrays.asList</code> 和 <code>List.of</code> 都能从数组或可变参数创建列表，但前者是固定长度视图，后者完全不可变，别混用。' },
      { h: '1.9 排序与 Collections 工具类' },
      { p: 'List 自己提供了 <code>sort(Comparator)</code>，JDK 8 之前用 <code>Collections.sort(list)</code>，两者底层都是归并排序的变体（TimSort），是稳定排序：比较结果相等的元素保持原有相对顺序。稳定这件事在“先按分数排、再按姓名排”的多级排序里非常重要。' },
      { p: '自然顺序要求元素实现 <code>Comparable</code>。String 按字典序，Integer 按数值，自定义类如果不实现 Comparable，直接 sort 会抛 ClassCastException。更灵活的方式是传 Comparator，用 <code>Comparator.comparing(...)</code> 声明排序键，还能 reversed、thenComparing 串成多级规则。' },
      { lang: 'java', code: 'import java.util.ArrayList;\nimport java.util.Comparator;\nimport java.util.List;\n\npublic class SortDemo {\n    public static void main(String[] args) {\n        List<String> names = new ArrayList<>(List.of("Tom", "Anna", "Bob"));\n        names.sort(Comparator.comparing(String::length));\n        System.out.println(names);   // [Tom, Bob, Anna]\n\n        names.sort(Comparator.comparing(String::length).reversed()\n                .thenComparing(Comparator.naturalOrder()));\n        System.out.println(names);   // [Anna, Bob, Tom]\n    }\n}', title: 'SortDemo.java' },
      { out: '[Tom, Bob, Anna]\n[Anna, Bob, Tom]' },
      { p: '注意输出：第一轮按长度升序，Tom 和 Bob 都是 3，保持原来的相对顺序，所以是 Tom、Bob；第二轮先按长度降序，Anna 最长排第一，Tom 和 Bob 长度相同，再用自然序升序，Bob 在 Tom 前。Comparator 链式调用的顺序就是从主到次。' },
      { p: 'Collections 还提供 reverse、shuffle、swap、max、min、frequency、binarySearch。binarySearch 的前提是列表已经按同一规则排好序，否则结果未定义；它不是线性扫描，而是二分，返回找到的下标或“插入点取负再减一”。这些方法都是静态工具，不改变集合的类型。' },
      { p: '自定义类排序时，最容易忽略的是“比较结果与 equals 保持一致”。如果 compareTo 返回 0 但 equals 返回 false，放进 TreeSet 会被当成重复元素丢掉，放进 HashMap 又不会；这种不一致会让同一份数据在不同容器里表现不同，极难排查。BigDecimal 就是经典例子：equals 要求精度也相同，compareTo 只比较数值，1.0 和 1.00 的 equals 是 false、compareTo 是 0。用 BigDecimal 做 TreeSet 或 TreeMap 的 key 时，一定要想清楚你要的是“数值相等”还是“完全相等”。' },
      { p: 'Comparator 最好抽成静态常量或工具方法反复使用，不要每次排序都临时 new 一个匿名类；比较器本身无状态，复用不会带来线程安全问题。比较器里也不要写有副作用的逻辑，排序算法会多次调用 compare，调用次数取决于数据规模和分布，副作用次数不可预测。Comparator.comparing 默认不允许 null，字段可能为空时要用 <code>nullsFirst</code> 或 <code>nullsLast</code> 显式处理，否则排序到一半抛 NullPointerException。另外，List.sort 是原地排序，会直接修改列表顺序；需要保留原顺序时，先复制一份再排。' },
      { h: '1.10 线程安全与选型' },
      { p: 'ArrayList 和 LinkedList 都不是线程安全的。多个线程同时 add，可能出现元素丢失、size 与实际不符，甚至内部数组状态错乱。JDK 早期用 Vector 解决，但它的每个方法都加 synchronized，锁粒度太大，单线程性能也受影响，现在只存在于遗留代码里。' },
      { p: '需要线程安全时有三条路：一是 <code>Collections.synchronizedList(list)</code> 包一层，读写都加同一把锁，简单但并发度低；二是 <code>CopyOnWriteArrayList</code>，写时复制整个数组，读完全不加锁，适合读多写极少的监听器列表；三是 <code>ConcurrentHashMap</code> 这类并发容器，但那是 Map，不是 List。' },
      { p: '还有一种常见误解：用了 synchronizedList 就万事大吉。它的迭代器仍然不是线程安全的，遍历时必须自己 <code>synchronized (list)</code> 包住整个循环，否则别的线程一改，照样抛 ConcurrentModificationException。并发容器的“安全”指的是单次操作原子，不是把多次操作合成事务。' },
      { p: '线程安全不只是“方法会不会同时执行”，还包括“一个线程的修改，另一个线程能不能看见”。synchronizedList 的每个方法都在同一把锁上同步，锁的释放与获取建立了 happens-before 关系，所以拿到锁的线程能看到之前的修改。CopyOnWriteArrayList 则靠一个 volatile 修饰的内部数组引用：写操作加锁并替换整个数组，读操作直接读当前引用，永远不加锁。代价是读到的可能是旧快照，迭代器也不会抛 ConcurrentModificationException，因为它遍历的是创建迭代器那一刻的数组。' },
      { p: '选容器时先问三个问题：数据量大概多少、读多还是写多、需不需要顺序。数据量小，任何实现在性能上都够用，优先选语义最简单的；读多写少且集合很小，CopyOnWriteArrayList 很合适；需要按下标频繁访问，ArrayList 几乎总是对的；只有在明确测量出瓶颈、且瓶颈确实来自头部增删时，才轮到 LinkedList。过早优化选型，往往换来更复杂的代码和更差的缓存表现。' },
      { h: '1.11 初学者最常见的七个错误' },
      { list: [
        '把 <code>Arrays.asList</code> 的结果当可变列表，一 add 就抛 UnsupportedOperationException。',
        '对 <code>List&lt;Integer&gt;</code> 写 <code>remove(1)</code>，以为删值 1，实际删的是下标 1。',
        '在增强 for 里调用 <code>list.remove(x)</code>，触发 ConcurrentModificationException。',
        '以为 <code>subList</code> 是副本，改视图后发现原列表也变了。',
        '用 <code>==</code> 比较两个 String 元素，应该用 equals。',
        '给 <code>new ArrayList&lt;&gt;(100)</code> 后直接 <code>get(0)</code>，忘了 size 还是 0。',
        '自定义对象没重写 equals，contains 和 indexOf 永远找不到“内容相同”的元素。'
      ] },
      { p: '这七条错误里，有五条会在运行期才暴露，而且往往不报错、只是结果不对。建议你在练习时故意把每种错误写一遍，观察异常类型和堆栈信息：是编译错误、下标越界，还是并发修改异常，定位方式完全不同。把异常的名字和触发条件对应起来，比背 API 列表有用得多，后面读别人的代码时也能一眼看出风险点。' },
      { h: '1.12 本章小结' },
      { list: [
        '集合框架分两支：Collection（List/Set/Queue）和 Map，Map 不属于 Collection。',
        'List 有序、可重复、支持下标；常用实现是 ArrayList 和 LinkedList。',
        '泛型把类型检查提前到编译期，集合只能装引用类型，基本类型靠装箱。',
        'remove(int) 删下标，remove(Object) 删内容，Integer 列表尤其要小心。',
        'subList、Arrays.asList 都是视图，List.of 才是真正不可变。',
        '遍历中删元素用 Iterator.remove 或 removeIf，不要用增强 for 直接删。',
        '默认选 ArrayList；需要线程安全时按读写比例选择包装或 CopyOnWriteArrayList。'
      ] },
      { h: '1.13 常见追问' },
      { list: [
        '<b>问：数组和 List 该怎么选？</b><br>答：看长度是否在创建时就确定，以及是否需要频繁增删。长度固定、元素是基本类型、追求零对象开销和极致访问速度时用数组，它没有包装、没有边界检查之外的开销，也方便与原生接口交换数据。需要不定长扩容、丰富的查找与视图 API、泛型带来的类型安全时用 List。经验做法是内部实现用数组换性能，对外暴露接口时用 List 换便利。',
        '<b>问：List 能存 null 吗？</b><br>答：ArrayList 与 LinkedList 都允许存 null，甚至能存多个，<code>contains(null)</code> 返回 true，<code>remove(null)</code> 删掉第一个出现的 null。真正的限制来自实现类：<code>List.of</code> 与 <code>Arrays.asList</code> 之后的结构性修改都会失败，前者连 null 元素本身都不接受，会直接抛 NullPointerException。团队里更该关心的是语义：能存 null 不等于该存 null，可空引用会让调用方到处判空。',
        '<b>问：为什么 <code>List&lt;int&gt;</code> 编译不过？</b><br>答：泛型参数必须是引用类型，基本类型没有对应的类，所以只能写 <code>List&lt;Integer&gt;</code>。这不只是语法限制：泛型在实现上做了类型擦除，运行期元素都当 Object 存，基本类型无法作为 Object 引用。代价是每次读写都可能发生装箱与拆箱，循环里往 <code>List&lt;Integer&gt;</code> 反复累加时，这个开销会被放大，数量级大时要考虑 primitive 专用容器或直接改用数组。',
        '<b>问：ArrayList 的容量和 size 有什么区别？</b><br>答：容量是底层数组的长度，size 是实际存了多少个元素；容量总是大于等于 size。无参构造时容量为 0，第一次 add 才分配成默认的 10，所以「默认容量 10」其实是首次写入时才落地的。容量只影响扩容时机，不影响遍历和下标范围，越界判断用的始终是 size。想减少扩容就把预估数量传给构造器，传多了只是占内存，不会影响正确性。',
        '<b>问：为什么增强 for 里删除元素会抛异常？</b><br>答：增强 for 会被编译成迭代器遍历，集合内部维护一个 modCount，每次结构性修改都加一；迭代器在每次取元素前后比对期望值与实际值，发现不一致就抛 ConcurrentModificationException。真正的问题不是「多线程」，而是遍历期间绕过了迭代器去改结构。<b>要点</b>是改用 <code>iterator.remove()</code> 或直接 <code>list.removeIf(...)</code>，它们会同步更新 modCount。',
        '<b>问：ArrayList、LinkedList、Vector 三个实现怎么选？</b><br>答：默认选 ArrayList，随机访问快、内存连续、扩容策略温和，绝大多数场景它都是最优解。需要频繁在头部或尾部增删、或者当队列用时选 ArrayDeque，它比 LinkedList 更快也更省内存，LinkedList 只在需要同时从两端大量插入、且几乎不按下标访问时才有位置。Vector 的方法全是同步的，每次操作都有锁开销，属于历史遗留，新代码不该再用，需要并发就用 CopyOnWriteArrayList 或加显式锁。'
      ] },

      { h: '1.14 自测与练习' },
      { ol: [
        '创建 <code>List&lt;Integer&gt;</code>，依次加入 10、20、30，分别用 remove(1) 和 remove(Integer.valueOf(20)) 删除，打印两次结果。<details class="tb-ans"><summary>参考答案</summary><div class="ans-body"><pre class="tb-ans-code" data-lang="java">import java.util.ArrayList;\nimport java.util.List;\n\npublic class RemoveTwo {\n  public static void main(String[] args) {\n    List&lt;Integer> a = new ArrayList&lt;>(List.of(10, 20, 30));\n    a.remove(1);                        // 按下标\n    System.out.println(a);              // [10, 30]\n    List&lt;Integer> b = new ArrayList&lt;>(List.of(10, 20, 30));\n    b.remove(Integer.valueOf(1));       // 按元素\n    System.out.println(b);              // [10, 20, 30]\n    List&lt;Integer> c = new ArrayList&lt;>(List.of(10, 20, 30));\n    try {\n      c.remove(20);\n    } catch (IndexOutOfBoundsException e) {\n      System.out.println("remove(20) 选了下标重载");\n    }\n  }\n}</pre><b>要点</b>：remove(int) 与 remove(Object) 是重载，实参是 int 时编译器优先选下标版本，哪怕元素本身就是 Integer；要删元素得先装箱成 Integer，或者把值存进 Integer 变量再传。</div></details>',
        '用四种方式遍历同一个列表，统计每种写法输出的元素个数。<details class="tb-ans"><summary>参考答案</summary><div class="ans-body"><pre class="tb-ans-code" data-lang="java">import java.util.Iterator;\nimport java.util.List;\n\npublic class Walk4 {\n  public static void main(String[] args) {\n    List&lt;String> l = List.of("a", "b", "c");\n    int n1 = 0, n2 = 0, n3 = 0;\n    for (int i = 0; i &lt; l.size(); i++) n1++;\n    for (String s : l) n2++;\n    Iterator&lt;String> it = l.iterator();\n    while (it.hasNext()) {\n      it.next();\n      n3++;\n    }\n    long n4 = l.stream().count();\n    System.out.println(n1 + " " + n2 + " " + n3 + " " + n4);\n  }\n}</pre><b>要点</b>：增强 for 和显式迭代器编译后是同一套 iterator 调用，两者性能一致；只有普通 for 加 get(i) 在 LinkedList 上会退化成 O(n^2)。遍历中改结构只能用 it.remove()。</div></details>',
        '构造一个包含 6 个元素的列表，取 <code>subList(1, 4)</code>，修改视图的第一个元素，再打印原列表。<details class="tb-ans"><summary>参考答案</summary><div class="ans-body"><pre class="tb-ans-code" data-lang="java">import java.util.ArrayList;\nimport java.util.ConcurrentModificationException;\nimport java.util.List;\n\npublic class SubView {\n  public static void main(String[] args) {\n    List&lt;Integer> l = new ArrayList&lt;>(\n        List.of(1, 2, 3, 4, 5, 6));\n    List&lt;Integer> v = l.subList(1, 4);\n    v.set(0, 99);\n    System.out.println(l);   // [1, 99, 3, 4, 5, 6]\n    v.clear();\n    System.out.println(l);   // [1, 5, 6]\n    l.add(7);\n    try {\n      System.out.println(v.size());\n    } catch (ConcurrentModificationException e) {\n      System.out.println("视图已失效");\n    }\n  }\n}</pre><b>要点</b>：subList 是原列表的视图不是拷贝，set/clear 都会改原表；结构一改旧视图立刻失效，再访问抛 ConcurrentModificationException。要独立副本写 new ArrayList&lt;>(l.subList(1, 4))。</div></details>',
        '把 <code>Arrays.asList("a", "b")</code> 赋给 List，尝试 add 和 set，记录各自的异常。<details class="tb-ans"><summary>参考答案</summary><div class="ans-body"><pre class="tb-ans-code" data-lang="java">import java.util.Arrays;\nimport java.util.List;\n\npublic class AsListTwo {\n  public static void main(String[] args) {\n    List&lt;String> l = Arrays.asList("a", "b");\n    l.set(0, "z");\n    System.out.println(l);          // [z, b]\n    try {\n      l.add("c");\n    } catch (UnsupportedOperationException e) {\n      System.out.println("add 不支持");\n    }\n    try {\n      l.remove(0);\n    } catch (UnsupportedOperationException e) {\n      System.out.println("remove 不支持");\n    }\n  }\n}</pre><b>要点</b>：Arrays.asList 返回 Arrays$ArrayList，底层就是传进来的数组，长度固定：set 可以，add/remove 抛 UnsupportedOperationException；要可变就包一层 new ArrayList&lt;>(Arrays.asList(...))，或用 List.of 直接拿不可变集合。</div></details>',
        '自定义一个 Student 类（姓名、分数），放进 List，分别按分数升序和姓名降序排序。<details class="tb-ans"><summary>参考答案</summary><div class="ans-body"><pre class="tb-ans-code" data-lang="java">import java.util.ArrayList;\nimport java.util.Comparator;\nimport java.util.List;\n\npublic class StuSort {\n  record Stu(String name, int score) {}\n\n  public static void main(String[] args) {\n    List&lt;Stu> l = new ArrayList&lt;>(List.of(\n        new Stu("Ann", 88), new Stu("Bob", 95),\n        new Stu("Cid", 88)));\n    l.sort(Comparator.comparingInt(Stu::score));\n    System.out.println(l);\n    l.sort(Comparator.comparing(Stu::name).reversed());\n    System.out.println(l);\n  }\n}</pre><b>要点</b>：List.sort 原地排序、返回 void，别写 l = l.sort(...)；降序要把 reversed() 加在整个比较器后面，挂在 key 提取器上（Stu::name.reversed）编译不过；两次 sort 会互相覆盖，要同时生效用 thenComparing。</div></details>'
      ] },
      { note: '<b>练习建议：</b>做练习时打开调试器，在 add、remove、subList 这几行打断点，观察 size、底层数组长度和 modCount 的变化，比只盯正确结果更能建立边界感。' }
    ]
  };

T['arraylist-linkedlist'] = {
    meta: '本章约 6400 字 · 建议 35 分钟 · 配套扩容流程图与 5 道习题',
    blocks: [
      { h: '2.1 为什么同样的 List 会差几十倍' },
      { p: '上一章我们说 List 有三个实现，其中 ArrayList 和 LinkedList 最常用。它们都实现了同一个接口，add、get、remove 的方法签名一模一样，写出来的调用代码也一模一样。但底层的存储方式完全不同：一个用连续数组，一个用双向链表。这个差异不会影响“能不能运行”，却会在数据量上来之后，决定程序是几十毫秒还是几秒钟。' },
      { p: '很多初学者背过一句结论：“ArrayList 查询快，LinkedList 增删快。”这句话只对了一半，而且在真实项目里经常把人带偏。LinkedList 的“增删快”有严格前提：你必须已经站在要操作的那个节点上。如果还要先按下标找到它，定位过程本身就是 O(n)，总代价并没有比 ArrayList 好。' },
      { p: '这一章我们把两个类拆开看：内部有哪些字段、一次 add 到底做了什么、扩容为什么是 1.5 倍、get 为什么一个 O(1) 一个 O(n)、迭代器如何发现“遍历时被修改”。最后给出一张选型表，并手写一个迷你动态数组，把“扩容”和“搬移”从概念变成你能写出来的代码。' },
      { h: '2.2 ArrayList 内部长什么样' },
      { p: 'ArrayList 的字段很少，核心只有两个：一个 <code>Object[] elementData</code> 数组，用来真正存放元素；一个 <code>int size</code>，记录当前放了多少个元素。注意“数组长度”和“size”不是一回事：数组长度是容量（capacity），size 是实际元素个数，容量永远大于等于 size。' },
      { p: '为什么用 Object[] 而不是 E[]？因为泛型在运行期会被擦除，JVM 不知道 E 具体是什么类型，没法创建泛型数组。ArrayList 内部统一用 Object[] 存，取出来时再由编译器在调用处插入强制转换。这也是为什么往 ArrayList 里放错类型，编译期能拦住，但通过反射或原始类型绕过去，运行期仍可能抛 ClassCastException。' },
      { p: 'ArrayList 采用懒初始化：<code>new ArrayList&lt;&gt;()</code> 时并不会立刻分配一个长度为 10 的数组，而是先指向一个共享的空数组常量，等到第一次 add 才真正分配。这样创建大量空列表时不会浪费内存。默认容量 10 这个数字，是在第一次扩容时才用上的。' },
      { lang: 'java', code: '// JDK 8 源码简化版，字段与方法名保持原样\npublic class ArrayList<E> {\n    private static final int DEFAULT_CAPACITY = 10;\n    private static final Object[] EMPTY_ELEMENTDATA = {};\n    private static final Object[] DEFAULTCAPACITY_EMPTY_ELEMENTDATA = {};\n\n    transient Object[] elementData;   // 真正存元素的数组\n    private int size;                 // 实际元素个数\n\n    public ArrayList() {\n        this.elementData = DEFAULTCAPACITY_EMPTY_ELEMENTDATA;\n    }\n}', title: 'ArrayListFields.java' },
      { p: '如果你在构造时传入容量 <code>new ArrayList&lt;&gt;(100)</code>，它会直接分配长度为 100 的数组，size 仍然是 0。传 0 则使用 EMPTY_ELEMENTDATA，第一次 add 时只扩到 1，而不是默认的 10。这些细节平时不用管，但面试问“ArrayList 默认容量是多少、什么时候分配”时，答“10，第一次 add 时分配”才是完整的。' },
      { p: '除了单个 add，addAll 也会触发扩容，而且它是一次性算好需要多少容量，再决定扩不扩、扩到多少。如果一次要加入 1000 个元素，而当前容量只有 10，它会直接扩到足够装下 1010 个，而不是反复按 1.5 倍扩十几次。所以批量添加通常比循环单个 add 更高效，这也是集合工具方法存在的重要意义：把“多次小操作”合并成“一次大操作”。' },
      { p: 'ArrayList 的继承关系也值得看一眼：它继承 AbstractList，实现了 List、RandomAccess、Cloneable、Serializable。AbstractList 提供了大部分方法的默认实现，ArrayList 只重写需要优化的部分；RandomAccess 是空接口，仅用于标记“支持快速随机访问”；Cloneable 和 Serializable 分别支持浅拷贝和序列化。看懂这行声明，就能猜到这个类大致具备哪些能力。' },
      { h: '2.3 按下标取值为什么是 O(1)' },
      { p: '数组在内存里是一段连续空间，每个元素占固定大小。知道起始地址、元素大小和下标，就能用“起始地址 + 下标 × 元素大小”直接算出目标地址，一次内存访问就拿到元素。这就是随机访问 O(1) 的来源，也是 ArrayList 的 get 和 set 能这么快的原因。' },
      { p: '连续内存还有一个隐性好处：CPU 缓存友好。CPU 读内存时不是一个字节一个字节读，而是一次读一整条缓存行（通常 64 字节）。你顺序遍历数组，后面的元素很可能已经在缓存里，访问速度接近寄存器；链表节点散落在堆的各处，每次跳转都可能是一次缓存未命中，实际耗时远高于“只数指针跳了几次”的理论值。' },
      { p: '所以 benchmark 里经常出现“理论复杂度一样，ArrayList 却快好几倍”的现象。复杂度只描述增长趋势，不描述常数；而常数在真实数据规模下往往更重要。理解这一点，你就不会为了一个想象中的 O(1) 插入，把整个结构换成缓存极不友好的链表。' },
      { p: '比较两个结构不能只看操作次数，还要看内存布局。ArrayList 的元素引用连续排列，遍历时 CPU 预取器能提前把后面的数据拉进缓存；LinkedList 的节点是 new 出来的独立对象，地址不连续，每次 next 都可能跳到内存的另一处，缓存命中率低。数据量大时，这个差距会盖过复杂度上的理论优势。' },
      { h: '2.4 一次 add 引发的扩容' },
      { p: '往尾部 add 一个元素，看起来只有一行，内部却分几步：先检查容量够不够，不够就扩容；然后把元素放到 <code>elementData[size]</code>；最后 size 加一。扩容是这里面唯一可能很慢的一步，因为它要申请一个更大的新数组，把旧数组的元素全部复制过去，再把引用指向新数组。' },
      { flow: ['调用 add(e)', '计算需要的最小容量 size + 1', '容量足够则直接写入', '不够则计算新容量 old + old / 2', '创建新数组并复制旧元素', '写入元素，size 加一'] },
      { p: '新容量不是翻倍，而是 <code>oldCapacity + (oldCapacity &gt;&gt; 1)</code>，也就是约 1.5 倍。10 扩到 15，15 扩到 22，22 扩到 33。为什么不翻倍？1.5 倍在“减少扩容次数”和“减少空间浪费”之间更平衡；Vector 用的是翻倍，空间浪费更明显。扩容后如果计算出的容量还不够（比如一次 addAll 进来很多元素），就直接采用需要的最小容量。' },
      { p: '扩容虽然要复制，但它是“均摊 O(1)”：从空列表连续 add n 个元素，总复制次数大约是 n 的常数倍，平均到每次 add 就是常数时间。所以不要因为“扩容要复制”就不敢用 ArrayList，真正要避免的是在循环里不断触发扩容。如果能预估元素个数，构造时给一个初始容量，或者先 <code>ensureCapacity(n)</code>，就能把这部分开销降到最低。' },
      { note: '<b>常见误解：</b>“ArrayList 每次 add 都要扩容。”——不是。只有 size 达到容量时才扩，而且一次扩到 1.5 倍，之后很多次 add 都不需要再动数组。' },
      { p: '扩容时旧数组并不会立刻消失：新数组分配好、元素复制完、引用切换之后，旧数组才变成不可达，等待 GC 回收。所以在扩容的那一瞬间，堆里同时存在新旧两个数组，内存峰值大约是平时的 1.5 到 2.5 倍。数据量特别大时，这个峰值可能导致 OutOfMemoryError。解决办法不是不用 ArrayList，而是提前估算容量，避免在内存紧张时突然扩容；同时也要避免在循环里反复创建大列表，让旧数组来不及回收。' },
      { p: '内存占用也要算总账。ArrayList 的冗余来自扩容：容量 1.5 倍增长，最坏情况下有约三分之一的空间是空的，但可以通过 trimToSize 收回。LinkedList 的冗余来自每个节点的对象头和两个引用，元素本身越小，额外开销占比越高。存小对象时，LinkedList 的内存可能是 ArrayList 的两三倍。' },
      { p: '补充一句关于内存的实践：如果你的列表会长期存活、元素数量稳定，可以在启动时用带容量的构造器一次分配好，运行期就几乎没有扩容动作；如果是短生命周期的临时列表，默认构造即可，JVM 的分配和回收都很快，不必过度设计。' },
      { h: '2.5 中间插入与删除的代价' },
      { p: '<code>add(index, e)</code> 分三步：检查下标是否在 0 到 size 之间；确保容量足够；把 index 及之后的所有元素整体后移一位，腾出位置再写入。后移用 <code>System.arraycopy</code> 完成，它是本地方法，比手写 for 循环快得多，但仍然是 O(n)，移动的元素个数是 size - index。' },
      { p: '<code>remove(index)</code> 相反：先取出要删的元素，把 index 之后的元素整体前移一位，把最后一个位置置为 null（帮助 GC），size 减一。删除尾部元素不需要搬移，是 O(1)；删除头部要搬移全部元素，是 O(n)。所以“ArrayList 删除慢”也要看位置，尾部删除其实很快。' },
      { p: '这也解释了一个常见优化：如果需要频繁删除头部，不要用 <code>list.remove(0)</code>，考虑用 <code>ArrayDeque</code> 或 <code>LinkedList</code>；如果只是偶尔删一次，O(n) 完全无所谓，不要为了理论复杂度把代码改复杂。先测量，再优化，是使用集合时最该养成的习惯。' },
      { p: '还有两个方法容易和 add/remove 混淆。set(index, e) 只替换元素，不改变结构，所以不会增加 modCount，也不会让迭代器失效；remove(Object) 则要先遍历找到第一个 equals 相等的元素，再按下标删除，整体是 O(n)，而且它和 remove(int) 构成重载，传 Integer 时尤其容易选错。理解每个方法“改不改结构”，是判断迭代器会不会失效的关键。' },
      { h: '2.6 LinkedList 的节点结构' },
      { p: 'LinkedList 的每个元素不是直接放在数组里，而是包装成一个 Node 对象。Node 里存三样东西：元素本身 item、指向下一个节点的 next、指向上一个节点的 prev。链表本身只保存两个引用：first 指向头节点，last 指向尾节点，再加一个 size。' },
      { lang: 'java', code: 'private static class Node<E> {\n    E item;\n    Node<E> next;\n    Node<E> prev;\n\n    Node(Node<E> prev, E element, Node<E> next) {\n        this.item = element;\n        this.next = next;\n        this.prev = prev;\n    }\n}\n\n// LinkedList 的三个字段\ntransient int size = 0;\ntransient Node<E> first;\ntransient Node<E> last;', title: 'NodeStruct.java' },
      { p: '因为每个节点都保存前后两个引用，所以从任意一个节点出发，都能 O(1) 找到它的前驱和后继。在“已经拿到节点”的前提下，插入和删除只需要改几个引用，不需要搬移任何元素。这就是链表“增删快”的真正含义，也是它和数组最本质的区别。' },
      { p: '为什么是双向链表而不是单向？因为删除一个节点需要它的前驱：单向链表删除时必须从头再走一遍找前驱，O(n)；双向链表通过 prev 直接拿到前驱，O(1)。LinkedList 还实现了 Deque，所以它同时有 offerFirst、pollLast、push、pop 这些方法，既能当列表，也能当队列和栈。功能多不等于合适，同一个类承担的语义越多，调用方越容易用错方法，具体怎么选后面再说。' },
      { p: '代价是每个元素都要额外创建一个 Node 对象。一个 Node 对象头大约 16 字节，加上 item、next、prev 三个引用（压缩指针下各 4 字节），大约 28 到 32 字节，此外还有对象对齐的填充。存 100 万个 Integer，ArrayList 主要是一块 4MB 左右的引用数组，LinkedList 则要额外创建 100 万个 Node，内存和 GC 压力都大得多。' },
      { p: 'node(index) 的折半优化经常被面试问到：它先判断 index 是否小于 size 的一半，是就从 first 往后走 next，否则从 last 往前走 prev。这样最多走 size/2 步，常数减半，但增长趋势仍然是线性。不要因为看到“折半”就以为它是 O(log n)，它没有像数组那样直接算出地址，只是少走了一半路。数据量翻倍，耗时仍然翻倍。' },
      { h: '2.7 LinkedList 的 O(1) 与 O(n)' },
      { p: 'LinkedList 的 <code>addFirst</code>、<code>addLast</code>、<code>removeFirst</code>、<code>removeLast</code> 都是 O(1)，因为 first 和 last 直接指向头尾，改几个引用就完成。它实现 Deque 接口，天生适合当双端队列和栈用。但 <code>add(index, e)</code> 和 <code>get(index)</code> 不是 O(1)。' },
      { p: '原因在于按下标找节点必须从头或尾一步步走。LinkedList 做了一个小优化：<code>node(index)</code> 会判断 index 离哪一头更近，小于 size/2 就从头往后走，否则从尾往前走。所以访问中间元素大约走 size/2 步，复杂度仍是 O(n)，只是常数小了一半。' },
      { lang: 'java', code: 'import java.util.LinkedList;\nimport java.util.List;\n\npublic class LinkedListOps {\n    public static void main(String[] args) {\n        List<String> linked = new LinkedList<>(List.of("a", "b", "c", "d"));\n        System.out.println(linked.get(2));      // c，从头走 2 步\n\n        LinkedList<String> deque = new LinkedList<>(linked);\n        deque.addFirst("start");\n        deque.addLast("end");\n        System.out.println(deque);              // [start, a, b, c, d, end]\n        System.out.println(deque.removeFirst()); // start\n        System.out.println(deque.removeLast());  // end\n    }\n}', title: 'LinkedListOps.java' },
      { out: 'c\n[start, a, b, c, d, end]\nstart\nend' },
      { p: '注意 <code>add(index, e)</code> 的真实代价：先调用 node(index) 定位，O(n)；再改引用插入，O(1)。总复杂度是 O(n)，不是 O(1)。很多“LinkedList 插入比 ArrayList 快”的实验，其实是只测了“已经定位到节点”的情况，或者数据量太小、ArrayList 的搬移成本还没显现。真实业务里按下标插入，LinkedList 往往更慢。' },
      { p: 'JVM 默认开启压缩指针，对象里的引用占 4 字节而不是 8 字节，这让 LinkedList 的额外开销小了一些，但每个 Node 仍然是一个独立对象，至少带 12 到 16 字节的对象头。ArrayList 只需要一块数组对象加一个 length 字段，元素越少，两者的相对差距越大。另外，ArrayList 存 Integer 时只存引用，Integer 对象本身仍然在堆上，这部分开销两者都有，比较时不要重复计算。' },
      { h: '2.8 遍历方式与 O(n²) 陷阱' },
      { p: '这是 LinkedList 最著名的性能坑：用普通 for 循环加 <code>get(i)</code> 遍历。每一次 get(i) 都要从头走 i 步，累加起来是 0+1+2+…+(n-1)，也就是 O(n²)。数据量一万时是五千万次节点跳转，十万时是五十亿次，程序会直接卡死。' },
      { lang: 'java', code: 'import java.util.LinkedList;\nimport java.util.List;\n\npublic class LinkedListLoop {\n    public static void main(String[] args) {\n        List<Integer> list = new LinkedList<>();\n        for (int i = 0; i < 10000; i++) {\n            list.add(i);\n        }\n\n        long sum = 0;\n        for (int i = 0; i < list.size(); i++) {   // 错误：O(n²)\n            sum += list.get(i);\n        }\n        System.out.println(sum);\n\n        long sum2 = 0;\n        for (int n : list) {                      // 正确：O(n)\n            sum2 += n;\n        }\n        System.out.println(sum2 == sum);\n    }\n}', title: 'LinkedListLoop.java' },
      { out: '49995000\ntrue' },
      { p: '增强 for 之所以快，是因为它只调用一次 <code>iterator()</code>，之后每次 <code>next()</code> 直接拿当前节点的 next，全程 O(n)。同理，<code>forEach</code>、stream、<code>listIterator</code> 都是线性遍历。记住一条硬规则：只要集合可能是 LinkedList，就绝不要用“下标 + get”遍历，改用迭代器或增强 for。' },
      { p: '反过来，ArrayList 用哪种遍历都可以，普通 for 甚至略快，因为少了迭代器对象的创建和 hasNext 调用。写通用工具方法时，如果参数类型是 List 而不知道具体实现，一律用增强 for，既安全又清晰。不要为了“可能的性能”写死下标循环，那是在给未来的自己埋雷。' },
      { p: '迭代器的 remove 不是简单转调 list.remove。它会先检查 lastRet 是否合法、modCount 是否仍然等于 expectedModCount，然后调用 list.remove(lastRet)，再把 lastRet 置为 -1，并把 expectedModCount 同步成新的 modCount。所以连续调用两次 remove 会抛 IllegalStateException，因为第一次之后已经没有“刚访问过的元素”可删。' },
      { h: '2.9 迭代器与 fail-fast' },
      { p: 'ArrayList 和 LinkedList 的迭代器都遵循同一套 fail-fast 机制。集合内部有一个 <code>modCount</code>，记录结构被修改的次数（add、remove、clear 会加一，set 不会）。创建迭代器时，它把当前的 modCount 存进 <code>expectedModCount</code>；每次 next 前比较两者，不相等就立刻抛 ConcurrentModificationException。' },
      { p: '这套机制的目的是“尽早暴露错误”，而不是保证并发安全。它是单线程也会触发的：你在增强 for 里调用 list.remove，modCount 加一，迭代器还拿着旧值，下一次 next 就抛异常。正确做法是调用迭代器自己的 remove，它会在删除后同步更新 expectedModCount。' },
      { p: '还有一个容易忽略的点：fail-fast 不保证一定触发。Java 文档明确说它是最佳努力，不能依赖它做正确性判断。多线程环境下，可能刚好没检测到，也可能读到脏数据。要并发修改，应该用并发容器或自己加锁，而不是指望异常来兜底。' },
      { h: '2.10 选型：LinkedList 还剩哪些场景' },
      { p: '在真实项目里，LinkedList 的出现频率远低于教科书。绝大多数“需要 List”的场景，ArrayList 都是默认答案：随机访问多、遍历多、内存更省、缓存更友好。只有两种情况值得考虑 LinkedList：一是把它当 Deque 用，需要频繁在头尾插入删除；二是你已经持有节点引用，需要在节点旁边 O(1) 插入。' },
      { p: '但即便是当队列用，<code>ArrayDeque</code> 通常也比 LinkedList 更好：它用循环数组实现，没有每个节点的对象开销，头尾操作同样是 O(1)，还避免了 LinkedList 的缓存不友好。JDK 官方文档也推荐用 ArrayDeque 实现栈和队列。所以更准确的说法是：默认 ArrayList，队列和栈用 ArrayDeque，LinkedList 主要用于教学、面试和少数特殊场景。' },
      { table: { head: ['需求', '首选', '理由'], rows: [
        ['通用列表，读多写少', 'ArrayList', '随机访问快、内存省、缓存友好'],
        ['频繁头尾增删', 'ArrayDeque', 'O(1) 且无节点开销'],
        ['栈（后进先出）', 'ArrayDeque', 'push/pop 语义清晰，比 Stack 快'],
        ['已知节点旁插入', 'LinkedList', '改引用即可，O(1)'],
        ['需要线程安全', 'CopyOnWriteArrayList 或加锁', '按读写比例选择'],
        ['需要按值快速查找', 'HashSet / HashMap', 'List 的 contains 是 O(n)']
      ] } },
      { table: { head: ['维度', 'ArrayList', 'LinkedList'], rows: [
        ['底层结构', '连续 Object 数组', '双向链表节点'],
        ['随机访问 get(i)', 'O(1)', 'O(n)，从近的一端走'],
        ['尾部追加 add(e)', '均摊 O(1)', 'O(1)'],
        ['头部插入 add(0, e)', 'O(n)，整体后移', 'O(1)'],
        ['中间插入 add(i, e)', 'O(n)，搬移后半段', 'O(n)，先定位再插入'],
        ['按下标删除', 'O(n)，搬移后半段', 'O(n)，先定位再删'],
        ['内存开销', '较低，有容量冗余', '较高，每节点额外对象头'],
        ['缓存友好度', '高，连续内存', '低，节点分散']
      ] } },
      { p: 'LinkedList 允许存 null，ArrayDeque 不允许，这是少数 LinkedList 仍有优势的细节。但 ArrayDeque 的 push/pop/offer/poll 都是 O(1)，没有节点对象开销，整体更快。JDK 文档明确建议用 ArrayDeque 代替 Stack，也建议用它实现队列。除非你的 API 必须返回 LinkedList，或者确实需要存 null，否则没有理由优先选 LinkedList。选择容器时，“哪个类功能多”不是标准，“哪个结构匹配访问模式”才是。' },
      { p: 'JDK 里有一个标记接口 RandomAccess，ArrayList 实现了它，LinkedList 没有。Collections 工具类会据此选择遍历策略：对支持随机访问的列表用下标循环，对不支持的用迭代器。你自己写通用方法时也可以照做：if (list instanceof RandomAccess) 用 for，否则用增强 for。这不是必须的优化，但它体现了 JDK 设计者用“标记接口”表达能力的思路，也解释了为什么同样一个 sort，对不同 List 会走不同路径。' },
      { p: '最后给一个工程上的判断标准：如果一段代码里出现了 LinkedList，先问“我真的测量过吗”。没有测量数据的选型，多半是被“链表增删快”这句话影响。把 ArrayList 用到极致，再在确实需要的地方换 ArrayDeque，通常能得到更简单、更快、更好维护的代码。数据结构没有绝对的好坏，只有和访问模式匹不匹配。' },
      { h: '2.11 手写一个 MiniArrayList' },
      { p: '看懂源码最好的方式是自己写一遍。下面这个迷你版本只实现 add、get、remove、size，但保留了 ArrayList 最核心的三件事：容量不足时按 1.5 倍扩容、用 System.arraycopy 搬移元素、删除后把空位置 null 帮助 GC。' },
      { lang: 'java', code: 'public class MiniArrayList<E> {\n    private Object[] data = new Object[10];\n    private int size;\n\n    public void add(E e) {\n        if (size == data.length) {\n            int newCap = data.length + (data.length >> 1);\n            Object[] bigger = new Object[newCap];\n            System.arraycopy(data, 0, bigger, 0, size);\n            data = bigger;\n        }\n        data[size++] = e;\n    }\n\n    public E get(int index) {\n        if (index < 0 || index >= size) {\n            throw new IndexOutOfBoundsException("index: " + index);\n        }\n        return (E) data[index];\n    }\n\n    public E remove(int index) {\n        E old = get(index);\n        int moved = size - index - 1;\n        if (moved > 0) {\n            System.arraycopy(data, index + 1, data, index, moved);\n        }\n        data[--size] = null;\n        return old;\n    }\n\n    public int size() {\n        return size;\n    }\n\n    public static void main(String[] args) {\n        MiniArrayList<String> list = new MiniArrayList<>();\n        for (int i = 0; i < 12; i++) {\n            list.add("v" + i);\n        }\n        list.remove(0);\n        System.out.println(list.size());\n        System.out.println(list.get(0));\n        System.out.println(list.get(10));\n    }\n}', title: 'MiniArrayList.java' },
      { out: '11\nv1\nv11' },
      { p: '逐行看几个关键点。构造时分配 10 个位置；add 第 11 个元素时触发扩容，newCap 等于 10 + 5 = 15，复制前 10 个元素，再把新元素放到下标 10；remove(0) 把下标 1 到 10 的元素整体前移一位，最后把下标 10 置 null，size 变成 11。get 先做边界检查再强转，这就是 ArrayList 的全部核心逻辑。' },
      { p: '写完之后可以故意改几个地方验证理解：把 1.5 倍改成 2 倍，观察扩容次数；把 remove 里的 arraycopy 删掉，观察元素错位；把 data[--size] = null 删掉，用内存分析工具看对象是否无法回收。这种“破坏性实验”比对照着源码读一遍有效得多。' },
      { p: '手写实现时，编译器会提示“未经检查的强制转换”，因为把 Object 强转成 E 在运行期无法验证。这正是泛型擦除的代价：ArrayList 源码里也用 SuppressWarnings 压掉这类警告。生产代码不要随意模仿这种强转，但在教学实现里，它让你直观看到“泛型只是编译期的语法糖，运行时全是 Object”。' },
      { h: '2.12 本章小结' },
      { list: [
        'ArrayList 是连续数组 + size，默认容量 10，第一次 add 时才分配。',
        '扩容按约 1.5 倍增长，需要复制旧元素，均摊到每次 add 仍是 O(1)。',
        'ArrayList 的 get/set 是 O(1)，中间插入删除要搬移元素，是 O(n)。',
        'LinkedList 是双向链表，头尾操作 O(1)，按下标访问和插入都要先定位，是 O(n)。',
        'LinkedList 不要用 get(i) 遍历，会退化成 O(n²)，用增强 for 或迭代器。',
        '遍历中删元素用 Iterator.remove 或 removeIf，modCount 不一致会触发 fail-fast。',
        '默认选 ArrayList；队列和栈用 ArrayDeque；LinkedList 只在特定场景使用。'
      ] },
      { p: '还有一个常被忽略的实践：不要在循环条件里反复调用 list.size() 以外的高开销方法。size() 本身是 O(1)，但如果你写的是 list.contains(x) 放在循环条件里，每次都是 O(n)，嵌套起来就是 O(n²)。把与循环变量无关的结果提前算好，是比换容器更通用的优化手段。' },
      { h: '2.13 常见追问' },
      { list: [
        '<b>问：ArrayList 的默认容量到底是多少？</b><br>答：字段上的默认常量是 10，但无参构造并不立刻分配数组，而是共享一个空数组，直到第一次 add 才把它换成容量为 10 的数组。所以「默认容量 10」是首次写入之后才成立的事实。用 <code>new ArrayList&lt;&gt;(n)</code> 指定容量时则立刻分配 n 个位置，适合已知规模的批量导入，能省掉前面几次扩容和数组复制。',
        '<b>问：扩容为什么选 1.5 倍而不是 2 倍？</b><br>答：这是扩容次数与空间浪费的折中。倍数越大，达到目标规模所需的复制次数越少，但平均闲置空间越多；2 倍时数组往往有一半位置空着，1.5 倍在同样次数下闲置更少，还能让释放掉的旧数组有机会被后续分配复用，这一点对长期运行的服务很重要。代价是需要更多次复制，不过复制总成本仍然保持线性，可以接受。',
        '<b>问：ArrayList 能存 null 吗？</b><br>答：能，而且可以存多个。<code>contains(null)</code> 返回 true，<code>remove(null)</code> 只删掉第一个 null，<code>indexOf(null)</code> 返回第一个 null 的位置。允许存 null 是历史设计，不代表该用；业务代码里存进 null，后续每次取值都要判空，容易漏。真正依赖「不允许 null」的语义时用 <code>List.of</code>，它在写入时就抛 NullPointerException，把约定提前暴露。',
        '<b>问：为什么说 LinkedList 插入是 O(1)？</b><br>答：前提是「已经站在那个节点上」。LinkedList 的 add 只是改几个引用，不涉及复制，所以是常数时间；但按下标插入要先从头部或尾部走一遍找位置，这段是 O(n)，中间位置平均要走一半长度。同时按下标取值也是 O(n)，因为它必须顺着链表逐个跳。所以用 LinkedList 时应当通过迭代器或首尾方法操作，绝不要在循环里写 get(i)。',
        '<b>问：ArrayList 线程安全吗？</b><br>答：不安全。多线程同时 add 可能让两个线程读到同一个 size，都往同一个下标写，结果是元素丢失；扩容期间一个线程还可能继续往已被替换的旧数组里写。要并发写用 CopyOnWriteArrayList（写时复制，适合读多写少），或者用 <code>Collections.synchronizedList</code> 包一层并在遍历时手动加锁，也可以干脆换成线程私有列表最后合并。',
        '<b>问：遍历时 set 会触发 fail-fast 吗？</b><br>答：不会。fail-fast 的判断依据是 modCount，它只在结构性修改（增、删、扩容引起的变化）时递增；<code>set</code> 只是替换某个位置的值，长度不变，因此 modCount 不变，迭代继续进行。但要注意这并不意味着安全：替换会改变元素内容，依赖快照语义的逻辑仍可能算出错误结果，多线程下还可能出现读到半成品对象的情况。'
      ] },

      { h: '2.14 自测与练习' },
      { ol: [
        '分别用 ArrayList 和 LinkedList 存 10 万个整数，用增强 for 求和，比较耗时并解释差异来源。<details class="tb-ans"><summary>参考答案</summary><div class="ans-body"><pre class="tb-ans-code" data-lang="java">import java.util.ArrayList;\nimport java.util.LinkedList;\nimport java.util.List;\n\npublic class SumTwo {\n  static long sum(List&lt;Integer> l) {\n    long s = 0;\n    for (int v : l) s += v;\n    return s;\n  }\n\n  public static void main(String[] args) {\n    int n = 100_000;\n    List&lt;Integer> a = new ArrayList&lt;>();\n    List&lt;Integer> b = new LinkedList&lt;>();\n    for (int i = 0; i &lt; n; i++) {\n      a.add(i);\n      b.add(i);\n    }\n    sum(a);\n    sum(b);\n    long t0 = System.nanoTime();\n    sum(a);\n    long t1 = System.nanoTime();\n    sum(b);\n    long t2 = System.nanoTime();\n    long msA = (t1 - t0) / 1_000_000;\n    long msB = (t2 - t1) / 1_000_000;\n    System.out.println("ArrayList " + msA);\n    System.out.println("LinkedList " + msB);\n  }\n}</pre><b>要点</b>：增强 for 走迭代器，两种容器都是 O(n)，差的只是常数：LinkedList 每个元素多一个 Node（两个引用），内存不连续、缓存命中差。必须先跑一遍预热再计时，单次结果抖动很大。</div></details>',
        '用普通 for + get 遍历一个 5 万元素的 LinkedList，记录耗时，再改成迭代器对比。<details class="tb-ans"><summary>参考答案</summary><div class="ans-body"><pre class="tb-ans-code" data-lang="java">import java.util.Iterator;\nimport java.util.LinkedList;\nimport java.util.List;\n\npublic class WalkLinked {\n  public static void main(String[] args) {\n    int n = 50_000;\n    List&lt;Integer> l = new LinkedList&lt;>();\n    for (int i = 0; i &lt; n; i++) l.add(i);\n    long t0 = System.nanoTime();\n    long s1 = 0;\n    for (int i = 0; i &lt; l.size(); i++) s1 += l.get(i);\n    long t1 = System.nanoTime();\n    long s2 = 0;\n    Iterator&lt;Integer> it = l.iterator();\n    while (it.hasNext()) {\n      s2 += it.next();\n    }\n    long t2 = System.nanoTime();\n    System.out.println(s1 + " / " + (t1 - t0) / 1_000_000);\n    System.out.println(s2 + " / " + (t2 - t1) / 1_000_000);\n  }\n}</pre><b>要点</b>：LinkedList.get(i) 要先从头或尾数过去，普通 for 遍历退化成 O(n^2)，五万元素就能差几个数量级；判断容器能不能随机访问看它是否实现 RandomAccess，实现了才用下标循环。</div></details>',
        '给 MiniArrayList 增加 add(index, e) 方法，要求正确处理边界和元素后移。<details class="tb-ans"><summary>参考答案</summary><div class="ans-body"><pre class="tb-ans-code" data-lang="java">public class MiniArrayList {\n  private int[] data = new int[4];\n  private int size;\n\n  private void check(int i, int max) {\n    if (i &lt; 0 || i > max) {\n      throw new IndexOutOfBoundsException("index " + i);\n    }\n  }\n\n  public void add(int index, int e) {\n    check(index, size);\n    if (size == data.length) grow();\n    System.arraycopy(data, index, data, index + 1,\n        size - index);\n    data[index] = e;\n    size++;\n  }\n\n  private void grow() {\n    int[] bigger = new int[data.length * 2];\n    System.arraycopy(data, 0, bigger, 0, size);\n    data = bigger;\n  }\n\n  public static void main(String[] args) {\n    MiniArrayList l = new MiniArrayList();\n    l.add(0, 7);\n    l.add(0, 5);\n    l.add(1, 6);\n    System.out.println(l.data[0] + "," + l.data[1]\n        + "," + l.data[2]);\n  }\n}</pre><b>要点</b>：插入下标的合法范围是 0..size（等于 size 就是尾插），所以边界检查的上界必须是 size 而不是 size-1；必须先扩容再腾位置，元素后移用 System.arraycopy 一次搬完。</div></details>',
        '写代码验证：在增强 for 中删除元素会抛异常，而 iterator.remove 不会。<details class="tb-ans"><summary>参考答案</summary><div class="ans-body"><pre class="tb-ans-code" data-lang="java">import java.util.ArrayList;\nimport java.util.ConcurrentModificationException;\nimport java.util.Iterator;\nimport java.util.List;\n\npublic class RemoveInLoop {\n  public static void main(String[] args) {\n    List&lt;String> a = new ArrayList&lt;>(\n        List.of("a", "b", "c"));\n    try {\n      for (String s : a) {\n        if (s.equals("b")) a.remove(s);\n      }\n    } catch (ConcurrentModificationException e) {\n      System.out.println("增强 for 删除抛异常");\n    }\n    List&lt;String> b = new ArrayList&lt;>(\n        List.of("a", "b", "c"));\n    Iterator&lt;String> it = b.iterator();\n    while (it.hasNext()) {\n      if (it.next().equals("b")) it.remove();\n    }\n    System.out.println(b);\n  }\n}</pre><b>要点</b>：增强 for 被编译器展开成迭代器，但 remove 调的是 list 自己的方法：modCount 变了、迭代器里的 expectedModCount 没变，下一次 next 就抛 ConcurrentModificationException；it.remove() 会同步这两个计数。</div></details>',
        '设计一个「最近浏览记录」功能，最多保留 20 条，新记录加到头部，超出删尾部，选择合适的容器并说明理由。<details class="tb-ans"><summary>参考答案</summary><div class="ans-body"><pre class="tb-ans-code" data-lang="java">import java.util.ArrayDeque;\nimport java.util.Deque;\n\npublic class Recent {\n  private final int limit;\n  private final Deque&lt;String> q = new ArrayDeque&lt;>();\n\n  Recent(int limit) { this.limit = limit; }\n\n  void visit(String url) {\n    q.remove(url);\n    q.addFirst(url);\n    while (q.size() > limit) q.removeLast();\n  }\n\n  public static void main(String[] args) {\n    Recent r = new Recent(3);\n    for (String s : new String[] {"a", "b", "c", "a"}) {\n      r.visit(s);\n    }\n    System.out.println(r.q);\n  }\n}</pre><b>要点</b>：头插尾删正是 Deque 的两端操作，ArrayDeque 都摊还 O(1) 且每元素无额外节点；ArrayList 的 add(0,x) 每次要搬整个数组，不选它。访问过的项要先 remove 再 addFirst，否则同一个 url 会出现两条。</div></details>'
      ] },
      { note: '<b>练习建议：</b>同时打开 JDK 源码对照 ArrayList 的 grow、add、remove 与 LinkedList 的 linkLast、node、unlink，按「add 一个元素发生了什么」这条线追踪，比从头通读高效得多。' }
    ]
  };


T['hashmap'] = {
    meta: '本章约 6800 字 · 建议 40 分钟 · 配套 put 流程图与 6 道习题',
    blocks: [
      { h: '3.1 为什么学 HashMap' },
      { p: '前面两章讲的 List 都是“按位置存”：你知道第几个元素是什么，就用下标取；你想按某个条件找，就只能从头遍历。但现实里大量需求不是按位置，而是按“标识”查：用学号查学生、用身份证号查账户、用单词查出现次数、用配置项名字查配置值。这类需求的核心是建立一种映射关系，让一个键对应一个值。' },
      { p: '用 List 也能做：把键值对封装成对象塞进列表，查找时逐个比较键。数据量小的时候没问题，一千条以内几乎感觉不到慢。可一旦到十万条、一百万条，每次查找都平均比较一半的元素，累计起来就是灾难。HashMap 出现的意义，就是把“按键查找”的平均代价从 O(n) 降到 O(1)，而且这个 O(1) 不依赖数据规模。' },
      { p: '它是 Java 面试出现频率最高的类之一，也是实际项目里最常用的容器。但很多人只会 put 和 get，遇到“自定义对象做 key 为什么取不到值”“为什么遍历顺序每次不一样”“多线程用 HashMap 为什么会丢数据”就答不上来。这些问题的答案都藏在它的底层结构里。' },
      { p: '这一章我们按“结构 → 定位 → 写入 → 冲突 → 扩容 → 树化 → 读取 → 契约 → 调优”的顺序拆解。读完之后，你应该能徒手画出一次 put 的完整路径，能解释容量为什么必须是 2 的幂，也能在代码 review 时一眼看出 equals/hashCode 写得对不对。' },
      { h: '3.2 整体结构：数组、链表与红黑树' },
      { p: 'JDK 8 的 HashMap 本质上是“数组 + 链表 + 红黑树”。最外层是一个 Node 数组，习惯上叫 table 或“桶数组”；每个数组位置叫一个桶（bucket）；桶里先放一个节点，冲突的元素就挂在这个节点后面形成链表；当链表长到一定程度并且数组也够长时，链表会转换成红黑树，把查找从 O(n) 降到 O(log n)。' },
      { p: '每个节点是一个 Node 对象，包含四个部分：hash（键的哈希值，缓存下来避免重复计算）、key、value、next（指向同桶的下一个节点）。注意它存了 hash，而不是每次比较都重新调用 hashCode。比较两个键是否相同时，先比 hash，不相等就直接跳过，只有 hash 相等才继续比 key，这是一个很实在的小优化。' },
      { p: '有几个术语必须分清。capacity 是 table 的长度，也就是桶的数量，永远是 2 的幂；size 是当前键值对的数量；threshold 是扩容阈值，等于 capacity 乘以负载因子；loadFactor 是负载因子，默认 0.75。很多人把 size 和 capacity 混为一谈，实际上 size 可以远小于 capacity，前者是“装了多少”，后者是“能装多少”。' },
      { p: 'table 不是 new 的时候就分配。无参构造只设置负载因子，table 仍然是 null；第一次 put 时才调用 resize 分配一个长度为 16 的数组，并把阈值设为 12。这叫懒初始化，目的是避免创建了却不用造成浪费。所以“HashMap 默认容量 16”这句话要补一句：第一次放入元素时才真正分配。' },
      { table: { head: ['常量', '值', '含义'], rows: [
        ['DEFAULT_INITIAL_CAPACITY', '16', '默认容量，必须是 2 的幂'],
        ['DEFAULT_LOAD_FACTOR', '0.75', '默认负载因子'],
        ['TREEIFY_THRESHOLD', '8', '链表长度达到它就考虑树化'],
        ['UNTREEIFY_THRESHOLD', '6', '树节点数降到它就退化为链表'],
        ['MIN_TREEIFY_CAPACITY', '64', '树化要求的最小表长度'],
        ['MAXIMUM_CAPACITY', '1 << 30', '容量的上限']
      ] } },
      { lang: 'java', code: 'import java.util.HashMap;\nimport java.util.Map;\n\npublic class HashMapBasic {\n    public static void main(String[] args) {\n        Map<String, Integer> stock = new HashMap<>();\n        stock.put("apple", 10);\n        stock.put("banana", 5);\n        stock.put("cherry", 20);\n\n        stock.put("apple", 12);            // 键已存在，覆盖旧值\n        System.out.println(stock.get("apple"));      // 12\n        System.out.println(stock.get("durian"));     // null\n        System.out.println(stock.getOrDefault("durian", 0)); // 0\n        System.out.println(stock.containsKey("banana"));     // true\n        System.out.println(stock.size());                    // 3\n\n        for (Map.Entry<String, Integer> e : stock.entrySet()) {\n            System.out.println(e.getKey() + " = " + e.getValue());\n        }\n    }\n}', title: 'HashMapBasic.java' },
      { out: '12\nnull\n0\ntrue\n3\nbanana = 5\napple = 12\ncherry = 20' },
      { p: '注意这段遍历的顺序：banana 排在 apple 前面，既不是插入顺序也不是字母顺序，而是哈希下标决定的顺序。换一批键、换一个容量，顺序就可能变，所以永远不要依赖它。需要顺序时应该换 LinkedHashMap（保留插入顺序）或 TreeMap（按键排序），而不是试图“修好” HashMap 的顺序。' },
      { h: '3.3 hash 定位：从任意键到数组下标' },
      { p: 'HashMap 要解决的核心问题是：给你一个任意类型的 key，怎么把它变成一个 0 到 capacity-1 之间的整数下标。答案分两步：先调用 key 的 hashCode 得到一个 int，再对这个 int 做“扰动”，最后用位运算映射到数组范围内。' },
      { p: 'hashCode 返回的是 32 位有符号整数，范围大约正负 21 亿。如果直接用它去取模，会遇到两个问题：负数取模结果可能是负的，不能直接当数组下标；而且 table 通常只有 16 或 32 个位置，高位的信息完全用不上，大量键会挤在少数几个桶里。' },
      { p: 'JDK 8 的扰动函数只有一行：<code>(h = key.hashCode()) ^ (h &gt;&gt;&gt; 16)</code>。它把 hash 的高 16 位无符号右移到低 16 位，再和原值做异或。这样高位的变化也能影响低位，而低位正是后面取下标时要用的部分。异或的好处是不会丢失信息，比直接相加或相乘更均匀。' },
      { p: '接着算下标：<code>(n - 1) &amp; hash</code>，n 是 table 长度。当 n 是 2 的幂时，n-1 的二进制是“低位全 1”，按位与的结果恰好等于 hash 对 n 取模，但位运算比取模快得多。这就是容量必须是 2 的幂的根本原因：只有这样，位运算才能替代取模，并且让结果均匀落在每个桶上。' },
      { p: '如果容量不是 2 的幂，比如 15，n-1 是 1110，最后一位永远是 0，那么所有奇数下标的桶永远空着，一半空间被浪费，冲突概率也翻倍。所以即使你构造时传入 17，HashMap 也会用 tableSizeFor 把它向上取成 32。它宁可多分配一点，也要保证容量是 2 的幂。' },
      { p: '还有一个特殊值：null 键。HashMap 允许一个 null 键，它的 hash 被固定为 0，所以永远落在下标 0 的桶里。这也是为什么推荐用 String、Integer 这类不可变对象做键——它们的 hashCode 稳定且分布均匀，而 null 键虽然能用，但会让逻辑多一个分支。' },
      { lang: 'java', code: 'public class HashIndex {\n    static final int hash(Object key) {\n        int h;\n        return (key == null) ? 0 : (h = key.hashCode()) ^ (h >>> 16);\n    }\n\n    public static void main(String[] args) {\n        System.out.println("Aa 与 BB 的 hashCode 相同: "\n                + ("Aa".hashCode() == "BB".hashCode()));\n\n        int n = 16;                       // 容量必须是 2 的幂\n        for (String k : new String[]{"Aa", "BB", "java"}) {\n            int h = hash(k);\n            System.out.println(k + " 扰动后=" + h + " 下标=" + ((n - 1) & h));\n        }\n    }\n}', title: 'HashIndex.java' },
      { out: 'Aa 与 BB 的 hashCode 相同: true\nAa 扰动后=2112 下标=0\nBB 扰动后=2112 下标=0\njava 扰动后=3254803 下标=3' },
      { p: '这个例子同时说明了两件事：第一，不同的字符串完全可能拥有相同的 hashCode，“Aa”和“BB”就是经典例子；第二，hash 相同就一定会落到同一个桶，于是形成冲突。冲突不可怕，HashMap 有链表和红黑树来兜底，但冲突太多会显著拖慢查询，所以好的 hashCode 应该尽量均匀。' },
      { h: '3.4 put 的完整流程' },
      { p: 'put 是 HashMap 最复杂的操作，把它拆成一条流水线就好理解了。下面这条流程对应 JDK 8 的实现，省略了并发和树化的部分细节，但主干完全一致。' },
      { flow: ['计算 key 的 hash（扰动）', 'table 为空则先 resize 初始化', '用 (n-1) & hash 定位桶', '桶为空则直接放入新节点', '桶首节点 key 相同则覆盖 value', '是树节点则走红黑树插入', '否则遍历链表，尾部插入或覆盖', '链表长度达阈值则 treeifyBin', 'size 加一，超过阈值则 resize'] },
      { p: '第一步算 hash，上一节已经讲过。第二步检查 table 是否为 null 或长度为 0，是就先扩容，这一次扩容会把容量定为 16、阈值定为 12。第三步定位下标。第四步如果桶里什么都没有，直接 new 一个 Node 放进去，这是最常见也最快的情况。' },
      { p: '第五步比较桶的首节点：如果 hash 相同且 key 相等（== 或 equals），说明是同一个键，直接把 value 换掉，然后返回旧值。注意这里返回旧值是 put 的约定，很多人不知道 put 有返回值，其实它在“覆盖”场景下非常有用，可以判断这次写入是新增还是更新。' },
      { p: '第六步，如果首节点是 TreeNode，说明这个桶已经树化，调用 putTreeVal 在红黑树里查找或插入。第七步是普通链表：从首节点往后遍历，每到一个节点都比较 hash 和 key，找到相同的就覆盖并返回；走到尾部还没有，就 new 一个节点挂在最后。JDK 8 用的是尾插法，JDK 7 用的是头插法，这个变化后面会解释原因。' },
      { p: '第八步，插入新节点后如果链表长度达到了 8，调用 treeifyBin。但注意 treeifyBin 内部还会检查 table 长度是否达到 64：没达到就只做一次扩容，不树化。第九步，size 加一，如果超过 threshold 就 resize。所以一次 put 可能触发一次扩容，也可能触发一次树化，具体取决于当时的容量和冲突情况。' },
      { p: '为什么要把“检查是否已存在”放在插入之前？因为 HashMap 不允许重复键。如果先插入再检查，就会产生两个相同的键，后续 get 的行为将不确定。这个“先查后插”的顺序是所有 Map 实现都必须遵守的语义，也是 put 比 List.add 复杂得多的原因。' },
      { h: '3.5 哈希冲突与链表' },
      { p: '冲突是数学上不可避免的。hashCode 只有 32 位，能表示约 42 亿种取值，而字符串可以有无限多种；就算键的类型有限，把任意多的键塞进固定数量的桶，根据鸽巢原理，一定有两个键落到同一个桶。所以 HashMap 的设计目标不是“消除冲突”，而是“让冲突的代价可控”。' },
      { p: '解决冲突有两大流派：开放地址法（冲突了就按某种规则找下一个空位）和链地址法（同一个桶里的元素串成链表）。HashMap 用的是链地址法，因为它在删除时更简单，也不会出现“探测序列断裂”的问题。Java 的 ThreadLocalMap 用的是开放地址法，可以对比着理解。' },
      { p: 'JDK 7 的链表插入用头插法：新节点直接变成桶的第一个节点，原来的头变成它的 next。头插的优点是快，不用遍历到尾部；缺点是扩容后同一桶的元素顺序会反转，而且在并发扩容时可能形成环形链表，导致 get 时无限循环、CPU 打满。JDK 8 改成尾插法，顺序稳定了，环的问题也从根源上消失。' },
      { p: '冲突的代价是查询变慢。一个桶里有 k 个元素，最坏要比较 k 次，平均 k/2 次。如果 hash 分布很差，所有键都挤在一个桶里，HashMap 就退化成一个链表，get 从 O(1) 变成 O(n)。这正是“好的 hashCode”重要的原因：它决定了元素能不能均匀铺开。' },
      { p: 'String 的 hashCode 写法值得一看：<code>h = 31 * h + charAt(i)</code>，从第一个字符开始累乘 31 再相加。选 31 是因为它是奇素数，乘法可以变成移位减法（31 * h = (h &lt;&lt; 5) - h），JVM 能优化；而且 31 不大，不容易溢出。这个实现简单、稳定、分布尚可，是自定义 hashCode 时可以借鉴的模板。' },
      { lang: 'java', code: 'import java.lang.reflect.Field;\nimport java.util.HashMap;\n\npublic class CollisionDemo {\n    static class BadKey {\n        final int id;\n        BadKey(int id) { this.id = id; }\n        @Override public int hashCode() { return 1; }   // 全部撞在一起\n        @Override public boolean equals(Object o) {\n            return o instanceof BadKey && ((BadKey) o).id == id;\n        }\n    }\n\n    public static void main(String[] args) throws Exception {\n        HashMap<BadKey, Integer> map = new HashMap<>();\n        for (int i = 0; i < 10; i++) {\n            map.put(new BadKey(i), i);\n        }\n        System.out.println("size = " + map.size());\n        System.out.println("get(7) = " + map.get(new BadKey(7)));\n\n        Field f = HashMap.class.getDeclaredField("table");\n        f.setAccessible(true);\n        Object[] table = (Object[]) f.get(map);\n        System.out.println("table 长度 = " + table.length);\n\n        Object node = table[1];        // hash=1，容量 16 时下标为 1\n        int len = 0;\n        while (node != null) {\n            len++;\n            Field nf = node.getClass().getDeclaredField("next");\n            nf.setAccessible(true);\n            node = nf.get(node);\n        }\n        System.out.println("下标 1 的链表长度 = " + len);\n    }\n}', title: 'CollisionDemo.java' },
      { out: 'size = 10\nget(7) = 7\ntable 长度 = 64\n下标 1 的链表长度 = 10' },
      { p: '这段代码故意让所有键的 hashCode 都返回 1。放入 10 个元素后，它们全部落在下标 1 的桶里，链表长度是 10。按规则，链表长度达到 8 应该树化，但 table 长度只有 16，没有达到 64，容量不足 64 时，treeifyBin 不会树化，而是改为扩容：第 9 个元素触发一次、第 10 个元素又触发一次，容量最终到 64，链表仍然是链表，要到第 11 个元素才真正树化。这个实验结果正好验证了“树化需要容量配合”这条规则。' },
      { h: '3.6 扩容：resize、负载因子与容量预判' },
      { p: '当 size 超过 threshold 时，HashMap 会扩容。threshold 等于 capacity 乘以 loadFactor，默认容量 16 对应阈值 12，也就是说 16 个桶装到 13 个元素时触发扩容。扩容的动作是：创建一个长度翻倍的新数组，把旧数组里的每个节点重新分配到新数组，然后把 table 指向新数组，阈值也翻倍。' },
      { p: '最直观的 rehash 做法是对每个节点重新计算 hash 和下标，但 JDK 8 做了一个很巧的优化。因为容量是 2 的幂，扩容后容量翻倍，元素的新下标只有两种可能：要么还是原下标，要么是原下标加旧容量。判断依据是 <code>(e.hash &amp; oldCap) == 0</code>：等于 0 就留在低位链，否则进高位链。' },
      { p: '这样一次遍历就能把旧桶拆成两条链，一条放在新数组的原位置，一条放在“原位置 + oldCap”的位置，完全不需要重新计算 hash，也不需要取模。这个设计是 JDK 8 相比 JDK 7 的重要性能改进，也让扩容时的节点顺序保持稳定，不会像头插法那样反转。' },
      { p: '负载因子 0.75 不是随便定的。它要在“空间利用率”和“冲突概率”之间折中：太小会频繁扩容、浪费内存；太大则桶里元素变多、查询变慢。0.75 来自对随机哈希的泊松分布计算，在这个负载下，一个桶里出现 8 个元素的概率大约是千万分之一，所以树化阈值定在 8 是有统计依据的，不是拍脑袋。' },
      { p: '负载因子不建议随便改。调小（比如 0.5）会让冲突更少、查询更快，但扩容更频繁、内存占用更高；调大（比如 0.9）省内存，但桶里元素变多，查询变慢，还可能频繁树化。除非你有明确的基准测试数据，否则保持 0.75 就好，JDK 的选择已经考虑得很周全。' },
      { p: '如果大概知道要放多少元素，构造时传初始容量能避免反复扩容。但不要直接传元素个数，因为 HashMap 会按“容量 × 0.75”算阈值，传 1000 实际只能装 750 个就会扩容。正确的估算方式是 <code>expectedSize / 0.75 + 1</code>，再让 HashMap 向上取到 2 的幂。' },
      { p: '举个例子：预计放 1000 个键值对，1000 / 0.75 约等于 1333，加一得 1334，tableSizeFor 向上取到 2048。这样阈值是 1536，放 1000 个不会触发扩容。如果直接传 1000，容量是 1024，阈值 768，放到 769 个就扩容到 2048，多了一次完整的 rehash。' },
      { p: '扩容的代价是 O(n)，而且扩容瞬间新旧两个数组同时存在，内存峰值会明显上升。所以如果你能预估元素数量，最好在构造时指定初始容量，避免运行期反复扩容。反过来说，也不要随意指定一个巨大的容量，那会长期占用大量内存，还拖慢 GC。' },
      { p: '扩容还会改变遍历顺序。因为元素被拆分到新数组的不同位置，原来相邻的键可能被分到不同的桶。这就是“HashMap 顺序不保证”的底层原因之一：不仅哈希本身无序，扩容还会重排。任何依赖 HashMap 遍历顺序的业务逻辑都是脆弱的。' },
      { lang: 'java', code: 'import java.lang.reflect.Field;\nimport java.util.HashMap;\n\npublic class ResizeDemo {\n    static int capacity(HashMap<?, ?> map) throws Exception {\n        Field f = HashMap.class.getDeclaredField("table");\n        f.setAccessible(true);\n        Object[] t = (Object[]) f.get(map);\n        return t == null ? 0 : t.length;\n    }\n\n    static int threshold(HashMap<?, ?> map) throws Exception {\n        Field f = HashMap.class.getDeclaredField("threshold");\n        f.setAccessible(true);\n        return (Integer) f.get(map);\n    }\n\n    public static void main(String[] args) throws Exception {\n        HashMap<String, Integer> map = new HashMap<>(3);\n        for (int i = 1; i <= 7; i++) {\n            map.put("k" + i, i);\n            System.out.println("size=" + map.size()\n                    + " capacity=" + capacity(map)\n                    + " threshold=" + threshold(map));\n        }\n    }\n}', title: 'ResizeDemo.java' },
      { out: 'size=1 capacity=4 threshold=3\nsize=2 capacity=4 threshold=3\nsize=3 capacity=4 threshold=3\nsize=4 capacity=8 threshold=6\nsize=5 capacity=8 threshold=6\nsize=6 capacity=8 threshold=6\nsize=7 capacity=16 threshold=12' },
      { p: '构造时传 3，HashMap 用 tableSizeFor 把它向上取成 4，所以容量是 4 而不是 3。容量 4 的阈值是 3，放第 4 个元素时超过阈值，扩容到 8，阈值变成 6；放到第 7 个时又超过 6，扩容到 16，阈值 12。整个过程清晰展示了“容量翻倍、阈值同步翻倍”的规律。' },
      { list: ['容量 16 对应阈值 12，能装 12 个键值对；', '容量 32 对应阈值 24；', '容量 64 对应阈值 48；', '容量 128 对应阈值 96；', '容量 256 对应阈值 192。'] },
      { h: '3.7 树化与退化' },
      { p: '链表越长，查询越慢。为了兜底，JDK 8 引入了红黑树：当一个桶里的链表长度达到 8，并且 table 长度达到 64 时，这条链表会被转换成红黑树，查询复杂度从 O(n) 降到 O(log n)。这就是“数组 + 链表 + 红黑树”里红黑树的由来。' },
      { p: '为什么树化需要两个条件？因为树节点比普通节点占用的内存大得多，TreeNode 除了 key、value、next，还要维护 parent、left、right、red 等字段。如果 table 还很短，冲突多只是因为桶太少，此时扩容比树化更划算：扩容能把元素分散到更多桶里，从根源上减少冲突，而且实现简单、内存开销小。' },
      { p: 'TreeNode 有一个巧妙的设计：它继承自 LinkedHashMap.Entry，而后者又继承自 HashMap.Node，所以树节点同时保留了 next 指针，既能当红黑树用，也能当链表用。扩容拆分时，代码可以沿 next 遍历整棵树，把它拆成低位和高位两条链，再根据长度决定是否重新树化。这种“一节点两用”的设计减少了类型转换的复杂度。' },
      { p: '树化之后，查找、插入、删除都变成 O(log n)。但要注意，红黑树比较节点时仍然要调用 equals 或比较 hash，如果所有键的 hash 都相同，比较次数并不会消失，只是从线性变成对数。所以树化是“缓解”而不是“消除”糟糕 hashCode 的影响，根子上还是要写出分布均匀的 hashCode。' },
      { p: '退化发生在两个时机：一是扩容拆分后，如果一条树上的节点数小于等于 6，就把它转回链表；二是删除节点后，如果树的结构变得太小，也会触发退化。阈值 8 和 6 之间留了缓冲，避免在边界反复树化、退化，这种“迟滞”设计在工程里很常见。' },
      { p: '实际项目里，正常的 String 或 Integer 键几乎不会触发树化，因为它们的 hash 分布足够均匀，一个桶里很难堆到 8 个元素。所以树化更像是“防御性设计”，用来应对恶意构造的 hash 冲突（比如攻击者故意送一堆 hash 相同的参数），保证最坏情况下性能不会彻底崩塌。' },
      { h: '3.8 get 与查询路径' },
      { p: 'get 的流程比 put 简单：先算 hash，再用 (n-1) & hash 定位桶，然后在这个桶里找。如果桶是空的，直接返回 null；如果首节点就匹配，返回它的 value；如果是树节点，走红黑树查找；否则沿着 next 遍历链表，直到找到或走到末尾。' },
      { p: '判断“是不是同一个键”的条件是：<code>e.hash == hash &amp;&amp; (k = e.key) == key || key.equals(k)</code>。先比 hash 是因为整数比较极快，能过滤掉绝大多数不相同的键；再用 == 比较引用，相同引用直接通过；最后才调用 equals，因为 equals 可能很慢。这个顺序把开销大的操作放在最后，是很典型的性能优化思路。' },
      { p: '注意括号：实际源码是 <code>(k = e.key) == key || (key != null &amp;&amp; key.equals(k))</code>，先判断引用相等，再判断 key 非空后调用 equals。这样既避免了空指针，也保证了自己和自己比较时不用走 equals。写自定义 key 时，equals 里也要先做 instanceof 或 getClass 判断，再强转比较字段。' },
      { p: 'get 返回 null 有一个著名歧义：它可能表示“这个键不存在”，也可能表示“这个键存在，但它的值是 null”。HashMap 允许 null 值，所以这两种情况无法靠返回值区分。要区分就用 containsKey，它返回 boolean，代价和 get 一样是 O(1)。这也是为什么有些团队规范禁止在 Map 里存 null 值。' },
      { p: '还有一个容易混淆的方法：containsValue。它不是 O(1)，而是 O(n)，因为值没有哈希，只能把整个表遍历一遍。如果业务频繁需要“按值查键”，说明数据结构选错了，应该额外维护一个反向的 Map，而不是反复调用 containsValue。' },
      { lang: 'java', code: 'import java.util.HashMap;\nimport java.util.Map;\n\npublic class GetDemo {\n    public static void main(String[] args) {\n        Map<String, String> map = new HashMap<>();\n        map.put("a", null);\n        map.put("b", "B");\n\n        System.out.println(map.get("a"));            // null，存在但值为 null\n        System.out.println(map.get("c"));            // null，不存在\n        System.out.println(map.containsKey("a"));    // true\n        System.out.println(map.containsKey("c"));    // false\n        System.out.println(map.getOrDefault("c", "默认值")); // 默认值\n\n        System.out.println(map.containsValue("B"));  // true，O(n)\n        System.out.println(map.size());              // 2\n    }\n}', title: 'GetDemo.java' },
      { out: 'null\nnull\ntrue\nfalse\n默认值\ntrue\n2' },
      { p: '如果业务上确实需要区分“没有”和“值为 null”，除了 containsKey，还可以用 Optional 包装返回值，或者干脆约定不允许 null 值并在一开始就校验。约定比技巧更重要：一个团队统一“Map 不存 null 值”，就能省掉大量判空和歧义处理。' },
      { h: '3.9 equals 与 hashCode 的契约、key 的选择' },
      { p: '这是 HashMap 最容易出错的地方，也是面试必问。Java 对这两个方法有一条硬性契约：如果两个对象 equals 返回 true，那么它们的 hashCode 必须相等；反过来，hashCode 相等，equals 不一定为 true。违反前半条，HashMap 就会出现“存进去却取不出来”的怪事。' },
      { p: '原因在于 HashMap 的查找是两段式的：先靠 hashCode 定位到桶，再靠 equals 在桶内精确匹配。如果你只重写了 equals，没有重写 hashCode，两个“逻辑相等”的对象会使用 Object 默认的 hashCode（通常是对象地址派生出来的），落在不同的桶里。查找时先去 A 桶找，而对象在 B 桶，自然找不到。' },
      { p: '反过来，只重写 hashCode 不重写 equals 也不行。这样两个对象可能落在同一个桶，但 equals 仍然比较地址，返回 false，HashMap 会认为它们是两个不同的键，于是同一个桶里出现两个“看起来一样”的键，get 时可能取到其中一个，行为难以预测。' },
      { p: '正确的做法是两者一起重写，并且使用同一组字段。推荐用 IDE 生成，或者用 <code>Objects.equals</code> 和 <code>Objects.hash</code> 简化。字段的选择标准是：参与 equals 比较的字段，必须全部参与 hashCode 计算；不参与的字段不能影响相等性判断。' },
      { p: 'equals 本身还要满足五条性质：自反（自己等于自己）、对称（a 等于 b 则 b 等于 a）、传递（a=b、b=c 则 a=c）、一致（多次调用结果不变）、与 null 比较必须返回 false。写的时候先判断 <code>this == o</code>，再判断 <code>o == null || getClass() != o.getClass()</code>，然后强转逐字段比较，这是最稳妥的模板。' },
      { p: '一个隐蔽的错误是参数类型写错：<code>public boolean equals(Point o)</code> 不是重写，而是重载。HashMap 内部调用的是 <code>equals(Object)</code>，你写的那个方法根本不会被调用。加上 <code>@Override</code> 注解，编译器会立刻报错，帮你发现这个问题。这是注解最实用的场景之一。' },
      { lang: 'java', code: 'import java.util.HashMap;\nimport java.util.Map;\nimport java.util.Objects;\n\npublic class EqualsHashCodeDemo {\n    static class BadPoint {\n        final int x, y;\n        BadPoint(int x, int y) { this.x = x; this.y = y; }\n        @Override public boolean equals(Object o) {\n            if (!(o instanceof BadPoint)) return false;\n            BadPoint p = (BadPoint) o;\n            return x == p.x && y == p.y;\n        }\n        // 故意不重写 hashCode\n    }\n\n    static class GoodPoint {\n        final int x, y;\n        GoodPoint(int x, int y) { this.x = x; this.y = y; }\n        @Override public boolean equals(Object o) {\n            if (this == o) return true;\n            if (!(o instanceof GoodPoint)) return false;\n            GoodPoint p = (GoodPoint) o;\n            return x == p.x && y == p.y;\n        }\n        @Override public int hashCode() { return Objects.hash(x, y); }\n    }\n\n    public static void main(String[] args) {\n        Map<BadPoint, String> bad = new HashMap<>();\n        bad.put(new BadPoint(1, 2), "A");\n        System.out.println(bad.get(new BadPoint(1, 2)));  // null\n\n        Map<GoodPoint, String> good = new HashMap<>();\n        good.put(new GoodPoint(1, 2), "A");\n        System.out.println(good.get(new GoodPoint(1, 2))); // A\n    }\n}', title: 'EqualsHashCodeDemo.java' },
      { out: 'null\nA' },
      { table: { head: ['equals', 'hashCode', '结果'], rows: [
        ['重写', '重写', '正常，可以按值查找'],
        ['重写', '不重写', 'equals 相等但桶不同，get 取不到'],
        ['不重写', '重写', '同桶但 equals 不等，被当成两个键'],
        ['不重写', '不重写', '按引用比较，只认同一个对象']
      ] } },
      { p: '最后一种情况其实也是合法的：如果你就希望“只有同一个对象才算同一个键”，那用默认实现没问题。问题出在“混合”：既想按值相等，又只重写了一半。判断标准很简单：只要你的类需要作为 HashMap 的键或 HashSet 的元素，并且你重写了 equals，就必须同时重写 hashCode。' },
      { p: '最适合做键的是不可变对象：String、Integer、Long、枚举、UUID 等。它们的字段不会被修改，hashCode 在生命周期内保持不变，equals 也有明确定义。枚举尤其适合，因为枚举实例天然唯一，hashCode 由 JVM 保证稳定，还能直接用 == 比较。' },
      { p: '可变对象做键是经典陷阱。假设你用一个人对象做键，put 之后修改了它的姓名，而姓名参与了 hashCode 计算，那么这个对象的 hash 变了，但它在表里的位置还是按旧 hash 放的。之后用这个对象去 get，算出来的是新 hash，定位到别的桶，自然找不到。数据没丢，只是“迷路”了。' },
      { p: '数组和集合也不适合直接做键。数组的 equals 是引用比较，两个内容相同的数组并不相等；List 虽然重写了 equals，但它是可变的，修改元素会改变 hashCode。如果确实需要，可以先用 <code>List.copyOf</code> 转成不可变列表，或者自己封装一个不可变的值对象。' },
      { h: '3.10 遍历：三种方式、顺序与 fail-fast' },
      { p: '遍历 HashMap 有三种方式：keySet 只拿键，values 只拿值，entrySet 拿键值对。如果同时需要键和值，entrySet 最快，因为它一次就取出两者，不用为每个键再调用一次 get。keySet 遍历再 get 的写法虽然常见，但相当于每个元素多一次查找，数据量大时差距明显。' },
      { p: 'HashMap 不保证顺序，这是它和 LinkedHashMap、TreeMap 最大的区别。LinkedHashMap 在 HashMap 的基础上加了一条双向链表，默认保留插入顺序，构造时传 accessOrder=true 还能变成 LRU 顺序；TreeMap 则按 key 的自然顺序或比较器排序，代价是操作变成 O(log n)。' },
      { p: '遍历时修改也会触发 fail-fast。HashMap 的迭代器同样维护 expectedModCount，检测到 modCount 变化就抛 ConcurrentModificationException。正确做法是用 <code>map.remove(key)</code> 配合迭代器的 remove，或者用 JDK 8 的 <code>removeIf</code>、<code>forEach</code>，但后者内部也依赖迭代器，不能在回调里直接改结构。' },
      { lang: 'java', code: 'import java.util.HashMap;\nimport java.util.Map;\n\npublic class WordCount {\n    public static void main(String[] args) {\n        String text = "the quick brown fox jumps over the lazy dog the fox";\n        Map<String, Integer> freq = new HashMap<>();\n\n        for (String word : text.split("[^A-Za-z]+")) {\n            if (word.isEmpty()) continue;\n            freq.merge(word, 1, Integer::sum);\n        }\n\n        System.out.println("不同单词数: " + freq.size());\n        System.out.println("the 出现次数: " + freq.get("the"));\n        System.out.println("fox 出现次数: " + freq.get("fox"));\n\n        String best = null;\n        int max = 0;\n        for (Map.Entry<String, Integer> e : freq.entrySet()) {\n            if (e.getValue() > max) {\n                max = e.getValue();\n                best = e.getKey();\n            }\n        }\n        System.out.println("出现最多: " + best + " x" + max);\n    }\n}', title: 'WordCount.java' },
      { out: '不同单词数: 8\nthe 出现次数: 3\nfox 出现次数: 2\n出现最多: the x3' },
      { p: '这段代码用了 <code>merge</code>，它是 JDK 8 新增的默认方法：键不存在时放入给定值，存在时用第三个参数把旧值和新值合并。比“先 get 判空再 put”少一次查找，也更简洁。类似的还有 computeIfAbsent、computeIfPresent，专门处理“取不到就初始化”的场景，能避免大量重复的判空代码。' },
      { table: { head: ['遍历方式', '取到的内容', '额外查找', '适用场景'], rows: [
        ['keySet + get', '键，再按键取值', '每个键一次 get', '只需要键，或偶尔取值'],
        ['values', '值', '无', '只关心值的集合'],
        ['entrySet', '键值对', '无', '同时需要键和值，首选'],
        ['forEach', '键值对', '无', '写法简洁，注意不要改结构']
      ] } },
      { h: '3.11 线程安全：多线程 put 会怎样' },
      { p: 'HashMap 不是线程安全的。多个线程同时 put，可能出现数据覆盖、size 不准、甚至节点丢失。JDK 7 在并发扩容时还可能形成环形链表，导致 get 时死循环、CPU 飙到 100%；JDK 8 改成尾插并优化了扩容，环的问题基本消失，但数据覆盖和计数错误依然存在。' },
      { p: '所以“JDK 8 的 HashMap 线程安全了吗”这个问题的答案是：没有。它只是不会死循环了，并发写入仍然会丢数据。需要并发场景就用 ConcurrentHashMap；如果只是偶尔写、读多写少，可以用 Collections.synchronizedMap 包一层，或者每个线程用自己的 Map 再合并。' },
      { p: 'ConcurrentHashMap 在 JDK 8 里用 CAS 加 synchronized 锁单个桶，锁粒度比 JDK 7 的分段锁更细，并发度更高。它不允许 null 键和 null 值，因为并发环境下无法区分“没有”和“值为 null”；它的 size 是弱一致的，不保证精确。这些差异都是为并发场景做的取舍，用之前要了解清楚。' },
      { h: '3.12 常见错误清单' },
      { p: '下面这些错误在初学者代码里反复出现，逐条对照能省下大量调试时间。' },
      { list: [
        '自定义 key 只重写 equals 不重写 hashCode，导致 get 返回 null。',
        '用可变对象做 key，修改字段后再也查不到。',
        '遍历时直接 map.remove，抛 ConcurrentModificationException。',
        '把 size 当成容量，误以为默认能装 16 个元素。',
        '构造时传元素个数，忽略 0.75 的负载因子，仍会扩容。',
        '用 containsValue 做高频查询，没意识到它是 O(n)。',
        '依赖 HashMap 的遍历顺序，换 JDK 或扩容后结果变化。',
        '多线程共享 HashMap 并写入，出现数据丢失却难以复现。'
      ] },
      { h: '3.13 本章小结' },
      { list: [
        'HashMap 是数组 + 链表 + 红黑树，数组叫 table，长度永远是 2 的幂。',
        '定位分两步：hash 扰动 (h ^ h >>> 16)，再用 (n-1) & hash 取下标。',
        'put 先查后插，桶空直接放，冲突挂链表，长度到 8 且容量到 64 才树化。',
        'size 超过 capacity × 0.75 时扩容，容量翻倍，JDK 8 用高低位拆分避免重算 hash。',
        'equals 相等则 hashCode 必须相等，两者要使用同一组字段一起重写。',
        'get 先比 hash 再比 == 再比 equals，返回 null 有“不存在”和“值为 null”两种含义。',
        'HashMap 无序、非线程安全，需要顺序用 LinkedHashMap/TreeMap，需要并发用 ConcurrentHashMap。'
      ] },
      { h: '3.14 常见追问' },
      { list: [
        '<b>问：链表长度到 8 就一定会树化吗？为什么阈值是 8、退化又是 6？</b><br>答：不一定。树化要同时满足两个条件：某个桶里的链表长度达到 8，并且 table 的长度已经达到 64；不满足后者时只做扩容，先把元素摊开，因为扩容往往就能把冲突化解掉。选 8 是因为统计上在 0.75 负载因子下桶内达到 8 个元素的概率极低，链表的平均查找代价还可以接受；退化成 6 而不是 8，是留出缓冲带，避免元素在 7、8 之间来回增删时反复树化与还原，那两次转换的代价远高于多挂一两个节点。',
        '<b>问：负载因子为什么是 0.75？</b><br>答：这是空间占用与冲突概率的折中。取更大的值（比如 1.0）能把数组用得更满、省内存，但桶内元素变多，链表变长，查询和扩容都变慢；取更小的值冲突少、查得快，可数组空着一大片，内存和扩容频率都上升。0.75 是 JDK 文档给出的经验值，配合泊松分布的估算，此时单个桶里出现 8 个元素的概率约为千万分之六，所以树化只是极端情况的兜底，而不是常态。',
        '<b>问：JDK 7 和 JDK 8 的 HashMap 有什么本质区别？</b><br>答：三点。插入方式从头插改成尾插，因为头插在并发扩容时可能让两个节点互相指向，形成环形链表，此后 get 会死循环；结构上引入了红黑树，桶里元素多时从链表退化成树，最坏查找由 O(n) 变成 O(log n)；扩容从重新计算每个键的下标改成用高位与长度做与运算，把一条链拆成低位和高位两条，位置要么不动要么移到原下标加旧容量处。这也是为什么容量必须是 2 的幂。',
        '<b>问：HashMap 允许 null 键和 null 值吗？</b><br>答：都允许，而且 null 键只有一个。null 的 hash 被固定成 0，因此永远落在下标 0 的桶里，重复 put null 会覆盖同一个位置。null 键能存在只是因为它绕过了<code>hashCode()</code>调用，代价是取值前要判空，遍历时也要考虑这个特殊键。ConcurrentHashMap 则完全拒绝 null 键和 null 值，因为并发场景下无法区分「没有这个键」和「值是 null」。',
        '<b>问：put 的返回值是什么？常见的误用是什么？</b><br>答：键原本存在时返回被覆盖的旧值，键不存在时返回 null。看起来像「是否新增」的判据，其实不是：如果旧值本身就是 null，两种情况返回值一样，判断就失效了。要区分是否新增用 <code>putIfAbsent</code>，或先 <code>containsKey</code> 再 put，也可以直接用 <code>computeIfAbsent</code> 把「取不到就建」写成一个原子操作，省掉一次查找。',
        '<b>问：HashMap 和 Hashtable 到底差在哪？</b><br>答：Hashtable 的每个公开方法都加了 synchronized，靠一把对象锁保证线程安全，因此单线程性能明显更差；它不允许 null 键和 null 值；迭代时用的 Enumeration 是弱一致的老接口，没有 fail-fast 的现代语义。它是 JDK 1.0 的遗留类，新代码不该再用。需要并发就选 ConcurrentHashMap，它用分段或桶级 CAS 加锁，读几乎无锁，迭代器弱一致但不会抛异常。'
      ] },

      { h: '3.15 自测与练习' },
      { ol: [
        '手写一个 Person 类作为 HashMap 的键，只重写 equals，验证 get 失败；再补上 hashCode 验证成功。<details class="tb-ans"><summary>参考答案</summary><div class="ans-body"><pre class="tb-ans-code" data-lang="java">import java.util.HashMap;\nimport java.util.Map;\nimport java.util.Objects;\n\npublic class Person {\n  private final String name;\n\n  Person(String name) { this.name = name; }\n\n  @Override\n  public boolean equals(Object o) {\n    return o instanceof Person p &amp;&amp; name.equals(p.name);\n  }\n\n  public static void main(String[] args) {\n    Map&lt;Person, String> m = new HashMap&lt;>();\n    m.put(new Person("Ann"), "VP");\n    System.out.println(m.get(new Person("Ann"))); // null\n    System.out.println(new Person("Ann")\n        .equals(new Person("Ann")));              // true\n  }\n\n  @Override\n  public int hashCode() { return Objects.hash(name); }\n}</pre><b>要点</b>：注释掉 hashCode 时两个相等对象的哈希不同，落进不同桶，get 必然 null；补上 Objects.hash(name) 后才变回 "VP"。equals 和 hashCode 必须用同一组字段，record 会把两者一起生成。</div></details>',
        '用反射打印 HashMap 的 table 长度和阈值，分别用 new HashMap&lt;&gt;() 和 new HashMap&lt;&gt;(100) 观察差异。<details class="tb-ans"><summary>参考答案</summary><div class="ans-body"><pre class="tb-ans-code" data-lang="java">// 运行：java --add-opens java.base/java.util=ALL-UNNAMED Peek\nimport java.lang.reflect.Field;\nimport java.util.HashMap;\n\npublic class Peek {\n  static void dump(HashMap&lt;?, ?> m) throws Exception {\n    Field t = HashMap.class.getDeclaredField("table");\n    t.setAccessible(true);\n    Object[] tab = (Object[]) t.get(m);\n    Field th = HashMap.class.getDeclaredField("threshold");\n    th.setAccessible(true);\n    System.out.println((tab == null ? 0 : tab.length)\n        + " / " + th.get(m));\n  }\n\n  public static void main(String[] args) throws Exception {\n    dump(new HashMap&lt;>());           // 0 / 0\n    dump(new HashMap&lt;>(32));         // 0 / 32\n    HashMap&lt;Object, Object> m = new HashMap&lt;>();\n    for (int i = 0; i &lt; 13; i++) m.put(i, i);\n    dump(m);                         // 32 / 24\n  }\n}</pre><b>要点</b>：table 是惰性创建的，第一次 put 才按 threshold 分配；new HashMap&lt;>(32) 只是把阈值预置成 2 的幂，此时 table 仍是 null。JDK 17 起 setAccessible 访问 java.base 的私有字段会抛 InaccessibleObjectException，要加 --add-opens java.base/java.util=ALL-UNNAMED。</div></details>',
        '构造 20 个 hashCode 相同的键，观察链表长度、树化时机以及扩容后的变化。<details class="tb-ans"><summary>参考答案</summary><div class="ans-body"><pre class="tb-ans-code" data-lang="java">import java.util.HashMap;\nimport java.util.Map;\n\npublic class Collide {\n  static final class K {\n    final int id;\n    K(int id) { this.id = id; }\n    @Override public int hashCode() { return 42; }\n    @Override public boolean equals(Object o) {\n      return o instanceof K k &amp;&amp; k.id == id;\n    }\n  }\n\n  public static void main(String[] args) {\n    Map&lt;K, Integer> m = new HashMap&lt;>();\n    for (int i = 0; i &lt; 20; i++) m.put(new K(i), i);\n    System.out.println(m.size());\n    System.out.println(m.get(new K(7)));\n  }\n}</pre><b>要点</b>：链表转红黑树的条件是桶内节点到 8（第 9 个触发）且 table 已到 64，没到 64 时 treeifyBin 只会扩容；所以冲突键一多先是反复扩容，之后才树化，查找最坏从 O(n) 降到 O(log n)。</div></details>',
        '统计一段英文文本的词频，分别用 get 判空和 merge 实现，比较代码量与可读性。<details class="tb-ans"><summary>参考答案</summary><div class="ans-body"><pre class="tb-ans-code" data-lang="java">import java.util.HashMap;\nimport java.util.Map;\n\npublic class WordCount {\n  public static void main(String[] args) {\n    String[] words = {"a", "b", "a", "c", "a"};\n    Map&lt;String, Integer> m = new HashMap&lt;>();\n    for (String w : words) {\n      Integer old = m.get(w);\n      m.put(w, old == null ? 1 : old + 1);\n    }\n    System.out.println(m.get("a"));\n    Map&lt;String, Integer> n = new HashMap&lt;>();\n    for (String w : words) n.merge(w, 1, Integer::sum);\n    System.out.println(n.equals(m));\n  }\n}</pre><b>要点</b>：merge(k, 1, Integer::sum) 在键不存在时直接放 1、存在时把旧值和 1 交给函数，只做一次哈希查找；注意 value 不能为 null（merge 会当键不存在处理），累加别用 computeIfAbsent。</div></details>',
        '写一个方法，接收预期元素个数，返回建议的初始容量，并解释为什么这样算。<details class="tb-ans"><summary>参考答案</summary><div class="ans-body"><pre class="tb-ans-code" data-lang="java">public class Cap {\n  static int cap(int expected, float load) {\n    if (expected &lt;= 0) return 16;\n    int c = (int) Math.ceil(expected / load) - 1;\n    c |= c >>> 1;  c |= c >>> 2;\n    c |= c >>> 4;  c |= c >>> 8;  c |= c >>> 16;\n    return c &lt; 0 ? 1 : c + 1;\n  }\n\n  public static void main(String[] args) {\n    System.out.println(cap(1000, 0.75f)); // 2048\n    System.out.println(cap(12, 0.75f));   // 16\n    System.out.println(cap(0, 0.75f));    // 16\n  }\n}</pre><b>要点</b>：HashMap 的容量必须是 2 的幂，构造器内部会自己取 tableSizeFor，所以只管算「期望元素数 / 0.75 上取整」；给少了会多一次扩容加 rehash，给多了纯浪费内存。putAll 已存在的表时还要减去当前 size。</div></details>',
        '用两个线程各向同一个 HashMap 写入十万条数据，观察最终 size，再换成 ConcurrentHashMap 对比。<details class="tb-ans"><summary>参考答案</summary><div class="ans-body"><pre class="tb-ans-code" data-lang="java">import java.util.HashMap;\nimport java.util.Map;\nimport java.util.concurrent.ConcurrentHashMap;\n\npublic class Race {\n  static final int N = 100_000;\n\n  static void hammer(Map&lt;Integer, Integer> m)\n      throws Exception {\n    Thread[] ts = new Thread[2];\n    for (int t = 0; t &lt; 2; t++) {\n      final int base = t * N;\n      ts[t] = new Thread(() -> {\n        for (int i = base; i &lt; base + N; i++) {\n          m.put(i, i);\n        }\n      });\n      ts[t].start();\n    }\n    for (Thread t : ts) t.join();\n    System.out.println(m.size());\n  }\n\n  public static void main(String[] args) throws Exception {\n    hammer(new HashMap&lt;>());\n    hammer(new ConcurrentHashMap&lt;>());\n  }\n}</pre><b>要点</b>：HashMap 没有任何并发保护，两个线程同时 ++size、同时扩容会丢更新，结果每次都不一样，极端情况老版本还会死循环；ConcurrentHashMap 稳定等于 200000，代价是不许 null 键和 null 值。</div></details>'
      ] }
    ]
  };


T['set-comparator'] = {
    meta: '本章约 6200 字 · 建议 38 分钟 · 配套 HashSet 流程图与 6 道习题',
    blocks: [
      { h: '4.1 为什么学 Set' },
      { p: 'List 允许重复、有顺序、能按下标访问，这些特性在“记录流水”时非常合适。但很多业务关心的不是第几条，而是“有没有”：用户是否已经投过票、手机号是否已经注册、文章标签是否重复、今天打卡过没有。这类需求的关键词是“唯一”，用 List 也能实现，但每次都要遍历判重，数据一多就慢。' },
      { p: 'Set 就是为“唯一性”设计的容器。它的语义来自数学上的集合：元素不重复，不关心顺序（至少在 HashSet 里），核心操作是 add、contains、remove。HashSet 把这三个操作的平均复杂度都做到了 O(1)，比 List 的 O(n) 判重快一个数量级。' },
      { p: '但 Set 的世界不只有 HashSet。LinkedHashSet 在去重的同时保留插入顺序，TreeSet 在去重的同时保持排序，还能做范围查询。它们背后分别对应 HashMap、LinkedHashMap、TreeMap，理解了上一章的 HashMap，这一章会轻松很多。' },
      { p: '另一个重点是“比较”。TreeSet 怎么知道谁在前谁在后？靠 Comparable 或 Comparator。这两个接口不只服务于 Set，也服务于排序、优先级队列、GroupBy 等大量场景。学会写正确的比较器，比记住几个 API 更有长期价值。' },
      { p: '在数据库里，唯一性通常靠唯一索引保证；在内存里，唯一性靠 Set。两者思路一致：维护一个能快速判断“是否已存在”的结构。区别是数据库要把索引落盘、支持事务和跨进程访问，而 Set 只在当前进程内有效。理解这一点，你就知道 Set 适合做单次请求内的去重，不适合做分布式环境下的全局去重。' },
      { h: '4.2 Set 的语义与去重' },
      { p: 'Set 接口继承自 Collection，但没有新增任何“按下标”的方法。它只承诺三件事：不含重复元素、最多包含一个 null（具体实现可能不允许）、add 返回 boolean 表示是否真的加入了。这个 boolean 很重要，它让你不用先 contains 再 add，一次调用就能知道结果。' },
      { p: '“不重复”的判定标准由实现决定。HashSet 和 LinkedHashSet 用 equals：两个元素 equals 为 true 就视为重复。TreeSet 用比较器：compare 或 compareTo 返回 0 就视为重复。这个差异是本章最重要的一条规则，后面会专门用一节展开。' },
      { p: 'Set 的 equals 也有明确定义：两个 Set 大小相同，且其中一个的所有元素都包含在另一个里，就相等。注意它不管顺序，也不管实现类，所以 HashSet 和 TreeSet 只要元素相同就可能相等。这一点和 List 不同，List 的 equals 要求顺序也一致。' },
      { p: '还有一个容易忽略的方法：addAll。它把另一个集合的元素逐个加进来，返回“是否有元素被真正加入”。如果两个集合有大量重叠，addAll 会做很多次无效的 add。这个返回值在“批量去重并判断是否有新增”的场景里很好用。' },
      { h: '4.3 HashSet 的底层结构' },
      { p: 'HashSet 内部并没有自己的哈希表，它直接持有一个 HashMap，把元素当作键，值统一放一个名为 PRESENT 的静态常量对象。所以 add(e) 实际是 map.put(e, PRESENT)，contains(e) 是 map.containsKey(e)，remove(e) 是 map.remove(e)。' },
      { p: '为什么可以这样复用？因为 Map 的键本来就是“不重复”的，正好对应 Set 的元素。值是什么并不重要，只要占位即可。这个设计让 HashSet 几乎零成本地获得了 HashMap 的全部能力：哈希定位、冲突链表、红黑树、扩容、树化。' },
      { p: '所以 HashSet 的容量、负载因子、树化阈值与 HashMap 完全一致：默认 16 个桶、0.75 负载因子、链表长度 8 且容量 64 才树化。你给 HashSet 构造器传的初始容量，最终也是传给内部 HashMap。理解这一点，就不需要单独背 HashSet 的扩容规则。' },
      { flow: ['计算元素的 hash（扰动）', '用 (n-1) & hash 定位桶', '桶为空则放入，返回 true', '桶内逐个比较 hash 与 equals', '找到相等元素则放弃插入，返回 false', '都不相等则挂到链表或树中，返回 true', 'size 加一，必要时扩容或树化'] },
      { p: '注意最后一步的返回值：只有真正插入新元素才返回 true。这意味着你可以用 <code>if (set.add(x))</code> 来判断“这是第一次出现”，在去重统计、防止重复提交、抽奖去重等场景里非常自然，比先 contains 再 add 少一次查找。' },
      { lang: 'java', code: 'import java.util.HashSet;\nimport java.util.Set;\n\npublic class HashSetBasic {\n    public static void main(String[] args) {\n        Set<String> tags = new HashSet<>();\n        System.out.println(tags.add("java"));     // 第一次，加入成功\n        System.out.println(tags.add("java"));     // 已存在，返回 false\n        tags.add("spring");\n        tags.add("mysql");\n\n        System.out.println(tags.size());          // 3\n        System.out.println(tags.contains("java")); // true\n        System.out.println(tags.remove("mysql"));  // true\n        System.out.println(tags.size());           // 2\n        System.out.println(tags.contains("mysql")); // false\n    }\n}', title: 'HashSetBasic.java' },
      { out: 'true\nfalse\n3\ntrue\ntrue\n2\nfalse' },
      { p: '这段代码里没有任何“判重”逻辑，但重复的 java 只被保留了一次。去重不是靠 add 时做特殊处理，而是靠“键唯一”这个底层语义。你写下的每一个元素，都在内部经历了一次哈希定位和相等性比较。' },
      { p: '有一点需要澄清：Set 的“不重复”是就相等性而言，不是就引用而言。两个内容相同的 String 对象，引用不同但 equals 相等，所以只保留一个；两个内容相同的数组，equals 用的是引用比较，所以都会保留。判断标准永远取决于元素类型自己的 equals 实现，而不是看上去像不像。' },
      { h: '4.4 去重靠的是 equals 与 hashCode' },
      { p: '上一章讲过，HashMap 用 hash 定位、用 equals 精确匹配。HashSet 复用同一套机制，所以自定义对象要正确去重，必须同时重写 equals 和 hashCode。只重写 equals，两个“逻辑相同”的对象 hash 不同，会落进不同的桶，HashSet 认为它们是两个元素，size 变成 2。' },
      { p: '这个错误在“用户去重”“订单去重”里非常常见，而且很隐蔽：代码看起来完全正确，add 了两次同一个业务对象，size 却是 2。排查时先看类有没有重写 hashCode，再看两个字段是不是都参与了计算，基本能定位。' },
      { p: '还有一种更隐蔽的情况：重写了 hashCode，但用的字段和 equals 不一致。比如 equals 比较 id 和 name，hashCode 只算 id。这样 equals 相等的对象 hash 一定相等（因为 id 相同），契约仍然满足，不会出错；但如果反过来，equals 只比 id，hashCode 却算了 name，两个 id 相同、name 不同的对象会落到不同桶，去重就失效了。' },
      { p: '规则可以记成一句话：equals 用到的字段，hashCode 必须全部用到；hashCode 用到的字段，equals 可以不用，但那样会降低散列质量。最稳妥的做法是两者使用完全相同的字段集合，并用 Objects.equals 和 Objects.hash 实现。' },
      { lang: 'java', code: 'import java.util.HashSet;\nimport java.util.Objects;\nimport java.util.Set;\n\npublic class DedupDemo {\n    static class User {\n        final String name;\n        User(String name) { this.name = name; }\n        @Override public boolean equals(Object o) {\n            return o instanceof User && ((User) o).name.equals(name);\n        }\n        // 故意不写 hashCode\n    }\n\n    static class FixedUser {\n        final String name;\n        FixedUser(String name) { this.name = name; }\n        @Override public boolean equals(Object o) {\n            return o instanceof FixedUser && ((FixedUser) o).name.equals(name);\n        }\n        @Override public int hashCode() { return Objects.hash(name); }\n    }\n\n    public static void main(String[] args) {\n        Set<User> bad = new HashSet<>();\n        bad.add(new User("amy"));\n        bad.add(new User("amy"));\n        System.out.println("未重写 hashCode: " + bad.size());   // 2\n\n        Set<FixedUser> good = new HashSet<>();\n        good.add(new FixedUser("amy"));\n        good.add(new FixedUser("amy"));\n        System.out.println("重写 hashCode: " + good.size());    // 1\n    }\n}', title: 'DedupDemo.java' },
      { out: '未重写 hashCode: 2\n重写 hashCode: 1' },
      { p: '如果元素是 String、Integer、枚举这些 JDK 类，它们已经正确实现了 equals 和 hashCode，直接放进去就行。需要自己写的情况只有一种：你定义了一个值对象，并希望“内容相同就算同一个”。这时候请把两个方法一起生成，不要只写一个。' },
      { h: '4.5 LinkedHashSet：去重且保留顺序' },
      { p: 'HashSet 的遍历顺序看起来是“乱”的，因为它按桶的下标顺序输出，而桶的位置由 hash 决定。很多业务虽然不需要排序，但希望“按加入的先后输出”，比如去重后的访问记录、按首次出现顺序排列的标签。这时候用 LinkedHashSet。' },
      { p: 'LinkedHashSet 继承 HashSet，内部还是一个 LinkedHashMap。它在哈希表的基础上额外维护了一条双向链表，把元素按插入顺序串起来。所以它既有 O(1) 的查找，又能按插入顺序遍历，代价是每个元素多两个指针，内存略高。' },
      { p: '注意“插入顺序”的含义：元素第一次加入时被串到链表尾部，重复加入不会改变它的位置。所以对 ["b", "a", "b"] 去重，结果是 [b, a]，而不是 [a, b]。这个特性常被用来做“最近浏览”“首次出现的词”这类需求。' },
      { p: 'LinkedHashSet 的“顺序”只影响遍历，不影响定位。它的 contains 仍然平均 O(1)，因为链表只是把元素额外串起来，桶定位还是靠 hash。所以不要以为“有顺序就等于变慢”，在 LinkedHashMap 这套实现里，顺序和查找是解耦的两件事。' },
      { lang: 'java', code: 'import java.util.HashSet;\nimport java.util.LinkedHashSet;\nimport java.util.Set;\n\npublic class LinkedHashSetDemo {\n    public static void main(String[] args) {\n        Integer[] data = {10, 3, 7, 3, 10, 5};\n\n        Set<Integer> hash = new HashSet<>();\n        Set<Integer> linked = new LinkedHashSet<>();\n        for (Integer n : data) {\n            hash.add(n);\n            linked.add(n);\n        }\n\n        System.out.println("HashSet: " + hash);\n        System.out.println("LinkedHashSet: " + linked);\n        System.out.println("大小相同: " + (hash.size() == linked.size()));\n    }\n}', title: 'LinkedHashSetDemo.java' },
      { out: 'HashSet: [3, 5, 7, 10]\nLinkedHashSet: [10, 3, 7, 5]\n大小相同: true' },
      { p: 'HashSet 输出 [3, 5, 7, 10]，恰好是升序，但这是 Integer 的 hash 等于自身、桶下标等于值 &amp; 15 造成的巧合，不是保证。换一批数据或换容量，顺序就会变。LinkedHashSet 输出 [10, 3, 7, 5]，严格按首次出现顺序，这才是可以依赖的行为。' },
      { h: '4.6 TreeSet 与自然顺序' },
      { p: 'TreeSet 和“List 排序”是两种不同思路。List 是先把元素全部放进去，需要时再调用 sort，排一次 O(n log n)；TreeSet 是每次插入都维护有序，单次 O(log n)，整体也是 O(n log n)，但任何时刻都能有序遍历、做范围查询。前者适合批量处理一次，后者适合持续插入并随时查询。' },
      { p: 'TreeSet 在去重的同时保持有序。它内部是一个 TreeMap，底层是红黑树，元素按大小排列，add、contains、remove 都是 O(log n)。因为要比较大小，TreeSet 不允许 null（自然顺序下），也不允许插入无法比较的类型。' },
      { p: '默认情况下，TreeSet 使用元素的“自然顺序”，也就是元素实现 Comparable 接口后定义的顺序。String 按字典序，Integer 按数值，LocalDate 按日期先后。这些 JDK 类都实现了 Comparable，所以可以直接放进 TreeSet。' },
      { p: '如果元素类型没有实现 Comparable，或者你不想用它的默认顺序，就必须在构造 TreeSet 时传入一个 Comparator。否则第一次 add 就会抛 ClassCastException，提示两个元素无法比较。这个异常信息很直白，看到它就知道该补比较器了。' },
      { p: 'TreeSet 的排序是“全局有序”的，不是插入时排一下。每次 add 都会沿红黑树找到正确位置插入，所以任何时候遍历都是有序的。这也意味着它的 add 比 HashSet 慢，因为要比较 log n 次，而 HashSet 平均只比较常数次。' },
      { lang: 'java', code: 'import java.util.Set;\nimport java.util.TreeSet;\n\npublic class ComparableDemo {\n    static class Person implements Comparable<Person> {\n        final String name;\n        final int age;\n        Person(String name, int age) { this.name = name; this.age = age; }\n\n        @Override public int compareTo(Person o) {\n            return Integer.compare(age, o.age);\n        }\n        @Override public String toString() { return name + "(" + age + ")"; }\n    }\n\n    public static void main(String[] args) {\n        TreeSet<Person> set = new TreeSet<>();\n        set.add(new Person("Amy", 31));\n        set.add(new Person("Bob", 25));\n        set.add(new Person("Cara", 28));\n\n        System.out.println(set);           // 按年龄升序\n        System.out.println(set.first());    // 最小\n        System.out.println(set.last());     // 最大\n    }\n}', title: 'ComparableDemo.java' },
      { out: '[Bob(25), Cara(28), Amy(31)]\nBob(25)\nAmy(31)' },
      { p: '注意 Comparable 是“类自己知道自己怎么比较”，所以实现一次，所有需要排序的地方都能用：TreeSet、TreeMap、Collections.sort、Arrays.sort、PriorityQueue。缺点是侵入性强，一个类只能有一种自然顺序，改了就影响所有调用方。' },
      { h: '4.7 Comparator：写法、返回值与契约' },
      { p: 'Comparator 把比较逻辑从类里拿出来，变成一个独立对象。它只有一个抽象方法 compare(a, b)，返回负数表示 a 排在 b 前，0 表示相等，正数表示 a 排在 b 后。因为是函数式接口，可以用 lambda 或方法引用简洁地写出来。' },
      { p: 'JDK 8 给 Comparator 加了一组静态工厂和默认方法，让链式写法成为可能。Comparator.comparing(取值函数) 按某个字段排序，thenComparing 处理相等时的次级排序，reversed 反转顺序，comparingInt 避免装箱。这些方法组合起来，几乎能表达所有常见排序需求。' },
      { p: '很多初学者记住“返回负数在前”就够用了，但理解内部怎么用这个返回值，能帮你写出更可靠的代码。排序算法在比较两个元素时，只关心结果的符号，不关心具体数值。返回 -1 和返回 -100 效果一样，返回 1 和 100 也一样。' },
      { p: '所以实现 compareTo 时，最简单的写法是 <code>return Integer.compare(this.age, o.age)</code>，而不是手写 if-else 返回 -1/0/1。Integer.compare 已经处理了溢出和边界，语义清晰，也不容易写错。对于字符串，用 String.compareTo；对于日期，用 LocalDate.compareTo。' },
      { p: '写比较器时不要用 <code>a - b</code> 这种写法。两个 int 相减可能溢出，比如 a 是很大的正数、b 是负数，结果会变成负数，排序就错了。正确做法是 Integer.compare(a, b)、Long.compare、Double.compare，或者直接用 Comparator.comparingInt。' },
      { p: '比较器还必须满足“契约”：自反（compare(a, a) 为 0）、反对称（compare(a, b) 与 compare(b, a) 符号相反）、传递（a &lt; b 且 b &lt; c 则 a &lt; c）。违反契约时，排序结果可能错乱，甚至抛 IllegalArgumentException: Comparison method violates its general contract。' },
      { p: '当多个字段参与排序时，先比主字段，主字段相等再比次字段。手写版本是一串 if，链式版本是 thenComparing。链式写法不仅短，而且每个字段的比较规则独立，容易调整顺序。比如“年龄升序、工资降序”，就是把 comparingInt(age) 和 comparingInt(salary).reversed() 串起来。' },
      { p: '降序还有另一种写法：<code>Comparator.comparing(Employee::getAge).reversed()</code>。注意 reversed 作用于整个比较器，位置不同效果不同。如果写 <code>comparing(...).thenComparing(...).reversed()</code>，是把“主+次”的整体顺序反转，而不是只反转次字段，这是常见的理解偏差。' },
      { p: '实践上，比较器最好是无状态、可复用的常量。把常用规则定义成 static final 字段，比如 BY_AGE_THEN_NAME，既避免每次排序都创建对象，也让规则集中在一处。Comparator 静态工厂返回的对象本身不可变，可以安全共享，不存在线程安全问题。' },
      { lang: 'java', code: 'import java.util.ArrayList;\nimport java.util.Comparator;\nimport java.util.List;\n\npublic class ComparatorDemo {\n    static class Employee {\n        final String name;\n        final int age;\n        final int salary;\n        Employee(String name, int age, int salary) {\n            this.name = name; this.age = age; this.salary = salary;\n        }\n        @Override public String toString() {\n            return name + "(" + age + ", " + salary + ")";\n        }\n    }\n\n    public static void main(String[] args) {\n        List<Employee> list = new ArrayList<>(List.of(\n                new Employee("Amy", 31, 12000),\n                new Employee("Bob", 25, 15000),\n                new Employee("Cara", 28, 12000),\n                new Employee("Dan", 25, 9000)));\n\n        list.sort(Comparator.comparingInt((Employee e) -> e.age)\n                .thenComparing(Comparator.comparingInt((Employee e) -> e.salary).reversed()));\n        list.forEach(System.out::println);\n\n        list.sort(Comparator.comparing((Employee e) -> e.name));\n        System.out.println("按姓名排序后首位: " + list.get(0).name);\n    }\n}', title: 'ComparatorDemo.java' },
      { out: 'Bob(25, 15000)\nDan(25, 9000)\nCara(28, 12000)\nAmy(31, 12000)\n按姓名排序后首位: Amy' },
      { p: '示例里直接用 lambda 访问字段：<code>(Employee e) -&gt; e.age</code>，因为 Employee 没有写 getter。如果字段是 private，就提供 getter 并改成方法引用 <code>Employee::getAge</code>，两种写法完全等价。lambda 的好处是不用为了排序给类加一堆方法，缺点是字段名散落在业务代码里，重构时不如方法引用安全。' },
      { table: { head: ['维度', 'Comparable', 'Comparator'], rows: [
        ['位置', '由元素类自己实现', '独立的对象，外部传入'],
        ['方法', 'int compareTo(T o)', 'int compare(T a, T b)'],
        ['顺序数量', '一种自然顺序', '可以按需定义任意多种'],
        ['是否侵入', '需要修改元素类', '不需要修改元素类'],
        ['典型用法', 'TreeSet 默认排序、Collections.sort', '多字段排序、临时规则、第三方类']
      ] } },
      { p: '排序还有一个“稳定性”概念：相等元素的相对顺序是否保持。Java 的 Collections.sort 和 List.sort 使用 TimSort，是稳定排序；TreeSet 则不保留相等元素的顺序，因为相等的元素根本不会被重复加入。需要稳定排序时用 List.sort，不要指望 TreeSet。' },
      { h: '4.8 TreeSet 用 compare 判重' },
      { p: '这是 TreeSet 最容易踩的坑：它判断两个元素是否重复，用的不是 equals，而是 compare 或 compareTo 是否返回 0。也就是说，只要比较结果为 0，哪怕 equals 返回 false，TreeSet 也认为它们是同一个元素，后加入的会被丢弃。' },
      { p: '最典型的例子是按字符串长度排序。两个长度相同的字符串，比较器返回 0，TreeSet 就只保留第一个。你可能会惊讶地发现 add 了三个元素，size 却只有 2；更意外的是 contains("dog") 返回 true，尽管 dog 从未被加入。这不是 bug，而是 TreeSet 的设计：有序集合的“相等”由顺序决定。' },
      { p: '这条规则还有一个推论：TreeSet 的 contains 也用比较器，不用 equals。所以一个元素能不能被找到，取决于比较器是否为它返回 0，而不是 equals 是否相等。如果你的比较器只比较了部分字段，就会把“部分相同”的对象当成同一个，导致数据丢失。' },
      { p: '正确的做法是让比较器在“业务上不相等”时一定返回非 0。多字段排序时，把能区分对象的字段都串进 thenComparing，最后再用一个唯一字段（比如 id）兜底。这样既保证了排序稳定，又避免了误判重复。' },
      { lang: 'java', code: 'import java.util.Comparator;\nimport java.util.TreeSet;\n\npublic class ComparatorTrap {\n    public static void main(String[] args) {\n        TreeSet<String> byLength = new TreeSet<>(Comparator.comparingInt(String::length));\n        byLength.add("cat");\n        byLength.add("dog");     // 长度也是 3，比较结果为 0\n        byLength.add("bird");\n\n        System.out.println(byLength);              // [cat, bird]\n        System.out.println(byLength.size());        // 2\n        System.out.println(byLength.contains("dog")); // true，虽然没被加入\n    }\n}', title: 'ComparatorTrap.java' },
      { out: '[cat, bird]\n2\ntrue' },
      { p: '如果业务确实需要“按长度排序但保留所有单词”，就不能用 TreeSet 去重。可以改用 List 加排序，或者用 TreeSet 但让比较器在长度相同时再按字典序比较：<code>Comparator.comparingInt(String::length).thenComparing(Comparator.naturalOrder())</code>。这样只有完全相同的字符串才返回 0。' },
      { h: '4.9 TreeSet 的范围查询' },
      { p: 'TreeSet 实现了 NavigableSet，提供了一组基于顺序的查询方法，这是 HashSet 完全做不到的。floor 返回小于等于给定值的最大元素，ceiling 返回大于等于给定值的最小元素，higher 和 lower 则是严格大于、严格小于。' },
      { p: '除了单点查询，还能取子集：headSet(to) 返回小于 to 的部分，tailSet(from) 返回大于等于 from 的部分，subSet(from, to) 返回左闭右开区间。这些子集是“视图”，不是拷贝，修改原集合会影响子集，反之亦然。用完如果不想互相影响，要复制一份。' },
      { p: '这些方法在“分数段统计”“时间区间查询”“排行榜区间”里非常实用。比如找出不及格最高分用 floor(59)，找出及格最低分用 ceiling(60)，取 70 到 90 分的人用 subSet(70, 90)。比起遍历整个集合再判断，O(log n) 的定位加区间遍历效率高得多。' },
      { lang: 'java', code: 'import java.util.TreeSet;\n\npublic class TreeSetNav {\n    public static void main(String[] args) {\n        TreeSet<Integer> scores = new TreeSet<>();\n        for (int s : new int[]{55, 62, 70, 78, 85, 91, 96}) {\n            scores.add(s);\n        }\n\n        System.out.println(scores.first() + " ~ " + scores.last());\n        System.out.println("floor(80) = " + scores.floor(80));\n        System.out.println("ceiling(80) = " + scores.ceiling(80));\n        System.out.println("lower(85) = " + scores.lower(85));\n        System.out.println("higher(85) = " + scores.higher(85));\n        System.out.println("headSet(80) = " + scores.headSet(80));\n        System.out.println("tailSet(85) = " + scores.tailSet(85));\n        System.out.println("subSet(70, 90) = " + scores.subSet(70, 90));\n    }\n}', title: 'TreeSetNav.java' },
      { out: '55 ~ 96\nfloor(80) = 78\nceiling(80) = 85\nlower(85) = 78\nhigher(85) = 91\nheadSet(80) = [55, 62, 70, 78]\ntailSet(85) = [85, 91, 96]\nsubSet(70, 90) = [70, 78, 85]' },
      { p: '注意 headSet 和 tailSet 的边界：headSet(80) 不包含 80，tailSet(85) 包含 85，subSet(70, 90) 包含 70 不包含 90。这是“左闭右开”的惯例，和数组下标、substring 一致。如果希望包含右端点，可以用重载方法传一个 boolean 参数。' },
      { table: { head: ['方法', '含义', '示例（集合 55,62,70,78,85,91,96）'], rows: [
        ['floor(x)', '小于等于 x 的最大元素', 'floor(80) = 78'],
        ['ceiling(x)', '大于等于 x 的最小元素', 'ceiling(80) = 85'],
        ['lower(x)', '严格小于 x 的最大元素', 'lower(85) = 78'],
        ['higher(x)', '严格大于 x 的最小元素', 'higher(85) = 91'],
        ['headSet(x)', '小于 x 的子集', '[55, 62, 70, 78]'],
        ['tailSet(x)', '大于等于 x 的子集', '[85, 91, 96]'],
        ['subSet(a, b)', '大于等于 a 且小于 b', '[70, 78, 85]']
      ] } },
      { h: '4.10 常见错误与调试' },
      { p: 'Set 的 API 很少，但语义细节多。下面这些错误在真实项目里都能见到，逐条对照可以避免大部分问题。' },
      { list: [
        '往 HashSet 放自定义对象，只重写 equals 不重写 hashCode，去重失效。',
        '用可变对象做元素，修改字段后 hashCode 变化，contains 找不到。',
        '以为 HashSet 的遍历顺序是插入顺序，换数据后输出变化。',
        'TreeSet 存没有实现 Comparable 的对象，且没传 Comparator，add 时抛 ClassCastException。',
        '比较器只比较部分字段，TreeSet 把不同对象当成重复，数据丢失。',
        '用 a - b 写比较器，数值跨度大时溢出，排序错乱。',
        '在 TreeSet 里 add null，自然顺序下直接 NullPointerException。',
        '把 subSet 当成拷贝，修改原集合后发现“子集也变了”。'
      ] },
      { p: '调试 Set 问题时，最先打印的应该是 size，而不是遍历结果。size 不对，说明去重规则有问题；size 对但 contains 不对，说明查找规则有问题；两者都对但顺序不对，才轮到考虑顺序。按这个顺序排查，能快速缩小范围，避免一上来就怀疑 JDK。' },
      { h: '4.11 选型与实战：去重、排序与选择' },
      { p: '把选型总结成一个简单流程：先问要不要去重，不要就用 List；要的话再问要不要顺序，不要就 HashSet；要插入顺序就 LinkedHashSet；要排序或范围查询就 TreeSet。最后再问是不是多线程，是就换并发容器。按这个顺序判断，基本不会选错。' },
      { p: '选哪个 Set，取决于三个问题：需不需要顺序？需不需要排序？追不追求极致性能？如果都不需要，HashSet 是默认答案；需要保留插入顺序，用 LinkedHashSet；需要有序、范围查询或按自定义规则排序，用 TreeSet。' },
      { p: '性能上，HashSet 的 add/contains 平均 O(1)，TreeSet 是 O(log n)。数据量在几万以内，两者差别不明显；到了百万级，HashSet 的优势才显现。但 TreeSet 提供的有序性和范围查询是 HashSet 给不了的，不能只看复杂度选型。' },
      { p: '还要注意线程安全。HashSet、LinkedHashSet、TreeSet 都不是线程安全的，多线程写入会出现与 HashMap 类似的问题。并发场景可以用 <code>ConcurrentHashMap.newKeySet()</code> 得到一个线程安全的 Set，或者用 Collections.synchronizedSet 包一层，但后者所有操作串行，性能一般。' },
      { p: '最后是“不可变集合”。JDK 9 的 <code>Set.of(...)</code> 可以创建不可变 Set，元素不能增删，传入重复元素会直接抛 IllegalArgumentException。它适合定义常量集合，比如权限码、白名单。注意它不允许 null，也不保证迭代顺序。' },
      { table: { head: ['实现', '底层', '顺序', 'add/contains', '允许 null', '去重依据'], rows: [
        ['HashSet', 'HashMap', '不保证', '平均 O(1)', '一个', 'hashCode + equals'],
        ['LinkedHashSet', 'LinkedHashMap', '插入顺序', '平均 O(1)', '一个', 'hashCode + equals'],
        ['TreeSet', 'TreeMap（红黑树）', '排序顺序', 'O(log n)', '不允许', 'compare/compareTo 为 0']
      ] } },
      { p: '还有一个小技巧：如果已经有 List，想一步去重并保持顺序，可以用 <code>new LinkedHashSet&lt;&gt;(list)</code>，它的构造器接收 Collection，会自动去重并保留首次出现顺序。反过来，Set 转 List 用 <code>new ArrayList&lt;&gt;(set)</code>。这类构造器转换比手写循环简洁得多。' },
      { h: '4.12 本章小结' },
      { list: [
        'Set 的核心语义是元素唯一，add 返回 boolean 表示是否真的加入。',
        'HashSet 内部是一个 HashMap，元素作键，值是一个常量占位对象。',
        'HashSet 去重依赖 hashCode 定位和 equals 比较，两者必须一起重写。',
        'LinkedHashSet 额外维护双向链表，保留插入顺序，重复加入不改变位置。',
        'TreeSet 基于红黑树，保持排序，add/contains 是 O(log n)。',
        'TreeSet 用 compare 或 compareTo 返回 0 判定重复，不看 equals，这是最大的坑。',
        'Comparable 是类内部的自然顺序，Comparator 是外部可插拔的比较规则。',
        '比较器返回负数在前、0 相等、正数在后，不要用相减避免溢出。'
      ] },
      { p: '还有一个细节：TreeSet 的 first()、last()、pollFirst()、pollLast() 都是 O(log n)，其中 poll 会把元素取出来并删除。做排行榜时常用 pollLast 取最高分并移除，比先 last 再 remove 少一次查找，语义也更清楚。' },
      { h: '4.13 常见追问' },
      { list: [
        '<b>问：HashSet 为什么是无序的？</b><br>答：因为它内部就是一个 HashMap，元素当键存放，遍历时按底层数组的桶下标顺序走，而下标由元素的 hashCode 经过扰动与取模得到，与插入的先后毫无关系。所以只要元素的哈希值稳定，同一个集合的遍历顺序在同一 JDK 版本下是稳定的，但它既不等于插入顺序，也不等于大小顺序。需要顺序时用 LinkedHashSet 保留插入顺序，或用 TreeSet 按比较器排序。',
        '<b>问：Comparable 和 Comparator 该怎么选？</b><br>答：类只有一个「天然就该这样排」的顺序时，让它实现 Comparable，把规则写在 compareTo 里，好处是 TreeSet、TreeMap、<code>Collections.sort</code>、<code>max</code> 等都能直接用。同一个类需要多种排法、或者根本改不了它的源码时，用 Comparator 外部传入，还可以用 <code>comparing</code>、<code>thenComparing</code> 组合出多级规则。两者可以共存：Comparable 给默认顺序，Comparator 给临时规则，显式传入的 Comparator 优先。',
        '<b>问：TreeSet 能存 null 吗？</b><br>答：不能。TreeSet 依靠比较来定位元素，第一个元素为 null 时后续要调用 <code>null.compareTo(e)</code>，第二个元素为 null 时比较器也要拿 null 参与，无论哪种情况都会抛 NullPointerException。这与 HashSet、LinkedHashSet 都不同——它们只看哈希，null 有固定哈希值，所以能存一个。要允许空值就用 HashSet 并单独处理，或把 null 换成哨兵对象。',
        '<b>问：LinkedHashSet 中重复加入会打乱原有顺序吗？</b><br>答：不会。重复加入时 add 返回 false，元素本身没有被替换，它在双向链表中的位置保持原样，因此顺序仍然是「首次插入的顺序」。但要注意它判重的依据依然是 equals 与 hashCode：如果你放入一个字段相同的新对象，旧对象保留、新对象被丢弃，取出来的是先放进去的那个实例，这一点在可变对象上尤其容易踩坑。',
        '<b>问：Set 的 equals 是怎么判断相等的？</b><br>答：按接口契约，两个集合相等当且仅当大小相同、且其中一个的每个元素都被另一个包含，也就是纯粹看元素集合，与实现类无关、与顺序无关。所以一个 HashSet 和一个 LinkedHashSet 只要元素相同就相等。代价是这个判断是 O(n) 次查找；另外 Set 的 hashCode 被定义为所有元素哈希之和，这也是有些团队不建议把大集合放进另一个哈希容器的原因。',
        '<b>问：并发场景下该用什么 Set？</b><br>答：优先 <code>ConcurrentHashMap.newKeySet()</code>，它返回一个基于并发哈希表的 Set，add、remove、contains 都是线程安全的，且读操作几乎无锁。它没有 CopyOnWriteArraySet 那种「写时复制整份数组」的开销，适合写也不少见的场景；后者的优势只在于迭代时不需要加锁、且迭代器看到的是快照，适合监听器列表这类读多写极少的结构。<code>Collections.synchronizedSet</code> 则是整表一把锁，只在低并发时够用。'
      ] },

      { h: '4.14 自测与练习' },
      { ol: [
        '定义一个 Book 类（isbn、title），正确实现 equals 和 hashCode，用 HashSet 验证同一 isbn 只保留一本。<details class="tb-ans"><summary>参考答案</summary><div class="ans-body"><pre class="tb-ans-code" data-lang="java">import java.util.HashSet;\nimport java.util.Objects;\nimport java.util.Set;\n\npublic class Book {\n  private final String isbn;\n  private final String title;\n\n  Book(String isbn, String title) {\n    this.isbn = isbn;\n    this.title = title;\n  }\n\n  @Override\n  public boolean equals(Object o) {\n    if (this == o) return true;\n    if (!(o instanceof Book b)) return false;\n    return isbn.equals(b.isbn);\n  }\n\n  @Override\n  public int hashCode() { return Objects.hash(isbn); }\n\n  public static void main(String[] args) {\n    Set&lt;Book> s = new HashSet&lt;>();\n    s.add(new Book("978", "A"));\n    s.add(new Book("978", "A"));\n    System.out.println(s.size());   // 1\n  }\n}</pre><b>要点</b>：equals 和 hashCode 必须只用同一组字段（这里是 isbn）；hashCode 里不要放可变字段，也不要放 title 这类不参与 equals 的字段，否则两个「相等」对象的哈希不同，HashSet 去重直接失效。</div></details>',
        '用 LinkedHashSet 统计一段文字中出现过的单词，按首次出现顺序输出。<details class="tb-ans"><summary>参考答案</summary><div class="ans-body"><pre class="tb-ans-code" data-lang="java">import java.util.HashSet;\nimport java.util.LinkedHashSet;\nimport java.util.Set;\n\npublic class FirstSeen {\n  public static void main(String[] args) {\n    String text = "b a c a b";\n    Set&lt;String> s = new LinkedHashSet&lt;>();\n    for (String w : text.split("\\\\s+")) s.add(w);\n    System.out.println(s);\n    System.out.println(new HashSet&lt;>(s));\n  }\n}</pre><b>要点</b>：LinkedHashSet 多维护一条双向链表记住插入顺序，代价是每个元素两个额外引用；重复 add 不会改变它原来的位置，所以它同时也适合做「按首次出现顺序去重」。</div></details>',
        '让 Person 实现 Comparable 按年龄排序，再用 Comparator 改成按姓名长度、再按年龄排序。<details class="tb-ans"><summary>参考答案</summary><div class="ans-body"><pre class="tb-ans-code" data-lang="java">import java.util.ArrayList;\nimport java.util.Comparator;\nimport java.util.List;\n\npublic class SortP {\n  record Person(String name, int age)\n      implements Comparable&lt;Person> {\n    @Override\n    public int compareTo(Person o) {\n      return Integer.compare(age, o.age);\n    }\n  }\n\n  public static void main(String[] args) {\n    List&lt;Person> l = new ArrayList&lt;>(List.of(\n        new Person("Amy", 30), new Person("Bob", 20),\n        new Person("Cara", 25)));\n    l.sort(null);\n    System.out.println(l);\n    l.sort(Comparator.comparingInt(\n            (Person p) -> p.name().length())\n        .thenComparingInt(Person::age));\n    System.out.println(l);\n  }\n}</pre><b>要点</b>：Comparable 是类内的唯一自然序，Comparator 是外挂的任意序，写了 Comparator 就用 sort(c) 而不是改 compareTo；int 相减会溢出，写 Integer.compare(a, b) 才稳，l.sort(null) 表示用自然序。</div></details>',
        '构造一个只按长度比较的 TreeSet，观察 size 和 contains 的结果，解释原因。<details class="tb-ans"><summary>参考答案</summary><div class="ans-body"><pre class="tb-ans-code" data-lang="java">import java.util.Set;\nimport java.util.TreeSet;\n\npublic class ByLen {\n  public static void main(String[] args) {\n    Set&lt;String> s = new TreeSet&lt;>(\n        (a, b) -> a.length() - b.length());\n    s.add("a");\n    s.add("b");\n    s.add("cc");\n    System.out.println(s.size());          // 2\n    System.out.println(s.contains("a"));   // true\n    System.out.println(s.contains("zz"));  // true，错\n  }\n}</pre><b>要点</b>：TreeSet 判重只看 comparator 的返回值，根本不调用 equals：长度相同就被当成同一个元素，contains 也因此误判。比较器必须与 equals 语义一致，或者在比较里再补一个能区分全序的键。</div></details>',
        '用 TreeSet 实现一个分数段查询：给定 60 到 80，输出区间内的所有分数。<details class="tb-ans"><summary>参考答案</summary><div class="ans-body"><pre class="tb-ans-code" data-lang="java">import java.util.NavigableSet;\nimport java.util.TreeSet;\n\npublic class ScoreR {\n  public static void main(String[] args) {\n    TreeSet&lt;Integer> s = new TreeSet&lt;>();\n    for (int v : new int[] {55, 62, 78, 80, 91}) s.add(v);\n    NavigableSet&lt;Integer> r = s.subSet(60, true, 80, true);\n    System.out.println(r);           // [62, 78, 80]\n    System.out.println(s.headSet(60));  // [55]\n    System.out.println(s.higher(78));   // 80\n  }\n}</pre><b>要点</b>：subSet(60, 80) 这个两参版本的右端是开区间，含 80 必须用四参版或写 subSet(60,true,80,true)；返回的是原集合的视图，往里 add 会写到原表，且只能加落在区间内的元素。</div></details>',
        '对比 HashSet 和 TreeSet 插入 10 万个随机整数的时间，并解释差异。<details class="tb-ans"><summary>参考答案</summary><div class="ans-body"><pre class="tb-ans-code" data-lang="java">import java.util.HashSet;\nimport java.util.Random;\nimport java.util.Set;\nimport java.util.TreeSet;\n\npublic class Speed {\n  static long time(Set&lt;Integer> s, int[] a) {\n    for (int v : a) s.add(v);\n    long t = System.nanoTime();\n    for (int v : a) s.add(v);\n    return (System.nanoTime() - t) / 1_000_000;\n  }\n\n  public static void main(String[] args) {\n    Random r = new Random(1);\n    int[] a = new int[100_000];\n    for (int i = 0; i &lt; a.length; i++) a[i] = r.nextInt();\n    long h = time(new HashSet&lt;>(), a);\n    long t = time(new TreeSet&lt;>(), a);\n    System.out.println("HashSet " + h);\n    System.out.println("TreeSet " + t);\n  }\n}</pre><b>要点</b>：HashSet 靠 hashCode 定位桶，均摊 O(1)；TreeSet 每次插入要走 O(log n) 次比较，通常慢一个数量级，换来的是有序与区间查询。计时前要先预热并固定随机种子，否则单次数字不可复现。</div></details>'
      ] },
      { note: '<b>练习建议：</b>用 JShell 或单元测试快速验证 add 的返回值、size 的变化与 contains 的结果；遇到「为什么没去重」「为什么顺序不对」，先打印 size 和元素，再回头检查 equals、hashCode 或比较器。' }
    ]
  };


T['iterator-queue'] = {
    meta: '本章约 6400 字 · 建议 40 分钟 · 配套堆调整流程图与 6 道习题',
    blocks: [
      { h: '5.1 为什么学迭代器与队列' },
      { p: '前面几章我们一直用增强 for 遍历集合，写起来很舒服，但从没解释过它背后是什么。为什么有的集合能用增强 for，有的不能？为什么遍历时删除元素会抛异常？为什么 Iterator 的 remove 就能安全删除？这些问题的答案都在 Iterable 和 Iterator 这两个接口里。' },
      { p: '队列则是另一类完全不同的需求。List 和 Set 关心“存了哪些”，队列关心“按什么顺序取”。现实中的消息队列、任务调度、打印队列、广度优先搜索，本质都是“先进先出”；而操作系统调度、带优先级的任务、求 Top K，则需要“每次取最小或最大”，这就是优先队列。' },
      { p: 'Java 的 Queue 是一个接口，ArrayDeque 和 LinkedList 实现了它，PriorityQueue 则用堆实现。堆是本章的难点：它用数组存一棵完全二叉树，靠上浮和下沉维持“父节点总是不大于子节点”的性质。理解堆之后，你就能解释为什么 PriorityQueue 的 peek 是 O(1)，而 poll 是 O(log n)。' },
      { p: '这一章分两条线：前半部分讲迭代器，包括 for-each 的本质、游标、fail-fast、ListIterator；后半部分讲队列，包括 Queue 的两组方法、ArrayDeque 的循环数组、PriorityQueue 的堆结构和常见坑。两条线最后汇合到“如何在遍历中安全地删除元素”这个实际问题上。' },
      { p: '队列在现实系统里无处不在：打印机任务按提交顺序排队，消息中间件把生产者和消费者解耦，线程池的任务队列等待空闲线程，广度优先搜索把待访问节点依次入队。它们的共同点是不能乱序，先到的必须先被处理。' },
      { h: '5.2 Iterable、Iterator 与迭代器的游标' },
      { p: 'Iterator 只有四个方法：hasNext 判断还有没有下一个，next 返回下一个并移动游标，remove 删除最近返回的元素，forEachRemaining 一次性消费剩余元素。前两个是核心，后两个是便利方法，其中 remove 在 JDK 8 里是默认方法，默认实现直接抛 UnsupportedOperationException。' },
      { p: '游标是理解迭代器的关键。以 ArrayList 为例，迭代器内部有一个 cursor，表示“下一个要返回的元素下标”，初始为 0。调用 next 时，先检查 cursor 是否越界，然后把 cursor 的值赋给 lastRet，cursor 加一，返回 elementData[lastRet]。所以 next 返回的是“游标刚才指的那个元素”。' },
      { p: 'remove 依赖 lastRet：它删除的是上一次 next 返回的元素。如果还没调用过 next，或者刚刚 remove 过，lastRet 就是 -1，此时调用 remove 会抛 IllegalStateException。删除之后，游标要回退一位，因为后面的元素整体前移了，这也是为什么 remove 之后不能连续再 remove。' },
      { p: 'hasNext 只是比较 cursor 和 size，O(1)。所以“先用 hasNext 判断再 next”是标准写法，能避免 NoSuchElementException。有些人喜欢用 try-catch 包住 next 来结束循环，这种写法能跑，但把正常流程当异常处理，性能和可读性都不好。' },
      { p: 'forEachRemaining 接收一个 Consumer，把剩下的元素依次传进去。它在内部仍然是循环调用 next，所以同样会做 fail-fast 检查。JDK 8 之后很多遍历都可以用它简化，但要注意它一旦开始就会消费到末尾，不能中途 break。' },
      { table: { head: ['方法', '作用', '注意事项'], rows: [
        ['hasNext()', '是否还有下一个元素', 'O(1)，不移动游标'],
        ['next()', '返回下一个元素并前移', '越界抛 NoSuchElementException'],
        ['remove()', '删除最近返回的元素', '未调用 next 或重复调用抛 IllegalStateException'],
        ['forEachRemaining()', '消费剩余全部元素', '不能中途停止，同样受 fail-fast 影响']
      ] } },
      { p: '能用于增强 for 的集合，必须实现 <code>Iterable</code> 接口。这个接口只有一个抽象方法 <code>iterator()</code>，返回一个 Iterator 对象。Collection 继承 Iterable，所以 List、Set、Queue 都能用增强 for；而 Map 没有继承 Iterable，所以不能直接 for-each，只能遍历它的 keySet、values 或 entrySet。' },
      { p: 'Iterable 表示“可以被迭代”，Iterator 表示“这一次迭代的游标”。前者是能力，后者是状态。同一个集合可以同时创建多个 Iterator，它们各自维护自己的游标，互不干扰；但如果有线程或代码修改了集合结构，所有迭代器都会因为 fail-fast 而失效。' },
      { p: '增强 for 只是语法糖。编译器会把 <code>for (String s : list)</code> 改写成“先调用 iterator()，再循环 hasNext() 和 next()”。所以增强 for 里不能删除元素，不是语法限制，而是它没有暴露迭代器变量，你只能调用集合的 remove，而那会破坏 modCount。' },
      { p: '自己实现一个可迭代类型也不难：实现 Iterable，返回一个带 hasNext 和 next 的 Iterator 即可。JDK 里很多类都这么做，比如文件行读取、目录遍历、数据库结果集。理解了这套协议，你就能把任何“逐个产出数据”的逻辑包装成可以用 for-each 的形式。' },
      { lang: 'java', code: 'import java.util.ArrayList;\nimport java.util.Iterator;\nimport java.util.List;\n\npublic class IteratorBasics {\n    public static void main(String[] args) {\n        List<String> list = new ArrayList<>(List.of("a", "b", "c"));\n        Iterator<String> it = list.iterator();\n\n        while (it.hasNext()) {\n            String s = it.next();\n            if (s.equals("b")) {\n                it.remove();       // 用迭代器删除，安全\n            }\n        }\n\n        System.out.println(list);        // [a, c]\n        System.out.println(it.hasNext()); // false\n    }\n}', title: 'IteratorBasics.java' },
      { out: '[a, c]\nfalse' },
      { h: '5.3 fail-fast 与并发修改' },
      { p: 'fail-fast 的实现依赖一个 modCount 字段。集合每次结构性修改（add、remove、clear）都会让 modCount 加一；迭代器创建时把当前值存进 expectedModCount；每次 next 或 remove 前比较两者，不相等就抛 ConcurrentModificationException。' },
      { p: '这套机制是“尽早失败”，不是“并发安全”。它不能保证一定检测到修改，也不能保证多线程下数据正确。Java 文档明确说 fail-fast 是最佳努力，不能依赖它做业务判断。真正的并发场景要用 ConcurrentHashMap、CopyOnWriteArrayList 这类容器。' },
      { p: '还有个细节：set 不算结构性修改，不会改变 modCount，所以遍历时调用 set 是安全的，不会触发异常。但 set 会改变元素内容，如果元素参与了 hashCode 或排序，可能破坏集合的内部结构，这种“逻辑上的不一致”比异常更难排查。' },
      { p: '遍历时删除元素的正确姿势有三种：用 Iterator.remove；用 <code>removeIf</code> 传一个谓词；用 <code>Collection.removeAll</code> 批量删除。前两种最常用，removeIf 在内部就是用迭代器实现的，代码最短，推荐优先使用。' },
      { p: '这段代码如果改成 <code>list.remove(s)</code>，会在下一次 next 时抛 ConcurrentModificationException。原因不是“不能在遍历时删除”，而是“不能用集合的方法删除”。迭代器的 remove 会同步更新 expectedModCount，所以它能感知到这次修改是自己做的，不会误报。' },
      { h: '5.4 ListIterator：双向迭代' },
      { p: 'ListIterator 是 Iterator 的子接口，只对 List 可用。它多了向前遍历的能力：hasPrevious、previous、nextIndex、previousIndex，还多了 set 和 add 两个修改方法。可以把它想成一个可以在元素之间来回移动的游标。' },
      { p: 'set 替换上一次 next 或 previous 返回的元素，不改变游标位置；add 在游标当前位置插入元素，插入后游标后移一位，所以新元素会出现在“刚返回的元素”之后。这两个方法经常被用来做原地转换，比如把所有字符串转大写，或者在每个元素前插入标记。' },
      { p: 'ListIterator 还可以指定起始位置：<code>list.listIterator(index)</code> 让游标从 index 开始。这让它适合做“从中间向前找”的操作，比如在有序列表里向前查找第一个满足条件的元素。普通 Iterator 只能从头到尾，做不到这一点。' },
      { lang: 'java', code: 'import java.util.ArrayList;\nimport java.util.List;\nimport java.util.ListIterator;\n\npublic class ListIteratorDemo {\n    public static void main(String[] args) {\n        List<String> list = new ArrayList<>(List.of("a", "b", "c"));\n        ListIterator<String> it = list.listIterator();\n\n        while (it.hasNext()) {\n            int i = it.nextIndex();\n            String s = it.next();\n            it.set(s.toUpperCase());   // 替换，不改变游标\n            if (i == 0) {\n                it.add("start");       // 在游标处插入\n            }\n        }\n\n        System.out.println(list);\n        System.out.println(it.hasPrevious());\n        System.out.println(it.previous());\n    }\n}', title: 'ListIteratorDemo.java' },
      { out: '[A, start, B, C]\ntrue\nC' },
      { p: '逐行走一遍：初始游标 0；第一次 next 返回 a，set 改成 A，i 为 0 所以 add 插入 start，游标变成 2；第二次 next 返回 b，改成 B；第三次 next 返回 c，改成 C。最终列表是 [A, start, B, C]，游标在末尾，hasPrevious 为 true，previous 返回 C。' },
      { h: '5.5 Queue 接口与两组方法' },
      { p: 'Queue 继承 Collection，语义是“先进先出”。它在 Collection 的基础上增加了三个动作：在尾部加入、从头部取出并删除、查看头部但不删除。每个动作都提供了两种形式：一种失败时抛异常，一种失败时返回特殊值。' },
      { p: '为什么要有两组方法？因为“队列满”和“队列空”在不同场景下的处理方式不同。有界队列满了，生产者可能希望阻塞或返回 false，而不是抛异常；空队列取元素，消费者可能希望拿到 null 继续循环，而不是中断。offer/poll/peek 就是为这种“柔性处理”准备的。' },
      { p: '实际开发中优先用 offer、poll、peek。它们不会用异常控制流程，代码更清晰。只有在“队列满或空属于程序错误”的场景下，才用 add、remove、element 让异常尽早暴露。这个选择标准和“用返回值还是抛异常”的一般原则一致。' },
      { table: { head: ['动作', '抛异常版本', '返回特殊值版本', '失败时'], rows: [
        ['入队', 'add(e)', 'offer(e)', 'add 抛 IllegalStateException，offer 返回 false'],
        ['出队', 'remove()', 'poll()', 'remove 抛 NoSuchElementException，poll 返回 null'],
        ['查看队首', 'element()', 'peek()', 'element 抛异常，peek 返回 null']
      ] } },
      { lang: 'java', code: 'import java.util.LinkedList;\nimport java.util.Queue;\n\npublic class QueueOps {\n    public static void main(String[] args) {\n        Queue<String> q = new LinkedList<>();\n        System.out.println(q.offer("a"));  // true，入队成功\n        System.out.println(q.offer("b"));  // true\n        System.out.println(q.peek());      // a，只看不删\n        System.out.println(q.poll());      // a，取出并删除\n        System.out.println(q.size());      // 1\n        System.out.println(q.poll());      // b\n        System.out.println(q.poll());      // null，队列已空\n        System.out.println(q.peek());      // null，空队列\n    }\n}', title: 'QueueOps.java' },
      { out: 'true\ntrue\na\na\n1\nb\nnull\nnull' },
      { p: 'Queue 不定义“是否允许 null”。LinkedList 允许 null，所以 poll 返回 null 时无法区分“空队列”和“队首就是 null”；ArrayDeque 和 PriorityQueue 不允许 null，避免了这种歧义。这也是推荐用它们而不是 LinkedList 做队列的原因之一。' },
      { h: '5.6 Deque 与 ArrayDeque' },
      { p: 'Deque 是“双端队列”，两端都能进出的队列。它继承 Queue，额外提供了 addFirst、addLast、offerFirst、offerLast、pollFirst、pollLast、peekFirst、peekLast，以及 push 和 pop。因为两端都可操作，它既能当队列（FIFO），也能当栈（LIFO）。' },
      { p: 'ArrayDeque 是 Deque 的数组实现，内部用一个循环数组加 head、tail 两个指针。所谓循环，是指当指针走到数组末尾时，回绕到下标 0 继续用，这样头尾操作都不需要搬移元素，都是 O(1)。容量是 2 的幂，扩容时翻倍。' },
      { p: '它不允许 null，因为要用 null 表示“空位置”。作为栈用时，push 加到头部，pop 从头部取；作为队列用时，offerLast 加到尾部，pollFirst 从头部取。两种用法共用同一个结构，只是调用不同的方法。' },
      { p: '为什么不用 Stack 类？Stack 继承 Vector，所有方法都加了 synchronized，单线程下也有锁开销；而且它的 API 设计较老，继承关系也不合理。JDK 文档明确推荐用 ArrayDeque 实现栈。同理，做队列也优先 ArrayDeque，而不是 LinkedList。' },
      { lang: 'java', code: 'import java.util.ArrayDeque;\nimport java.util.Deque;\n\npublic class ArrayDequeDemo {\n    public static void main(String[] args) {\n        Deque<Integer> stack = new ArrayDeque<>();\n        stack.push(1);\n        stack.push(2);\n        stack.push(3);\n        System.out.println(stack.pop());    // 3\n        System.out.println(stack.peek());   // 2\n\n        Deque<String> queue = new ArrayDeque<>();\n        queue.offerLast("a");\n        queue.offerLast("b");\n        queue.offerFirst("z");\n        System.out.println(queue);            // [z, a, b]\n        System.out.println(queue.pollFirst()); // z\n        System.out.println(queue.pollLast());  // b\n    }\n}', title: 'ArrayDequeDemo.java' },
      { out: '3\n2\n[z, a, b]\nz\nb' },
      { p: 'push 等价于 addFirst，pop 等价于 removeFirst，所以栈的“后进先出”正好对应头部操作。队列部分先放 a、b，再从头部放 z，得到 [z, a, b]；pollFirst 取 z，pollLast 取 b，剩下 [a]。所有操作都在两端，没有一次搬移整个数组。' },
      { p: '堆还经常和图的算法一起出现：Dijkstra 最短路每次取当前距离最小的节点，Prim 最小生成树每次取权值最小的边，A* 搜索每次取估价函数最小的节点。这些算法之所以高效，就是因为堆能在 O(log n) 内取出最小值，而不用把所有候选排一遍序。' },
      { h: '5.7 PriorityQueue 与堆' },
      { p: 'PriorityQueue 不是“先进先出”，而是“优先级最高的先出”。默认情况下，优先级由元素的自然顺序决定，最小的元素在队首，所以它默认是一个小顶堆。每次 poll 取出的都是当前最小的元素，而不是最早加入的元素。' },
      { p: '它的底层是一个数组，逻辑上是一棵完全二叉树。数组下标 i 的节点，父节点是 (i-1)/2，左孩子是 2i+1，右孩子是 2i+2。所谓“完全”，是指除了最后一层，其他层都填满，最后一层靠左连续排列。这个性质让树可以紧凑地存进数组，不需要额外的左右指针。' },
      { p: '堆的性质是：每个节点的值都不大于它的孩子（小顶堆）。注意它只保证“父不大于子”，不保证“左子树全部小于右子树”，也不保证数组整体有序。所以堆只能快速拿到最小值，不能快速做范围查询，也不能按顺序遍历。' },
      { p: '这就是为什么 PriorityQueue 的 peek 是 O(1)：最小值就在数组下标 0。而 poll 需要把末尾元素移到根，再一路下沉恢复堆序，是 O(log n)。offer 把新元素放到末尾，再一路上浮，也是 O(log n)。' },
      { p: 'PriorityQueue 默认初始容量是 11，扩容策略和 ArrayList 不同：容量小于 64 时翻倍，否则按 1.5 倍增长。它不允许 null，因为插入时要调用比较，null 会直接导致 NullPointerException。它也不是线程安全的，并发场景要用 PriorityBlockingQueue。' },
      { lang: 'java', code: 'import java.util.PriorityQueue;\n\npublic class PriorityQueueBasics {\n    public static void main(String[] args) {\n        PriorityQueue<Integer> pq = new PriorityQueue<>();\n        for (int n : new int[]{5, 1, 9, 3, 7}) {\n            pq.offer(n);\n        }\n\n        System.out.println(pq.peek());   // 1，最小值在堆顶\n        System.out.println(pq);          // 堆的内部数组，不是有序的\n\n        while (!pq.isEmpty()) {\n            System.out.print(pq.poll() + " ");\n        }\n        System.out.println();\n    }\n}', title: 'PriorityQueueBasics.java' },
      { out: '1\n[1, 3, 9, 5, 7]\n1 3 5 7 9' },
      { p: '注意第二行输出 [1, 3, 9, 5, 7]，它既不是插入顺序，也不是升序，而是堆的数组布局。3 是 1 的孩子，9 是 1 的另一个孩子，5 和 7 是 3 的孩子。这个布局满足“父不大于子”，但整体并不有序。只有连续 poll，才能得到完整的升序序列。' },
      { h: '5.8 上浮与下沉' },
      { p: '堆的所有操作都围绕两条路径：上浮和下沉。上浮用于插入：新元素放到数组末尾，然后不断和父节点比较，如果比父节点小就交换，直到到达根或者父节点已经更小。下沉用于删除堆顶：把末尾元素移到根，然后不断和较小的孩子比较，如果比孩子大就交换，直到到达叶子或者已经满足堆序。' },
      { flow: ['新元素放到数组末尾', '与父节点 (i-1)/2 比较', '小于父节点则交换，继续向上', '到达根或父节点更小则停止', 'poll 时取出下标 0 的元素', '把末尾元素移到根，size 减一', '与较小的孩子比较，大于则交换', '到达叶子或满足堆序则停止'] },
      { p: '上浮的交换次数最多是树高，也就是 log n。因为完全二叉树的高度是 log₂n，所以插入是 O(log n)。下沉同理，每次下降一层，最多 log n 次。这就是堆操作复杂度的来源，不需要背，画一棵树就能推出来。' },
      { p: '为什么下沉要和“较小的孩子”比较？因为小顶堆要求父节点不大于两个孩子。如果父节点比两个孩子都大，它必须和较小的那个交换，换完之后新的父节点才会比另一个孩子小；如果和较大的孩子交换，换上去的仍然是较大的值，可能还是比另一个孩子大，就要再换一次，效率更低。' },
      { p: '建堆还有一个小优化：如果一次性把无序数组建成堆，不需要逐个 offer，而是从最后一个非叶子节点开始，依次向前对每个节点下沉。这样做的复杂度是 O(n)，比逐个插入的 O(n log n) 更快。PriorityQueue 的构造器接收 Collection 时，用的就是这个方法。' },
      { table: { head: ['操作', '做法', '复杂度'], rows: [
        ['peek()', '直接取数组下标 0', 'O(1)'],
        ['offer(e)', '放到末尾再上浮', 'O(log n)'],
        ['poll()', '取堆顶，末尾移到根再下沉', 'O(log n)'],
        ['remove(Object)', '线性查找后再删除并调整', 'O(n)'],
        ['contains(Object)', '线性扫描数组', 'O(n)'],
        ['建堆（构造器）', '从最后一个非叶子节点依次下沉', 'O(n)']
      ] } },
      { h: '5.9 构造器与比较器' },
      { p: 'PriorityQueue 有多个构造器：无参构造使用默认容量 11 和自然顺序；传一个 int 指定初始容量；传一个 Comparator 指定比较规则；传一个 Collection 把已有元素建堆；传一个 PriorityQueue 或 SortedSet 复制。最常用的是前三个。' },
      { p: '一旦传入 Comparator，元素就不需要实现 Comparable。比较器返回负数表示 a 的优先级更高（排在前面），返回正数表示 b 的优先级更高。注意这里的“前面”对应“先出队”，所以小顶堆的比较器应该让较小的元素返回负数。' },
      { p: '要构造大顶堆，可以传 <code>Comparator.reverseOrder()</code>，它会反转自然顺序；也可以写 <code>(a, b) -&gt; b - a</code>，但这种写法在数值跨度大时会溢出，不推荐。更安全的写法是 <code>Comparator.comparingInt(x -&gt; -x)</code> 或者直接 reverseOrder。' },
      { p: '如果元素是自定义对象，比较器要保证“所有不相等的对象比较结果非 0”，否则堆无法区分它们，行为不确定。这一点和 TreeSet 的规则类似：比较器定义了顺序，也定义了相等。写比较器时最好把能区分的字段都串进去。' },
      { lang: 'java', code: 'import java.util.Comparator;\nimport java.util.PriorityQueue;\n\npublic class PriorityQueueComparator {\n    static class Task {\n        final String name;\n        final int priority;\n        Task(String name, int priority) {\n            this.name = name;\n            this.priority = priority;\n        }\n        @Override public String toString() {\n            return name + "(" + priority + ")";\n        }\n    }\n\n    public static void main(String[] args) {\n        PriorityQueue<Task> pq = new PriorityQueue<>(\n                Comparator.comparingInt((Task t) -> t.priority).reversed());\n\n        pq.offer(new Task("备份", 2));\n        pq.offer(new Task("告警", 9));\n        pq.offer(new Task("日志", 1));\n\n        while (!pq.isEmpty()) {\n            System.out.println(pq.poll());\n        }\n    }\n}', title: 'PriorityQueueComparator.java' },
      { out: '告警(9)\n备份(2)\n日志(1)' },
      { p: '这段代码用 reversed 把默认的小顶堆变成大顶堆，优先级数值越大越先出队。输出顺序是 9、2、1，正好是优先级从高到低。注意 Task 没有实现 Comparable，因为比较规则完全由外部 Comparator 提供，这也是 Comparator 的优势。' },
      { h: '5.10 Top K 与堆的实战' },
      { p: '堆最经典的实战是求 Top K。如果数据量很大，不能全部排序，可以维护一个大小为 K 的堆：求“最大的 K 个”就用小顶堆，堆顶是这 K 个里最小的；每来一个新元素，如果比堆顶大就替换堆顶，然后下沉。最后堆里剩下的就是最大的 K 个。' },
      { p: '为什么求最大 K 个反而用小顶堆？因为堆顶是“当前 K 个里最差的那个”，新元素只要比它好，就有资格进入前 K，把最差的挤出去。如果用大顶堆，堆顶是当前最好的，你无法判断新元素是否该淘汰别人。这个反直觉的搭配是 Top K 的核心。' },
      { p: '复杂度是 O(n log k)，比全排序的 O(n log n) 更优，而且只需要 O(k) 的额外空间。当 k 远小于 n 时，优势非常明显。面试里问“一亿个数找最大的十个”，标准答案就是小顶堆。' },
      { lang: 'java', code: 'import java.util.PriorityQueue;\n\npublic class TopKDemo {\n    public static void main(String[] args) {\n        int[] nums = {3, 2, 1, 5, 6, 4};\n        int k = 3;\n\n        PriorityQueue<Integer> heap = new PriorityQueue<>();\n        for (int n : nums) {\n            heap.offer(n);\n            if (heap.size() > k) {\n                heap.poll();          // 挤掉当前 K 个里最小的\n            }\n        }\n\n        System.out.println("第 " + k + " 大的数: " + heap.peek());\n        System.out.println(heap);\n    }\n}', title: 'TopKDemo.java' },
      { out: '第 3 大的数: 4\n[5, 6, 4]' },
      { p: '遍历过程：前三个 3、2、1 直接进堆；来 5 时堆变成 [2,3,5,1] 并挤掉 2；来 6 时挤掉 3；来 4 时挤掉 4 以下的元素，最终堆里是 4、5、6，堆顶 4 就是第 3 大的数。每一步堆的大小都不超过 k，内存占用很小。' },
      { h: '5.11 常见坑与选型' },
      { p: 'PriorityQueue 的坑比 ArrayList 多，因为它有“堆序”这个隐含约束。很多操作看起来正常，结果却不符合预期，逐条对照可以少走弯路。' },
      { list: [
        '以为遍历 PriorityQueue 会得到有序结果，其实只有 poll 才有顺序。',
        '往 PriorityQueue 里放 null，offer 时直接 NullPointerException。',
        '修改了已经在堆里的元素，却没有重新入堆，堆序被破坏。',
        '用 (a, b) -> b - a 写大顶堆，数值接近 int 边界时溢出。',
        '以为 PriorityQueue 线程安全，多线程 offer 后数据错乱。',
        '用 for-each 遍历时删除，抛 ConcurrentModificationException。',
        '比较器只比较部分字段，导致“相等”的元素顺序不确定。',
        '把 Queue 的 add/remove 用在可能满或空的场景，异常打断流程。'
      ] },
      { p: '第一条最值得展开：PriorityQueue 的 iterator 只是按数组下标顺序遍历，不保证任何优先级顺序。要按优先级取出，必须反复 poll；如果要“看一眼全部有序”，应该先复制一份再排序，或者干脆用 TreeSet。把 PriorityQueue 当有序集合用，是最常见的误用。' },
      { p: 'PriorityQueue 的迭代器是弱一致的：它不检查 modCount，所以遍历时修改堆不会抛 ConcurrentModificationException，但可能看到旧数据、重复数据或漏掉元素。这和 ArrayList 的 fail-fast 不同，原因是堆在调整时元素位置会大幅移动，JDK 选择了不做修改检查。' },
      { p: '第三条也很隐蔽：元素入堆后，如果你修改了它的优先级字段，堆不会自动重排。因为堆只在 offer 和 poll 时调整，平时不做任何检查。正确做法是 remove 掉旧元素再 offer 新的，或者重建堆；更好的做法是让参与排序的字段不可变。' },
      { p: '普通 FIFO 队列首选 ArrayDeque，它比 LinkedList 更快、更省内存，还不允许 null，避免歧义。需要线程安全就用 BlockingQueue 的实现，比如 ArrayBlockingQueue、LinkedBlockingQueue，它们在队列满或空时能阻塞，适合生产者消费者模型。' },
      { p: '栈也用 ArrayDeque，不要用 Stack。需要双端操作时，ArrayDeque 同样胜任。只有当元素需要按优先级出队时才用 PriorityQueue；需要同时支持优先级和并发时用 PriorityBlockingQueue。需要排序且要遍历有序时，用 TreeSet 而不是 PriorityQueue。' },
      { p: '还有一类特殊队列：DelayQueue 按延迟时间出队，SynchronousQueue 不存储元素、配对传递，LinkedTransferQueue 支持转移。它们都属于并发队列，平时用得少，但理解“队列不只是先进先出”这件事，有助于在合适的场景选对工具。' },
      { h: '5.12 本章小结' },
      { list: [
        '增强 for 的本质是 iterator() 加 hasNext/next，Collection 因此都必须实现 Iterable。',
        'Iterator 的游标指向下一个元素，remove 删除最近返回的元素，依赖 lastRet。',
        'fail-fast 靠 modCount 与 expectedModCount 比较，是最佳努力，不是并发安全。',
        'ListIterator 支持双向遍历和 set/add，适合原地修改和从中间向前查找。',
        'Queue 有两组方法：抛异常的 add/remove/element 和返回特殊值的 offer/poll/peek。',
        'ArrayDeque 用循环数组实现，头尾操作 O(1)，既可当队列也可当栈，不允许 null。',
        'PriorityQueue 是数组实现的二叉堆，peek O(1)，offer/poll O(log n)，遍历无序。',
        '求最大 K 个用小顶堆，复杂 O(n log k)；修改堆中元素后必须重新入堆。'
      ] },
      { p: '补充一点：ArrayDeque 的 size 上限是 2 的 30 次方，超过会抛 IllegalStateException。日常用法远达不到这个量级，但如果你拿它做无界缓冲，最好还是加一层限流，避免内存被撑爆。' },
      { h: '5.13 常见追问' },
      { list: [
        '<b>问：fail-fast 能保证一定检测到并发修改吗？</b><br>答：不能，它是「尽力而为」。检测靠的是 modCount 与迭代器保存的期望值是否一致，如果两次检查之间发生了偶数次结构性修改、或者修改恰好发生在下一次 next 之前又被覆盖回来，就可能检测不到；反过来它也可能在单线程下误报，只要你在遍历时绕过了迭代器去改结构。因此它是定位 bug 的辅助手段，不是并发正确性的保证，真正的并发安全要靠 ConcurrentHashMap 这类容器或显式同步。',
        '<b>问：ArrayDeque 为什么比 LinkedList 快？</b><br>答：因为它是可扩容的循环数组，元素紧挨着存放，一趟操作只碰一小片内存，CPU 缓存命中率高；LinkedList 每个元素都是一个独立节点，还要额外持有两个引用，遍历时不断跳指针，缓存几乎每次都失效。此外 ArrayDeque 不需要为每个元素分配对象，内存占用和 GC 压力都更小。它不允许存 null，这一点常被当成缺点，其实是内部用 null 表示空位带来的必要限制。',
        '<b>问：PriorityQueue 是先进先出吗？</b><br>答：不是。它按优先级出队，队头永远是最小元素（默认按自然顺序），与入队先后无关；只有优先级相同时，出队顺序才由内部堆结构决定，并不保证是入队顺序。想要大顶堆就传 <code>Comparator.reverseOrder()</code>。若既要按优先级出队、又要同优先级按入队顺序处理，就在比较器里加一个自增序号做第二关键字，把它变成稳定优先队列。',
        '<b>问：遍历 PriorityQueue 为什么是无序的？</b><br>答：因为它的底层是一个数组形式的二叉堆，只保证「每个父节点不大于它的子节点」这一条局部性质，兄弟之间、不同子树之间没有任何顺序约束。迭代器就是按数组下标从 0 到 size-1 走一遍，看到的自然不是全局有序序列。要得到有序结果只能反复 poll（会破坏原队列），或者先复制一份再逐个取出：<code>new PriorityQueue&lt;&gt;(pq)</code> 的复制是 O(n)。',
        '<b>问：peek 和 poll 有什么区别？空队列时呢？</b><br>答：peek 只读队头不删除，poll 取出队头并删除，两者都返回元素本身；队列为空时都返回 null，而不是抛异常。要抛异常的是另一组方法：element 和 remove 在空时抛 NoSuchElementException。Queue 接口就是这样成对设计的：add/remove/element 失败抛异常，offer/poll/peek 失败返回特殊值。代码里优先用返回特殊值的那组，能少写 try-catch。',
        '<b>问：怎么实现大顶堆？为什么不能写相减？</b><br>答：直接传 <code>Comparator.reverseOrder()</code> 最简洁，也可以用 <code>(a, b) -&gt; b - a</code> 的写法，但那是有害的：两个相差很大的 int 相减会溢出，符号翻转后排序结果完全错误，而且这个 bug 只在特定数值上出现。正确写法是 <code>Integer.compare(b, a)</code> 或 <code>Comparator.comparingInt(x -&gt; -x)</code>（后者对最值仍不安全）。同理，比较 long 或 Double 时也别靠减法。'
      ] },

      { h: '5.14 自测与练习' },
      { ol: [
        '用 Iterator 遍历 ArrayList，删除所有长度小于 2 的字符串，再用 removeIf 重写一遍。<details class="tb-ans"><summary>参考答案</summary><div class="ans-body"><pre class="tb-ans-code" data-lang="java">import java.util.ArrayList;\nimport java.util.Iterator;\nimport java.util.List;\n\npublic class Prune {\n  public static void main(String[] args) {\n    List&lt;String> a = new ArrayList&lt;>(\n        List.of("a", "bb", "c"));\n    Iterator&lt;String> it = a.iterator();\n    while (it.hasNext()) {\n      if (it.next().length() &lt; 2) it.remove();\n    }\n    System.out.println(a);          // [bb]\n    List&lt;String> b = new ArrayList&lt;>(\n        List.of("a", "bb", "c"));\n    b.removeIf(s -> s.length() &lt; 2);\n    System.out.println(b);          // [bb]\n  }\n}</pre><b>要点</b>：删除必须走 it.remove()，直接调 list.remove 会让 modCount 与 expectedModCount 不一致，下一次 next 抛 ConcurrentModificationException；removeIf 内部就是这个写法，能一行解决就别手写循环。</div></details>',
        '用 ListIterator 从后往前遍历一个 List，把所有元素追加到一个新列表。<details class="tb-ans"><summary>参考答案</summary><div class="ans-body"><pre class="tb-ans-code" data-lang="java">import java.util.ArrayList;\nimport java.util.List;\nimport java.util.ListIterator;\n\npublic class Back {\n  public static void main(String[] args) {\n    List&lt;String> src = new ArrayList&lt;>(\n        List.of("a", "b", "c"));\n    List&lt;String> out = new ArrayList&lt;>();\n    ListIterator&lt;String> it = src.listIterator(src.size());\n    while (it.hasPrevious()) out.add(it.previous());\n    System.out.println(out);        // [c, b, a]\n  }\n}</pre><b>要点</b>：反向遍历的游标起点必须是 listIterator(size())，listIterator() 的游标在 0，hasPrevious 立刻为 false；previous() 是先把游标退一格再取值，previousIndex 才是退格后的下标。</div></details>',
        '分别用 ArrayDeque 和 LinkedList 实现同一个队列操作序列，比较代码和性能。<details class="tb-ans"><summary>参考答案</summary><div class="ans-body"><pre class="tb-ans-code" data-lang="java">import java.util.ArrayDeque;\nimport java.util.Deque;\nimport java.util.LinkedList;\n\npublic class QueueTwo {\n  static void run(Deque&lt;String> q) {\n    q.offer("a");\n    q.offer("b");\n    System.out.println(q.poll());\n    q.offer("c");\n    System.out.println(q);\n  }\n\n  public static void main(String[] args) {\n    run(new ArrayDeque&lt;>());\n    run(new LinkedList&lt;>());\n  }\n}</pre><b>要点</b>：同样的队列语义，两者代码一模一样，差别在实现：ArrayDeque 用循环数组、每元素无额外节点；LinkedList 每个元素一个 Node。LinkedList 允许 null 元素而 ArrayDeque 不允许，往 Deque 里放 null 直接 NPE。</div></details>',
        '用 PriorityQueue 实现一个任务调度器，按优先级从高到低输出任务名。<details class="tb-ans"><summary>参考答案</summary><div class="ans-body"><pre class="tb-ans-code" data-lang="java">import java.util.PriorityQueue;\n\npublic class Sched {\n  record Task(String name, int prio) {}\n\n  public static void main(String[] args) {\n    PriorityQueue&lt;Task> q = new PriorityQueue&lt;>(\n        (x, y) -> Integer.compare(y.prio(), x.prio()));\n    q.offer(new Task("备份", 1));\n    q.offer(new Task("告警", 9));\n    q.offer(new Task("巡检", 5));\n    while (!q.isEmpty()) {\n      System.out.println(q.poll().name());\n    }\n  }\n}</pre><b>要点</b>：PriorityQueue 只保证 poll 的顺序，遍历它（for 或 iterator）拿到的是数组内部顺序，不是优先级顺序；比较器写成 y 减 x 才是大顶堆，优先级数字越大的先出。</div></details>',
        '用大小为 k 的小顶堆求数组中第 k 大的元素，并分析时间空间复杂度。<details class="tb-ans"><summary>参考答案</summary><div class="ans-body"><pre class="tb-ans-code" data-lang="java">import java.util.PriorityQueue;\n\npublic class Kth {\n  static Integer kth(int[] a, int k) {\n    PriorityQueue&lt;Integer> q = new PriorityQueue&lt;>();\n    for (int v : a) {\n      q.offer(v);\n      if (q.size() > k) q.poll();\n    }\n    return q.peek();\n  }\n\n  public static void main(String[] args) {\n    System.out.println(kth(new int[] {3, 1, 5, 4, 2}, 2));\n  }\n}</pre><b>要点</b>：堆里只留 k 个候选，堆顶就是第 k 大：时间 O(n log k)、空间 O(k)，比全排序的 O(n log n) 省；k 大于数组长度时返回 null，k 为 0 会得到最大值，边界要自己挡。</div></details>',
        '写代码验证：修改堆中元素的优先级后不重新入堆，poll 的顺序会出错。<details class="tb-ans"><summary>参考答案</summary><div class="ans-body"><pre class="tb-ans-code" data-lang="java">import java.util.PriorityQueue;\n\npublic class MutHeap {\n  static class Job {\n    String name;\n    int prio;\n    Job(String name, int prio) {\n      this.name = name;\n      this.prio = prio;\n    }\n    @Override public String toString() { return name; }\n  }\n\n  public static void main(String[] args) {\n    PriorityQueue&lt;Job> q = new PriorityQueue&lt;>(\n        (x, y) -> Integer.compare(x.prio, y.prio));\n    Job a = new Job("A", 1);\n    q.offer(a);\n    q.offer(new Job("B", 5));\n    q.offer(new Job("C", 9));\n    a.prio = 99;              // 改了，但堆没重排\n    System.out.println(q.poll());   // A，错\n    System.out.println(q.poll());   // B\n  }\n}</pre><b>要点</b>：堆只在 offer/poll 时比较，就地改被比较的字段不会触发上浮或下沉，poll 出来就是错的；正确做法是先 remove 掉、改完再 offer，或者干脆把比较键设成不可变。</div></details>'
      ] }
    ]
  };


T['collections-advanced'] = {
    meta: '本章约 6300 字 · 建议 40 分钟 · 配套红黑树插入流程图与 6 道习题',
    blocks: [
      { h: '6.1 为什么学这三个类' },
      { p: 'HashMap 和 HashSet 解决了“快速查找”，但它们不保证顺序。业务里经常需要“按 key 排序”的 Map：按学号排序的学生表、按时间排序的日志索引、按分数排序的排行榜。每次取出全部条目再排序当然可以，但如果有现成的有序 Map，插入时就维护好顺序，查询和遍历都更自然。TreeMap 就是这样的结构。' },
      { p: 'EnumMap 则是为枚举量身定做的 Map。枚举的数量固定、取值有限，天然适合做数组下标，但直接写数组会丢失类型安全，也容易越界。EnumMap 用枚举的 ordinal 作为下标，既有数组的性能，又有 Map 的接口和类型检查，是“用枚举做状态或分类”时最合适的容器。' },
      { p: 'Properties 是 JDK 里最古老的配置类，几乎每个 Java 项目都间接用过它：Maven 的 pom、Spring 的占位符、日志框架的配置，底层都有类似的键值对思想。它简单、稳定、线程安全，但有编码和历史包袱。理解它的边界，能帮你避免“中文乱码”“配置读不到”这类经典问题。' },
      { p: '这一章三个类各有侧重：TreeMap 讲有序映射和范围查询，EnumMap 讲枚举与数组的结合，Properties 讲配置文件与编码。它们都不难，但细节多，尤其是比较规则和字符集，稍不注意就会踩坑。另外，这三个类在面试中出现频率很高：TreeMap 的红黑树、EnumMap 的 ordinal 下标、Properties 的编码问题，都是常见的追问点。把它们的原理和边界弄清楚，既能写出更合适的代码，也能在需要选型时说出理由，而不是凭感觉挑一个集合。学习时不要只记 API，多问一句“它为什么这样设计”，理解会牢固得多。' },
      { h: '6.2 TreeMap 与红黑树' },
      { p: 'TreeMap 实现了 SortedMap 和 NavigableMap，底层是一棵红黑树。红黑树是一种自平衡的二叉搜索树：左子树的所有 key 都小于根，右子树的所有 key 都大于根，查找时每次比较都能排除一半，所以 get、put、remove 都是 O(log n)。' },
      { p: '普通二叉搜索树在极端情况下会退化成链表，比如按升序插入 1 到 1000，树会变成一条向右的单链，查找退化为 O(n)。红黑树通过给节点染色和旋转，保证从根到叶子的最长路径不超过最短路径的两倍，从而把树高控制在 O(log n)，避免了退化。可以这样理解：红黑树用少量的额外信息（每个节点一位颜色）换来了稳定的对数高度。相比 AVL 树，它的平衡条件更宽松，插入删除时旋转次数更少，因此更适合读写混合的场景；代价是最坏情况下的查找路径略长，但仍然是 O(log n)。Java 的 TreeMap、TreeSet 以及 Linux 内核的很多结构都选择了红黑树，原因就在这里。' },
      { p: '所谓旋转，是指在不破坏二叉搜索树性质的前提下，调整父子关系，把一边的节点“转”到另一边。插入和删除后，红黑树可能违反“红节点不能相邻”“根必须是黑色”等规则，于是通过变色和少量旋转恢复平衡。旋转的次数是常数，所以插入删除仍然是 O(log n)。最后提醒：TreeMap 的排序是在插入时维护的，所以 put 的成本比 HashMap 高，但遍历时不需要额外排序。如果数据是一次性写入、之后只读，而且需要有序输出，TreeMap 很合适；如果数据频繁增删又不需要顺序，HashMap 更划算。理解这个取舍，比记住“TreeMap 慢”这句结论有用得多。' },
      { flow: ['从根节点开始比较 key', 'compare 结果为 0 则覆盖 value', '小于根则进入左子树', '大于根则进入右子树', '走到空位，插入新节点并染红', '违反红黑规则则变色或旋转', 'size 加一，修改计数加一'] },
      { p: '因为要维护顺序，TreeMap 的常数开销比 HashMap 大：每次操作都要比较 log n 次，节点还要存颜色、左右孩子、父节点。数据量小的时候差别不明显，数据量大、且不需要顺序时，HashMap 仍然是更好的选择。' },
      { lang: 'java', code: 'import java.util.TreeMap;\n\npublic class TreeMapBasics {\n    public static void main(String[] args) {\n        TreeMap<String, Integer> scores = new TreeMap<>();\n        scores.put("Tom", 90);\n        scores.put("Amy", 85);\n        scores.put("Bob", 92);\n        scores.put("Amy", 88);        // 键已存在，覆盖\n\n        System.out.println(scores);            // 按 key 升序\n        System.out.println(scores.firstKey());  // Amy\n        System.out.println(scores.lastKey());   // Tom\n        System.out.println(scores.get("Amy"));  // 88\n        System.out.println(scores.size());      // 3\n    }\n}', title: 'TreeMapBasics.java' },
      { out: '{Amy=88, Bob=92, Tom=90}\nAmy\nTom\n88\n3' },
      { p: '输出顺序是 Amy、Bob、Tom，严格按字符串字典序，而不是插入顺序。这就是 TreeMap 和 HashMap 最直观的区别：它的 entrySet、keySet、values 都是有序的，遍历时直接得到排序结果，不需要再调用 sort。' },
      { h: '6.3 NavigableMap 的范围查询' },
      { p: 'TreeMap 实现了 NavigableMap，提供了一组基于顺序的导航方法。firstKey 和 lastKey 取最小、最大的键；floorKey 返回小于等于给定 key 的最大键；ceilingKey 返回大于等于给定 key 的最小键；lowerKey 和 higherKey 则是严格小于、严格大于。这些方法的命名很有规律：带 floor 和 ceiling 的是“包含等于”，带 lower 和 higher 的是“不包含等于”，记住这一点就不会用错。另外，这些方法在找不到符合条件的键时返回 null，而不是抛异常，所以调用后要判空，或者用带默认值的重载。' },
      { p: '除了单点定位，还能取子 Map：headMap(to) 返回小于 to 的部分，tailMap(from) 返回大于等于 from 的部分，subMap(from, to) 返回左闭右开区间。它们都有带 boolean 参数的重载，用来指定是否包含边界。这些子 Map 是视图，修改会互相影响。需要特别注意：子 Map 的区间是“左闭右开”的，subMap(20, 40) 包含 20 但不包含 40，这是 Java 集合区间操作的统一约定。如果你想要闭区间，要么用带 boolean 参数的重载，要么把右端点加一。写分页或时间范围查询时，这个细节经常导致“少一条”的 bug。' },
      { p: '还有 descendingMap 返回倒序视图，firstEntry、lastEntry、pollFirstEntry、pollLastEntry 直接操作首尾条目。做排行榜时，pollLastEntry 可以取出最高分并删除，比先 lastEntry 再 remove 少一次查找。' },
      { lang: 'java', code: 'import java.util.TreeMap;\n\npublic class TreeMapNav {\n    public static void main(String[] args) {\n        TreeMap<Integer, String> map = new TreeMap<>();\n        for (int k : new int[]{10, 20, 30, 40, 50}) {\n            map.put(k, "v" + k);\n        }\n\n        System.out.println(map.floorKey(35));    // 30\n        System.out.println(map.ceilingKey(35));  // 40\n        System.out.println(map.lowerKey(30));    // 20\n        System.out.println(map.higherKey(30));   // 40\n        System.out.println(map.headMap(30));     // 不含 30\n        System.out.println(map.tailMap(30));     // 含 30\n        System.out.println(map.subMap(20, 40));  // 含 20 不含 40\n    }\n}', title: 'TreeMapNav.java' },
      { out: '30\n40\n20\n40\n{10=v10, 20=v20}\n{30=v30, 40=v40, 50=v50}\n{20=v20, 30=v30}' },
      { p: '这套 API 在“按区间统计”“找前驱后继”“分页游标”里非常有用。比如按时间戳存日志，找某一天之前的最后一条，就用 floorKey；找某一天之后的第一条，就用 ceilingKey。用 HashMap 只能全量遍历，复杂度差一个数量级。' },
      { h: '6.4 TreeMap 的比较规则与坑' },
      { p: 'TreeMap 判断两个 key 是否相同，用的不是 equals，而是 compare 或 compareTo 是否返回 0。这一点和 TreeSet 完全一致。如果比较器只比较了 key 的一部分字段，那么“部分相同”的两个 key 会被当成同一个，后放入的覆盖先放入的，数据就这样悄悄丢了。' },
      { p: '自然顺序要求 key 实现 Comparable。String、Integer、LocalDate 都实现了，可以直接用；自定义类如果没有实现 Comparable，又没有传 Comparator，第一次 put 就会抛 ClassCastException。错误信息会说两个对象无法比较，看到它就该补比较器了。另外，key 的可变性也会带来麻烦：如果 key 对象的字段在放入后被修改，导致 hashCode 或比较结果变化，那么它在 TreeMap 里的位置就不再正确，查找可能失败。规则很简单：放入 Map 的 key 应该是不可变对象，或者至少在使用期间不要修改参与比较的字段。' },
      { p: 'TreeMap 不允许 null key。因为插入时要调用 compareTo 或 compare，null 会直接触发 NullPointerException。但 null value 是允许的，这一点和 HashMap 一样。所以 get 返回 null 仍然有歧义，需要 containsKey 区分。' },
      { p: '还有一个契约问题：Comparator 应该与 equals 保持一致。如果 compare 返回 0 但 equals 返回 false，TreeMap 会认为它们是同一个 key，这违反了 Map 的一般语义。JDK 文档明确建议保持一致，否则行为“奇怪但可预测”。写比较器时把能区分的字段都串进去，就能避免这个问题。还有一个小坑：比较器里不要用减法比较两个 int，比如写成 a - b，差值溢出时符号会反转，排序结果直接错乱。正确写法是 Integer.compare(a, b)，长整型用 Long.compare，字符串用 compareTo。这种溢出 bug 在小数据量下很难发现，数据一大就暴露，写比较器时要养成习惯。' },
      { p: 'TreeMap 也不是线程安全的。多线程读写要用 Collections.synchronizedSortedMap 包装，或者直接用 ConcurrentSkipListMap，后者是基于跳表的有序并发 Map，性能比加锁的 TreeMap 更好。' },
      { table: { head: ['实现', '顺序', '底层', 'get/put', 'null 键', '典型场景'], rows: [
        ['HashMap', '不保证', '数组 + 链表 + 红黑树', '平均 O(1)', '允许一个', '通用键值查找'],
        ['LinkedHashMap', '插入顺序或访问顺序', 'HashMap + 双向链表', '平均 O(1)', '允许一个', 'LRU、保留插入顺序'],
        ['TreeMap', '按 key 排序', '红黑树', 'O(log n)', '不允许', '排序、范围查询、排行榜']
      ] } },
      { h: '6.5 EnumMap：为枚举而生' },
      { p: '枚举的特点是“数量固定、取值有限”。一个表示星期的枚举只有 7 个实例，一个表示状态的枚举可能只有 5 个。对这种 key，用哈希表其实有点浪费：计算 hash、处理冲突、扩容，这些工作都可以省掉，因为每个枚举实例都有一个固定的序号 ordinal。' },
      { p: 'EnumMap 正是利用这一点：内部维护一个 Object 数组，长度等于枚举常量的个数，用 key.ordinal() 作为下标直接存取。所以它的 get 和 put 就是一次数组访问，复杂度 O(1)，常数比 HashMap 还小，而且永远不会发生哈希冲突。' },
      { p: '它的迭代顺序也很有特点：按枚举常量的声明顺序，而不是插入顺序。这个顺序由编译器保证，稳定可预测。做状态统计时，输出的顺序天然和枚举定义一致，不需要额外排序，这一点比 HashMap 舒服很多。还要注意，EnumMap 的 key 不能是 null，put(null, ...) 会立刻抛 NullPointerException；而 value 可以为 null，get 返回 null 时同样要用 containsKey 区分“没有这个键”和“值为 null”。这些规则和 HashMap 基本一致，只是 null key 从“允许一个”变成了“完全不允许”。' },
      { p: 'EnumMap 的构造器必须传入枚举的 Class 对象：<code>new EnumMap&lt;&gt;(Level.class)</code>。因为运行时泛型被擦除，EnumMap 需要这个 Class 来创建正确长度的数组，并校验 key 的类型。传错类型会在 put 时抛 ClassCastException。' },
      { lang: 'java', code: 'import java.util.EnumMap;\nimport java.util.Map;\n\npublic class EnumMapDemo {\n    enum Level { LOW, MEDIUM, HIGH }\n\n    public static void main(String[] args) {\n        EnumMap<Level, Integer> count = new EnumMap<>(Level.class);\n        count.put(Level.HIGH, 3);\n        count.put(Level.LOW, 7);\n        count.put(Level.MEDIUM, 5);\n\n        System.out.println(count);\n        for (Map.Entry<Level, Integer> e : count.entrySet()) {\n            System.out.println(e.getKey() + " -> " + e.getValue());\n        }\n        System.out.println(count.get(Level.HIGH));\n    }\n}', title: 'EnumMapDemo.java' },
      { out: '{LOW=7, MEDIUM=5, HIGH=3}\nLOW -> 7\nMEDIUM -> 5\nHIGH -> 3\n3' },
      { p: '注意输出顺序是 LOW、MEDIUM、HIGH，和插入顺序 HIGH、LOW、MEDIUM 完全不同，和枚举声明顺序一致。这正是 EnumMap 的设计：顺序由类型定义决定，而不是由使用者的插入顺序决定。' },
      { p: 'EnumMap 的第一个优势是快。数组下标访问没有哈希计算，也没有链表遍历，比 HashMap 少了很多步骤。第二个优势是省内存：一个 EnumMap 只有一个 Class 引用和一个 Object 数组，不需要 Node 对象和 table 数组，元素少的时候优势明显。从实现上看，EnumMap 的 entrySet 迭代器直接按数组下标从 0 走到 length-1，跳过 null 位置，所以遍历非常快，也不会像 HashMap 那样受桶数量和哈希分布影响。它的 keySet 和 values 也都是这种“按 ordinal 顺序扫描”的视图，行为和数组高度一致。' },
      { p: '第三个优势是类型安全。构造时指定了枚举类型，放入其他类型的 key 会立刻报错，而不是像原始数组那样悄悄接受任意下标。第四个优势是可读性：用枚举做 key，代码里出现的是 Level.HIGH 而不是魔法数字 3。另外，EnumMap 可以安全地和 Collections.unmodifiableMap 组合，得到只读视图；也可以在多线程读、单线程写的场景下使用，只要写操作有同步保护。它的数组结构在序列化时也更紧凑，因为只写实际存在的条目，不会像 HashMap 那样把整个 table 和链表节点都序列化出去。' },
      { p: '限制也很明确：key 必须是同一个枚举类型的实例，不能是 null，不能是别的类型；EnumMap 不是线程安全的；它不能像 HashMap 那样动态扩容，因为数组长度在构造时就固定为枚举常量个数。枚举一旦定义，数量就不会变，所以这个限制反而是优点。' },
      { table: { head: ['维度', 'EnumMap', 'HashMap'], rows: [
        ['底层', 'Object 数组，下标为 ordinal', '数组 + 链表 + 红黑树'],
        ['key 类型', '必须是同一个枚举', '任意对象'],
        ['null key', '不允许', '允许一个'],
        ['顺序', '枚举声明顺序', '不保证'],
        ['性能', '接近数组访问', '平均 O(1)，有哈希开销'],
        ['内存', '一个数组加一个 Class 引用', 'table 加每个 Node']
      ] } },
      { p: '什么时候用 EnumMap？只要 key 是枚举，就优先用它。典型场景包括：按状态统计数量、按类型分组、用枚举代替 switch 做分发、状态机的转移表。它比 HashMap 更快更省，也比数组更安全。' },
      { h: '6.6 Properties：最简单的配置类' },
      { p: 'Properties 继承自 Hashtable，用来表示一组键值对配置。它的 key 和 value 在概念上都是字符串，虽然因为继承关系可以放入其他对象，但强烈不建议这么做：getProperty 会把值强转成 String，放错类型会在读取时抛 ClassCastException。' },
      { p: '最常用的方法是 load、getProperty、setProperty、store。load 从输入流或 Reader 读取配置，getProperty 按键取值并可以给默认值，setProperty 写入，store 把当前配置写回输出流或 Writer。还有 stringPropertyNames 返回所有字符串键的集合。' },
      { p: 'Properties 的格式很简单：每行一个键值对，用等号、冒号或空白分隔；以 # 或 ! 开头的行是注释；行尾的反斜杠表示续行；值里可以用 \\t、\\n、\\r、\\\\ 等转义。它不支持嵌套结构，也不支持数组，只适合扁平的简单配置。需要强调：Properties 的键和值在语义上都是字符串，虽然 put 可以放任意 Object，但 getProperty 会做强转。把整数、布尔值甚至集合塞进去，读取时就会抛 ClassCastException。正确做法是统一用 setProperty 写入字符串，读取时再按需解析。' },
      { lang: 'java', code: 'import java.io.StringReader;\nimport java.util.Properties;\n\npublic class PropertiesLoad {\n    public static void main(String[] args) throws Exception {\n        String text = "# 应用配置\\n"\n                + "app.name=demo\\n"\n                + "app.port=8080\\n"\n                + "app.debug=true\\n";\n\n        Properties props = new Properties();\n        props.load(new StringReader(text));\n\n        System.out.println(props.getProperty("app.name"));\n        System.out.println(props.getProperty("app.port"));\n        System.out.println(props.getProperty("app.debug"));\n        System.out.println(props.getProperty("app.missing"));\n        System.out.println(props.getProperty("app.missing", "默认值"));\n        System.out.println(props.size());\n    }\n}', title: 'PropertiesLoad.java' },
      { out: 'demo\n8080\ntrue\nnull\n默认值\n3' },
      { p: '注意 getProperty 返回的都是 String，即使配置里写的是 8080 或 true，读出来也要自己转成 int 或 boolean。这是 Properties 和现代配置框架最大的区别：它不推断类型，也不支持层级，所有值都是文本。' },
      { h: '6.7 默认值链：配置的分层覆盖' },
      { p: 'Properties 支持“默认值链”：构造时可以传一个父 Properties，getProperty 在当前对象找不到时，会自动去父对象找，父对象再找不到就继续往上，形成一条链。这让“基础配置 + 环境覆盖”变得很简单。' },
      { p: '用法是：先加载 base.properties，再用它作为默认值创建 env.properties 对应的 Properties，后者只需要写差异项。读取时先查 env，查不到回落到 base。这个模式和现代配置框架的 profile 覆盖思路一致，只是 Properties 的实现更原始。默认值链的查找是递归的：当前对象没有，就去默认对象找；默认对象没有，再往它的默认对象找，直到链的尽头。链太长会影响性能，而且容易让人搞不清某个值到底来自哪一层。实践中建议最多两层：基础配置一层，环境覆盖一层。' },
      { p: '注意默认值链只影响读取，不影响写入。setProperty 永远写在当前对象上，不会修改父对象；size 和 keySet 也只反映当前对象自己的条目，不包含从父对象继承来的。理解这一点，才不会在统计配置项时多算或少算。' },
      { h: '6.8 Properties 的坑：编码与常见错误' },
      { p: 'load(InputStream) 按 ISO-8859-1 解码，这是 Properties 规范规定的。也就是说，如果你的配置文件里有中文，用 InputStream 读取会出现乱码，除非文件里的中文被写成 \\uXXXX 形式的 Unicode 转义。这是历史遗留设计，Java 早期没有统一的字符集约定。顺带一提，Java 9 之后 Properties 增加了不少便利方法，但 load 和 store 的编码规则没有变，ISO-8859-1 这条底线依然成立。只要记住“字节流走 Latin-1、字符流走你指定的编码”，遇到乱码就能快速定位是哪个环节出的问题。' },
      { p: '解决办法有两个：一是用 load(Reader) 并指定 UTF-8，比如 <code>new InputStreamReader(in, StandardCharsets.UTF_8)</code>；二是继续用 InputStream，但把中文写成 \\uXXXX。现代项目一般选第一种，可读性更好，也不容易出错。还有一点容易忽略：load 会清空还是合并？答案是合并——它把读到的键值对逐个 put 进当前 Properties，已存在的同名键会被覆盖，其他键保留。所以重复 load 多个文件可以实现“后面的覆盖前面的”，这也是常见的分层配置做法，但顺序必须由你控制。' },
      { p: '写入方向类似：store(OutputStream, comment) 会用 ISO-8859-1 编码，并把非 Latin-1 字符转义成 \\uXXXX；store(Writer, comment) 则把字符直接写进 Writer，是否乱码取决于 Writer 使用的字符集。所以导出配置时，优先用 Writer 并指定 UTF-8。' },
      { lang: 'java', code: 'import java.io.StringWriter;\nimport java.util.Properties;\n\npublic class PropertiesStore {\n    public static void main(String[] args) throws Exception {\n        Properties props = new Properties();\n        props.setProperty("app.name", "demo");\n        props.setProperty("app.port", "8080");\n\n        StringWriter writer = new StringWriter();\n        props.store(writer, "generated");\n        String text = writer.toString();\n\n        System.out.println(text.startsWith("#generated"));\n        System.out.println(text.contains("app.port=8080"));\n        System.out.println(text.contains("app.name=demo"));\n    }\n}', title: 'PropertiesStore.java' },
      { out: 'true\ntrue\ntrue' },
      { p: 'store 会在开头写一行注释，内容是你传入的 comment，再写一行当前时间的说明。这个时间戳会导致每次导出的文件略有不同，如果要做文件比对，记得忽略第一行。保存时如果目标文件已存在，store 会直接覆盖，不会合并。' },
      { p: 'Properties 简单，但历史包袱多。下面这些问题在维护老项目时经常遇到，提前知道能省很多时间。还有一个隐蔽的问题：Properties 继承 Hashtable，所有方法都加了 synchronized，单次操作线程安全，但“先 get 再 put”这种复合操作不是原子的。多线程更新计数时，仍然可能丢更新，需要自己加锁或改用 ConcurrentHashMap 配合原子类。' },
      { list: [
        '用 load(InputStream) 读含中文的配置，出现乱码，应改用 load(Reader) 指定 UTF-8。',
        '把非 String 的值放进 Properties，getProperty 时抛 ClassCastException。',
        '以为 Properties 支持嵌套或数组，实际上它只有扁平的字符串键值对。',
        '直接修改 System.getProperties()，影响整个 JVM，污染其他组件。',
        '在配置文件里用中文注释，读取时按 ISO-8859-1 解码变成乱码。',
        '把 Properties 当成线程安全的共享配置随意修改，读到的值前后不一致。',
        '忘记关闭输入流，文件句柄泄漏，应该用 try-with-resources。',
        '用 store 覆盖原文件时没有备份，配置丢失后无法恢复。'
      ] },
      { p: '其中“修改 System.getProperties”最危险。系统属性是全局的，任何代码都能读到，你改一个值可能影响日志、序列化、网络库的行为。需要临时配置时，自己创建 Properties 实例，不要动全局的那一份。另外，配置文件要放在类路径能被扫描到的位置，用 getResourceAsStream 读取时注意路径以斜杠开头表示从根开始，不以斜杠开头表示相对于当前类。路径写错时返回 null，紧接着的 load 会抛 NullPointerException，报错信息往往看不出真正原因。' },
      { h: '6.9 实战：枚举状态机与配置读取' },
      { p: '把三个类放在一起看，会发现它们分别解决“顺序”“枚举”“配置”三个问题。实际项目里，TreeMap 常用于按时间或 id 排序的索引，EnumMap 常用于状态计数和分发，Properties 常用于读取简单的本地配置。' },
      { p: '举个综合例子：一个订单状态机，状态用枚举表示，转移规则用 EnumMap 存“每个状态可以到达哪些状态”，统计各状态订单数也用 EnumMap；订单按创建时间排序索引用 TreeMap；数据库连接信息用 Properties 读取。四种结构各司其职，代码会很清晰。选型时可以先问三个问题：key 是枚举吗？需要按 key 排序或范围查询吗？配置是扁平的键值对吗？第一个是就用 EnumMap，第二个是就用 TreeMap，第三个是就用 Properties，都不满足就回到 HashMap。把问题问清楚，选择往往只有一种，不需要纠结。' },
      { p: '需要提醒的是，现代项目更常用 YAML、JSON、TOML 或配置中心，Properties 的份额在下降。但理解它仍然有价值：很多框架的底层仍然用它，面试也会问编码问题，而且它是理解“配置即键值对”这个抽象的最小样本。' },
      { h: '6.10 本章小结' },
      { list: [
        'TreeMap 基于红黑树，key 有序，get/put/remove 都是 O(log n)。',
        'TreeMap 用 compare 或 compareTo 判断 key 是否相同，返回 0 就覆盖。',
        'NavigableMap 提供 floorKey、ceilingKey、headMap、subMap 等范围查询能力。',
        'TreeMap 不允许 null key，非线程安全，并发有序场景用 ConcurrentSkipListMap。',
        'EnumMap 用枚举的 ordinal 作数组下标，性能接近数组，顺序等于枚举声明顺序。',
        'EnumMap 的 key 必须是同一种枚举，不允许 null，构造时需传入 Class 对象。',
        'Properties 是扁平的字符串键值配置，load/store 有编码差异，中文要用 Reader/Writer 或转义。',
        'Properties 支持默认值链，适合“基础配置 + 环境覆盖”，但不要修改全局系统属性。'
      ] },
      { h: '6.11 常见追问' },
      { list: [
        '<b>问：TreeMap 和 HashMap 该怎么选？</b><br>答：只有需要「按 key 有序遍历」或「范围查询」时才选 TreeMap，它的 subMap、headMap、tailMap、firstKey、floorKey 这些操作 HashMap 一个都提供不了，而且只能靠全量扫描模拟。其余场景 HashMap 更快：插入与查询均摊 O(1)，而 TreeMap 每次都是 O(log n) 并伴随比较与平衡旋转。另外 TreeMap 的 key 要么实现 Comparable，要么构造时给 Comparator，null 键一律不允许。',
        '<b>问：TreeMap 的 key 能为 null 吗？</b><br>答：不能。第一个元素为 null 时，后续插入要调用 <code>null.compareTo(k)</code>；即使第一个是正常键、后面放入 null，比较器也要拿 null 参与运算，两种情况都会抛 NullPointerException。这与 HashMap 不同——后者把 null 的哈希固定为 0，所以能存放一个 null 键。需要表达「没有键」时用 Optional 或哨兵常量，不要依赖 null 键。',
        '<b>问：EnumMap 为什么快？</b><br>答：它内部就是一个以枚举 ordinal 为下标的普通数组，put 时取 <code>key.ordinal()</code> 直接定位，没有哈希计算、没有扰动、没有冲突链，也不需要扩容与树化，所以读写都接近数组访问的速度。它的迭代顺序固定为枚举常量的声明顺序，天然可预测；构造时还必须显式传入枚举的 Class 对象，用来校验键的类型。代价是键只能来自单一枚举类型，泛型上无法表达「任意枚举」。',
        '<b>问：Properties 读取中文为什么乱码？</b><br>答：<code>load(InputStream)</code> 按 ISO-8859-1 解码，字节被当成单字节字符读入，中文的 UTF-8 多字节序列就被拆成乱码；<code>store(OutputStream)</code> 同理。标准解法是改用 <code>load(Reader)</code>，用 <code>new InputStreamReader(in, StandardCharsets.UTF_8)</code> 明确指定编码；或者维持 ISO-8859-1 并用 <code>\\uXXXX</code> 转义写入，这也是原生 properties 文件的历史约定。',
        '<b>问：Properties 是线程安全的吗？</b><br>答：单个方法安全，复合操作不安全。它继承自 Hashtable，get、put、remove 都是同步方法，但「先 get 判断空、再 put 默认值」这种组合在并发下仍会互相覆盖，可能被覆盖成不同的默认值，也可能读到刚被清理的中间状态。要做原子初始化用 <code>computeIfAbsent</code>（Properties 是 Map 的实现，可以直接用），或者干脆换成不可变的配置对象，在启动阶段一次性构建完再共享。',
        '<b>问：Properties 和 YAML 这类配置格式有什么本质区别？</b><br>答：Properties 只支持扁平的字符串键值与少量分隔符语法，没有层级、没有列表、没有类型，所有值读出来都是 String，需要自己转成 int 或 boolean；层级只能靠点号命名模拟，解析时并不能折叠成结构。YAML 支持嵌套、列表、锚点与类型标注，可读性好得多，但需要第三方库，这与本项目零依赖的原则冲突。所以本地小配置用 Properties 足够，复杂配置值得引入专门的库。'
      ] },

      { h: '6.12 自测与练习' },
      { ol: [
        '用 TreeMap 统计一段文字中每个单词出现的次数，并按单词字典序输出。<details class="tb-ans"><summary>参考答案</summary><div class="ans-body"><pre class="tb-ans-code" data-lang="java">import java.util.Map;\nimport java.util.TreeMap;\n\npublic class WordTree {\n  public static void main(String[] args) {\n    String text = "b a c a";\n    TreeMap&lt;String, Integer> m = new TreeMap&lt;>();\n    for (String w : text.split("\\\\s+")) {\n      m.merge(w, 1, Integer::sum);\n    }\n    System.out.println(m);   // {a=2, b=1, c=1}\n    System.out.println(m.firstKey());\n  }\n}</pre><b>要点</b>：TreeMap 的 keySet/entrySet 遍历本身就是 key 的自然序（或构造时给的 Comparator），不需要再排一次；key 不能为 null，get(null) 直接 NPE。</div></details>',
        '用 TreeMap 实现按分数区间查询：给定 60 到 80，输出该区间内的所有学生。<details class="tb-ans"><summary>参考答案</summary><div class="ans-body"><pre class="tb-ans-code" data-lang="java">import java.util.TreeMap;\n\npublic class RangeQ {\n  public static void main(String[] args) {\n    TreeMap&lt;Integer, String> m = new TreeMap&lt;>();\n    m.put(62, "Ann");\n    m.put(78, "Bob");\n    m.put(80, "Cid");\n    m.put(91, "Dan");\n    System.out.println(m.subMap(60, true, 80, true));\n    System.out.println(m.floorEntry(79));\n    System.out.println(m.higherKey(80));\n  }\n}</pre><b>要点</b>：真按分数当 key 时同分会互相覆盖，要存多人得用 Map&lt;Integer, List&lt;String>>；subMap 返回原表的视图，往区间外写抛 IllegalArgumentException。</div></details>',
        '用 EnumMap 统计一组订单中每个状态的数量，并按枚举声明顺序打印。<details class="tb-ans"><summary>参考答案</summary><div class="ans-body"><pre class="tb-ans-code" data-lang="java">import java.util.EnumMap;\nimport java.util.Map;\n\npublic class Order {\n  enum Status { NEW, PAID, SHIPPED, DONE }\n\n  public static void main(String[] args) {\n    Status[] in = {Status.NEW, Status.PAID, Status.NEW,\n        Status.DONE, Status.PAID, Status.NEW};\n    Map&lt;Status, Integer> m = new EnumMap&lt;>(Status.class);\n    for (Status s : in) m.merge(s, 1, Integer::sum);\n    for (Map.Entry&lt;Status, Integer> e : m.entrySet()) {\n      System.out.println(e);\n    }\n  }\n}</pre><b>要点</b>：EnumMap 用枚举 ordinal 当下标存进数组，遍历顺序恒为枚举声明顺序（不是计数先后），查找不哈希、不比较；构造时必须传 class 对象，key 也不能为 null。</div></details>',
        '用 Properties 读取一个含中文的配置文件，分别用 InputStream 和 Reader 验证编码差异。<details class="tb-ans"><summary>参考答案</summary><div class="ans-body"><pre class="tb-ans-code" data-lang="java">import java.io.ByteArrayInputStream;\nimport java.io.StringReader;\nimport java.nio.charset.StandardCharsets;\nimport java.util.Properties;\n\npublic class Conf {\n  public static void main(String[] args) throws Exception {\n    String text = "name=\\u5f20\\u4e09\\n";\n    Properties a = new Properties();\n    a.load(new ByteArrayInputStream(\n        text.getBytes(StandardCharsets.UTF_8)));\n    System.out.println(a.getProperty("name"));\n    Properties b = new Properties();\n    b.load(new StringReader(text));\n    System.out.println(b.getProperty("name"));\n  }\n}</pre><b>要点</b>：load(InputStream) 规定按 ISO-8859-1 解码，UTF-8 的中文必然乱码两位；要么改用 load(Reader) 配 Files.newBufferedReader(p, UTF_8)，要么把配置文件写成 \\uXXXX 转义。store 反过来也一样：写 OutputStream 会把非 Latin-1 字符转成转义。</div></details>',
        '用 Properties 实现「基础配置 + 环境覆盖」，验证默认值链的查找顺序。<details class="tb-ans"><summary>参考答案</summary><div class="ans-body"><pre class="tb-ans-code" data-lang="java">import java.util.Properties;\n\npublic class Over {\n  public static void main(String[] args) {\n    Properties base = new Properties();\n    base.setProperty("host", "127.0.0.1");\n    base.setProperty("port", "5432");\n    Properties env = new Properties();\n    env.setProperty("port", "6543");\n    Properties all = new Properties(base);\n    all.putAll(env);\n    System.out.println(all.getProperty("host"));\n    System.out.println(all.getProperty("port"));\n    System.out.println(all.getProperty("user", "root"));\n  }\n}</pre><b>要点</b>：getProperty 的查找顺序是「本表 → defaults 链 → getProperty(k, 默认值)」，所以覆盖只要往本表 put，base 不会被污染；defaults 是只读兜底，put 到 all 才有副作用。</div></details>',
        '比较 TreeMap、HashMap、EnumMap 插入十万条数据的时间，并解释差异。<details class="tb-ans"><summary>参考答案</summary><div class="ans-body"><pre class="tb-ans-code" data-lang="java">import java.util.EnumMap;\nimport java.util.HashMap;\nimport java.util.Map;\nimport java.util.Random;\nimport java.util.TreeMap;\n\npublic class Bench {\n  enum K { A, B, C, D }\n\n  static long time(Map&lt;Integer, Integer> m, int[] a) {\n    long t = System.nanoTime();\n    for (int v : a) m.put(v, v);\n    return (System.nanoTime() - t) / 1_000_000;\n  }\n\n  public static void main(String[] args) {\n    Random r = new Random(1);\n    int[] a = new int[100_000];\n    for (int i = 0; i &lt; a.length; i++) a[i] = r.nextInt();\n    long h = time(new HashMap&lt;>(), a);\n    long r2 = time(new TreeMap&lt;>(), a);\n    System.out.println("HashMap " + h);\n    System.out.println("TreeMap " + r2);\n    EnumMap&lt;K, Integer> e = new EnumMap&lt;>(K.class);\n    K[] vs = K.values();\n    long t = System.nanoTime();\n    for (int i = 0; i &lt; 100_000; i++) {\n      e.merge(vs[i % 4], 1, Integer::sum);\n    }\n    long e2 = System.nanoTime() - t;\n    System.out.println("EnumMap " + e2);\n  }\n}</pre><b>要点</b>：HashMap 与 EnumMap 都是均摊 O(1)，EnumMap 更快因为定位是数组下标而不是哈希；TreeMap 每次 O(log n) 还要比较，十万条下通常慢一个数量级。三者 key 类型不同，这个对比只能看量级，别当绝对数字。</div></details>'
      ] }
    ]
  };


})();
